70: /**
71:  * This rule checks if a {@link UnresolvedCallExpression} can work with the given arguments and
72:  * infers the output data type. All function calls are resolved {@link CallExpression} after
73:  * applying this rule.
74:  *
75:  * <p>This rule also resolves {@code flatten()} calls on composite types.
76:  *
77:  * <p>If the call expects different types of arguments, but the given arguments have types that can
78:  * be casted, a {@link BuiltInFunctionDefinitions#CAST} expression is inserted.
79:  *
80:  * <p>It validates and prepares inline, unregistered {@link UserDefinedFunction}s.
81:  */
82: @Internal
83: final class ResolveCallByArgumentsRule implements ResolverRule {
84: 
85:     @Override
86:     public List<Expression> apply(List<Expression> expression, ResolutionContext context) {
87:         // only the top-level expressions may access the output data type
88:         final SurroundingInfo surroundingInfo =
89:                 context.getOutputDataType().map(SurroundingInfo::of).orElse(null);
90:         return expression.stream()
91:                 .flatMap(e -> e.accept(new ResolvingCallVisitor(context, surroundingInfo)).stream())
92:                 .collect(Collectors.toList());
93:     }
94: 
95:     // --------------------------------------------------------------------------------------------
96: 
97:     private static class ResolvingCallVisitor
98:             extends RuleExpressionVisitor<List<ResolvedExpression>> {
99: 
100:         private final @Nullable SurroundingInfo surroundingInfo;
101: 
102:         ResolvingCallVisitor(ResolutionContext context, @Nullable SurroundingInfo surroundingInfo) {
103:             super(context);
104:             this.surroundingInfo = surroundingInfo;
105:         }
106: 
107:         @Override
108:         public List<ResolvedExpression> visit(UnresolvedCallExpression unresolvedCall) {
109:             final FunctionDefinition definition;
110:             // clean functions that were not registered in a catalog
111:             if (!unresolvedCall.getFunctionIdentifier().isPresent()) {
112:                 definition =
113:                         prepareInlineUserDefinedFunction(unresolvedCall.getFunctionDefinition());
114:             } else {
115:                 definition = unresolvedCall.getFunctionDefinition();
116:             }
117: 
118:             final String name =
119:                     unresolvedCall
120:                             .getFunctionIdentifier()
121:                             .map(FunctionIdentifier::toString)
122:                             .orElseGet(definition::toString);
123: 
124:             final Optional<TypeInference> typeInference = getOptionalTypeInference(definition);
125: 
126:             // resolve the children with information from the current call
127:             final List<ResolvedExpression> resolvedArgs = new ArrayList<>();
128:             final int argCount = unresolvedCall.getChildren().size();
129: 
130:             for (int i = 0; i < argCount; i++) {
131:                 final int currentPos = i;
132:                 final SurroundingInfo surroundingInfo =
133:                         typeInference
134:                                 .map(
135:                                         inference ->
136:                                                 SurroundingInfo.of(
137:                                                         name,
138:                                                         definition,
139:                                                         inference,
140:                                                         argCount,
141:                                                         currentPos,
142:                                                         resolutionContext.isGroupedAggregation()))
143:                                 .orElse(null);
144:                 final ResolvingCallVisitor childResolver =
145:                         new ResolvingCallVisitor(resolutionContext, surroundingInfo);
146:                 resolvedArgs.addAll(unresolvedCall.getChildren().get(i).accept(childResolver));
147:             }
148: 
149:             if (definition == BuiltInFunctionDefinitions.FLATTEN) {
150:                 return executeFlatten(resolvedArgs);
151:             }
152: 
153:             return Collections.singletonList(
154:                     typeInference
155:                             .map(
156:                                     newInference ->
157:                                             runTypeInference(
158:                                                     name,
159:                                                     unresolvedCall,
160:                                                     newInference,
161:                                                     resolvedArgs,
162:                                                     surroundingInfo))
163:                             .orElseThrow(
164:                                     () ->
165:                                             new TableException(
166:                                                     "Could not get a type inference for function: "
167:                                                             + name)));
168:         }
169: 
170:         @Override
171:         protected List<ResolvedExpression> defaultMethod(Expression expression) {
172:             if (expression instanceof ResolvedExpression) {
173:                 return Collections.singletonList((ResolvedExpression) expression);
174:             }
175:             throw new TableException("Unexpected unresolved expression: " + expression);
176:         }
177: 
178:         private List<ResolvedExpression> executeFlatten(List<ResolvedExpression> args) {
179:             if (args.size() != 1) {
180:                 throw new ValidationException("Invalid number of arguments for flattening.");
181:             }
182:             final ResolvedExpression composite = args.get(0);
183:             final LogicalType compositeType = composite.getOutputDataType().getLogicalType();
184:             if (hasLegacyTypes(compositeType)) {
185:                 return flattenLegacyCompositeType(composite);
186:             }
187:             return flattenCompositeType(composite);
188:         }
189: 
190:         private List<ResolvedExpression> flattenCompositeType(ResolvedExpression composite) {
191:             final DataType dataType = composite.getOutputDataType();
192:             final LogicalType type = dataType.getLogicalType();
193:             if (!isCompositeType(type)) {
194:                 return singletonList(composite);
195:             }
196:             final List<DataType> fieldDataTypes = DataTypeUtils.flattenToDataTypes(dataType);
197:             final List<String> fieldNames = DataTypeUtils.flattenToNames(dataType);
198:             return IntStream.range(0, fieldDataTypes.size())
199:                     .mapToObj(
200:                             idx -> {
201:                                 final DataType fieldDataType = fieldDataTypes.get(idx);
202:                                 final DataType nullableFieldDataType;
203:                                 if (type.isNullable()) {
204:                                     nullableFieldDataType = fieldDataType.nullable();
205:                                 } else {
206:                                     nullableFieldDataType = fieldDataType;
207:                                 }
208:                                 return resolutionContext
209:                                         .postResolutionFactory()
210:                                         .get(
211:                                                 composite,
212:                                                 valueLiteral(fieldNames.get(idx)),
213:                                                 nullableFieldDataType);
214:                             })
215:                     .collect(Collectors.toList());
216:         }
217: 
218:         private List<ResolvedExpression> flattenLegacyCompositeType(ResolvedExpression composite) {
219:             final TypeInformation<?> resultType =
220:                     fromDataTypeToLegacyInfo(composite.getOutputDataType());
221:             if (!(resultType instanceof CompositeType)) {
222:                 return singletonList(composite);
223:             }
224:             final CompositeType<?> compositeType = (CompositeType<?>) resultType;
225:             return IntStream.range(0, resultType.getArity())
226:                     .mapToObj(
227:                             idx ->
228:                                     resolutionContext
229:                                             .postResolutionFactory()
230:                                             .get(
231:                                                     composite,
232:                                                     valueLiteral(
233:                                                             compositeType.getFieldNames()[idx]),
234:                                                     fromLegacyInfoToDataType(
235:                                                             compositeType.getTypeAt(idx))))
236:                     .collect(Collectors.toList());
237:         }
238: 
239:         /** Temporary method until all calls define a type inference. */
240:         private Optional<TypeInference> getOptionalTypeInference(FunctionDefinition definition) {
241:             final TypeInference inference =
242:                     definition.getTypeInference(resolutionContext.typeFactory());
243:             if (inference.getOutputTypeStrategy() != TypeStrategies.MISSING) {
244:                 return Optional.of(inference);
245:             } else {
246:                 return Optional.empty();
247:             }
248:         }
249: 
250:         private ResolvedExpression runTypeInference(
251:                 String name,
252:                 UnresolvedCallExpression unresolvedCall,
253:                 TypeInference inference,
254:                 List<ResolvedExpression> resolvedArgs,
255:                 @Nullable SurroundingInfo surroundingInfo) {
256: 
257:             final Result inferenceResult =
258:                     TypeInferenceUtil.runTypeInference(
259:                             inference,
260:                             new TableApiCallContext(
261:                                     resolutionContext.typeFactory(),
262:                                     name,
263:                                     unresolvedCall.getFunctionDefinition(),
264:                                     resolvedArgs,
265:                                     resolutionContext.isGroupedAggregation()),
266:                             surroundingInfo);
267: 
268:             final List<ResolvedExpression> adaptedArguments =
269:                     adaptArguments(inferenceResult, resolvedArgs);
270: 
271:             return unresolvedCall.resolve(adaptedArguments, inferenceResult.getOutputDataType());
272:         }
273: 
274:         /** Adapts the arguments according to the properties of the {@link Result}. */
275:         private List<ResolvedExpression> adaptArguments(
276:                 Result inferenceResult, List<ResolvedExpression> resolvedArgs) {
277: 
278:             return IntStream.range(0, resolvedArgs.size())
279:                     .mapToObj(
280:                             pos -> {
281:                                 final ResolvedExpression argument = resolvedArgs.get(pos);
282:                                 final DataType argumentType = argument.getOutputDataType();
283:                                 final DataType expectedType =
284:                                         inferenceResult.getExpectedArgumentTypes().get(pos);
285: 
286:                                 if (!supportsAvoidingCast(
287:                                         argumentType.getLogicalType(),
288:                                         expectedType.getLogicalType())) {
289:                                     return resolutionContext
290:                                             .postResolutionFactory()
291:                                             .cast(argument, expectedType);
292:                                 }
293:                                 return argument;
294:                             })
295:                     .collect(Collectors.toList());
296:         }
297: 
298:         /** Validates and cleans an inline, unregistered {@link UserDefinedFunction}. */
299:         private FunctionDefinition prepareInlineUserDefinedFunction(FunctionDefinition definition) {
300:             if (definition instanceof ScalarFunctionDefinition) {
301:                 final ScalarFunctionDefinition sf = (ScalarFunctionDefinition) definition;
302:                 UserDefinedFunctionHelper.prepareInstance(
303:                         resolutionContext.configuration(), sf.getScalarFunction());
304:                 return new ScalarFunctionDefinition(sf.getName(), sf.getScalarFunction());
305:             } else if (definition instanceof TableFunctionDefinition) {
306:                 final TableFunctionDefinition tf = (TableFunctionDefinition) definition;
307:                 UserDefinedFunctionHelper.prepareInstance(
308:                         resolutionContext.configuration(), tf.getTableFunction());
309:                 return new TableFunctionDefinition(
310:                         tf.getName(), tf.getTableFunction(), tf.getResultType());
311:             } else if (definition instanceof AggregateFunctionDefinition) {
312:                 final AggregateFunctionDefinition af = (AggregateFunctionDefinition) definition;
313:                 UserDefinedFunctionHelper.prepareInstance(
314:                         resolutionContext.configuration(), af.getAggregateFunction());
315:                 return new AggregateFunctionDefinition(
316:                         af.getName(),
317:                         af.getAggregateFunction(),
318:                         af.getResultTypeInfo(),
319:                         af.getAccumulatorTypeInfo());
320:             } else if (definition instanceof TableAggregateFunctionDefinition) {
321:                 final TableAggregateFunctionDefinition taf =
322:                         (TableAggregateFunctionDefinition) definition;
323:                 UserDefinedFunctionHelper.prepareInstance(
324:                         resolutionContext.configuration(), taf.getTableAggregateFunction());
325:                 return new TableAggregateFunctionDefinition(
326:                         taf.getName(),
327:                         taf.getTableAggregateFunction(),
328:                         taf.getResultTypeInfo(),
329:                         taf.getAccumulatorTypeInfo());
330:             } else if (definition instanceof UserDefinedFunction) {
331:                 UserDefinedFunctionHelper.prepareInstance(
332:                         resolutionContext.configuration(), (UserDefinedFunction) definition);
333:             }
334:             return definition;
335:         }
336:     }
337: 
338:     // --------------------------------------------------------------------------------------------
339: 
340:     private static class TableApiCallContext implements CallContext {
341: 
342:         private final DataTypeFactory typeFactory;
343: 
344:         private final String name;
345: 
346:         private final FunctionDefinition definition;
347: 
348:         private final List<ResolvedExpression> resolvedArgs;
349: 
350:         private final boolean isGroupedAggregation;
351: 
352:         public TableApiCallContext(
353:                 DataTypeFactory typeFactory,
354:                 String name,
355:                 FunctionDefinition definition,
356:                 List<ResolvedExpression> resolvedArgs,
357:                 boolean isGroupedAggregation) {
358:             this.typeFactory = typeFactory;
359:             this.name = name;
360:             this.definition = definition;
361:             this.resolvedArgs = resolvedArgs;
362:             this.isGroupedAggregation = isGroupedAggregation;
363:         }
364: 
365:         @Override
366:         public DataTypeFactory getDataTypeFactory() {
367:             return typeFactory;
368:         }
369: 
370:         @Override
371:         public FunctionDefinition getFunctionDefinition() {
372:             return definition;
373:         }
374: 
375:         @Override
376:         public boolean isArgumentLiteral(int pos) {
377:             final ResolvedExpression arg = getArgument(pos);
378:             return arg instanceof ValueLiteralExpression || arg instanceof TypeLiteralExpression;
379:         }
380: 
381:         @Override
382:         public boolean isArgumentNull(int pos) {
383:             Preconditions.checkArgument(
384:                     isArgumentLiteral(pos), "Argument at position %s is not a literal.", pos);
385:             final ResolvedExpression arg = getArgument(pos);
386:             // special case for type literals in Table API only
387:             if (arg instanceof TypeLiteralExpression) {
388:                 return false;
389:             }
390:             final ValueLiteralExpression literal = (ValueLiteralExpression) getArgument(pos);
391:             return literal.isNull();
392:         }
393: 
394:         @Override
395:         @SuppressWarnings("unchecked")
396:         public <T> Optional<T> getArgumentValue(int pos, Class<T> clazz) {
397:             Preconditions.checkArgument(
398:                     isArgumentLiteral(pos), "Argument at position %s is not a literal.", pos);
399:             final ResolvedExpression arg = getArgument(pos);
400:             // special case for type literals in Table API only
401:             if (arg instanceof TypeLiteralExpression) {
402:                 if (!DataType.class.isAssignableFrom(clazz)) {
403:                     return Optional.empty();
404:                 }
405:                 return Optional.of((T) arg.getOutputDataType());
406:             }
407:             final ValueLiteralExpression literal = (ValueLiteralExpression) getArgument(pos);
408:             return literal.getValueAs(clazz);
409:         }
410: 
411:         @Override
412:         public String getName() {
413:             return name;
414:         }
415: 
416:         @Override
417:         public List<DataType> getArgumentDataTypes() {
418:             return resolvedArgs.stream()
419:                     .map(ResolvedExpression::getOutputDataType)
420:                     .collect(Collectors.toList());
421:         }
422: 
423:         @Override
424:         public Optional<DataType> getOutputDataType() {
425:             return Optional.empty();
426:         }
427: 
428:         @Override
429:         public boolean isGroupedAggregation() {
430:             return isGroupedAggregation;
431:         }
432: 
433:         private ResolvedExpression getArgument(int pos) {
434:             if (pos >= resolvedArgs.size()) {
435:                 throw new IndexOutOfBoundsException(
436:                         String.format(
437:                                 "Not enough arguments to access literal at position %d for function '%s'.",
438:                                 pos, name));
439:             }
440:             return resolvedArgs.get(pos);
441:         }
442:     }
443: }
