142:     private void deleteMaterialization(LongPredicate pruningChecker) {
143:         Set<Long> materializationToRemove;
144:         synchronized (lock) {
145:             Set<Long> checkpoints =
146:                     mapToMaterializationId.keySet().stream()
147:                             .filter(pruningChecker::test)
148:                             .collect(Collectors.toSet());
149:             materializationToRemove =
150:                     checkpoints.stream()
151:                             .map(mapToMaterializationId::remove)
152:                             .collect(Collectors.toSet());
153:             materializationToRemove.removeAll(mapToMaterializationId.values());
154:         }
155: 
156:         discardExecutor.execute(
157:                 () ->
158:                         syncDiscardFileForCollection(
159:                                 materializationToRemove.stream()
160:                                         .map(super::getCheckpointDirectory)
161:                                         .collect(Collectors.toList())));
162:     }
