276:             Thread.sleep(100);
277:             Map<String, Object> accumulators = client.getAccumulators(jobID).get();
278: 
279:             boolean allDone = true;
280:             for (Tuple2<String, Integer> acc : expectedAccumulators) {
281:                 Object accumOpt = accumulators.get(acc.f0);
282:                 if (accumOpt == null) {
283:                     allDone = false;
284:                     break;
285:                 }
286: 
287:                 Integer numFinished = (Integer) accumOpt;
