334:     /**
335:      * Tests that the compressed buffer will be decompressed after calling {@link
336:      * SingleInputGate#getNext()}.
337:      */
338:     @ParameterizedTest
339:     @ValueSource(strings = {"LZ4", "LZO", "ZSTD"})
340:     void testGetCompressedBuffer(final String compressionCodec) throws Exception {
341:         int bufferSize = 1024;
342:         BufferCompressor compressor =
343:                 new BufferCompressor(bufferSize, CompressionCodec.valueOf(compressionCodec));
344:         BufferDecompressor decompressor =
345:                 new BufferDecompressor(bufferSize, CompressionCodec.valueOf(compressionCodec));
346: 
347:         try (SingleInputGate inputGate =
348:                 new SingleInputGateBuilder().setBufferDecompressor(decompressor).build()) {
349:             TestInputChannel inputChannel = new TestInputChannel(inputGate, 0);
350: 
351:             MemorySegment segment = MemorySegmentFactory.allocateUnpooledSegment(bufferSize);
352:             for (int i = 0; i < bufferSize; i += 8) {
353:                 segment.putLongLittleEndian(i, i);
354:             }
355:             Buffer uncompressedBuffer = new NetworkBuffer(segment, FreeingBufferRecycler.INSTANCE);
356:             uncompressedBuffer.setSize(bufferSize);
357:             Buffer compressedBuffer = compressor.compressToOriginalBuffer(uncompressedBuffer);
358:             assertThat(compressedBuffer.isCompressed()).isTrue();
359: 
360:             inputChannel.read(compressedBuffer);
361:             inputGate.setInputChannels(inputChannel);
362:             inputGate.notifyChannelNonEmpty(inputChannel);
363: 
364:             Optional<BufferOrEvent> bufferOrEvent = inputGate.getNext();
365:             assertThat(bufferOrEvent.isPresent()).isTrue();
366:             assertThat(bufferOrEvent.get().isBuffer()).isTrue();
367:             ByteBuffer buffer =
368:                     bufferOrEvent
369:                             .get()
370:                             .getBuffer()
371:                             .getNioBufferReadable()
372:                             .order(ByteOrder.LITTLE_ENDIAN);
373:             for (int i = 0; i < bufferSize; i += 8) {
374:                 assertThat(buffer.getLong()).isEqualTo(i);
375:             }
376:         }
377:     }
