618:     /**
619:      * Tests that the release of the input gate is noticed while polling the channels for available
620:      * data.
621:      */
622:     @Test
623:     void testReleaseWhilePollingChannel() throws Exception {
624:         final AtomicReference<Exception> asyncException = new AtomicReference<>();
625: 
626:         // Setup the input gate with a single channel that does nothing
627:         final SingleInputGate inputGate = createInputGate(1);
628: 
629:         InputChannel inputChannel = InputChannelBuilder.newBuilder().buildUnknownChannel(inputGate);
630:         inputGate.setInputChannels(inputChannel);
631: 
632:         // Start the consumer in a separate Thread
633:         Thread asyncConsumer =
634:                 new Thread() {
635:                     @Override
636:                     public void run() {
637:                         try {
638:                             inputGate.getNext();
639:                         } catch (Exception e) {
640:                             asyncException.set(e);
641:                         }
642:                     }
643:                 };
644:         asyncConsumer.start();
645: 
646:         // Wait for blocking queue poll call and release input gate
647:         boolean success = false;
648:         for (int i = 0; i < 50; i++) {
649:             if (asyncConsumer.isAlive()) {
650:                 success = asyncConsumer.getState() == Thread.State.WAITING;
651:             }
652: 
653:             if (success) {
654:                 break;
655:             } else {
656:                 // Retry
657:                 Thread.sleep(100);
658:             }
659:         }
660: 
661:         // Verify that async consumer is in blocking request
662:         assertThat(success).as("Did not trigger blocking buffer request.").isTrue();
663: 
664:         // Release the input gate
665:         inputGate.close();
666: 
667:         // Wait for Thread to finish and verify expected Exceptions. If the
668:         // input gate status is not properly checked during requests, this
669:         // call will never return.
670:         asyncConsumer.join();
671: 
672:         assertThat(asyncException.get()).isNotNull();
673:         assertThat(asyncException.get().getClass()).isEqualTo(IllegalStateException.class);
674:     }
