1236:     private static void verifyBuffersInBufferPool(boolean isPipeline, int subpartitionRandSize)
1237:             throws Exception {
1238:         IntermediateResultPartitionID[] partitionIds =
1239:                 new IntermediateResultPartitionID[] {
1240:                     new IntermediateResultPartitionID(),
1241:                     new IntermediateResultPartitionID(),
1242:                     new IntermediateResultPartitionID()
1243:                 };
1244: 
1245:         IndexRange subpartitionIndexRange = new IndexRange(0, subpartitionRandSize - 1);
1246:         NettyShuffleEnvironmentBuilder nettyShuffleEnvironmentBuilder =
1247:                 new NettyShuffleEnvironmentBuilder();
1248:         Optional<Integer> expectMaxRequiredBuffersPerGate =
1249:                 isPipeline
1250:                         ? Optional.of(
1251:                                 InputGateSpecUtils.DEFAULT_MAX_REQUIRED_BUFFERS_PER_GATE_FOR_STREAM)
1252:                         : Optional.of(
1253:                                 InputGateSpecUtils.DEFAULT_MAX_REQUIRED_BUFFERS_PER_GATE_FOR_BATCH);
1254:         nettyShuffleEnvironmentBuilder.setMaxRequiredBuffersPerGate(
1255:                 expectMaxRequiredBuffersPerGate);
1256:         NettyShuffleEnvironment netEnv = nettyShuffleEnvironmentBuilder.build();
1257: 
1258:         SingleInputGate gate =
1259:                 createSingleInputGate(
1260:                         partitionIds,
1261:                         isPipeline ? ResultPartitionType.PIPELINED : ResultPartitionType.BLOCKING,
1262:                         subpartitionIndexRange,
1263:                         netEnv,
1264:                         ResourceID.generate(),
1265:                         new TestingConnectionManager(),
1266:                         new TestingResultPartitionManager(new NoOpResultSubpartitionView()),
1267:                         partitionIds.length * subpartitionRandSize);
1268:         gate.setup();
1269: 
1270:         for (InputChannel inputChannel : gate.inputChannels()) {
1271:             if (inputChannel instanceof RemoteInputChannel) {
1272:                 assertThat(((RemoteInputChannel) inputChannel).getInitialCredit()).isEqualTo(0);
1273:             }
1274:         }
1275: 
1276:         int targetTotalBuffersPerGate = 2 * partitionIds.length * subpartitionRandSize + 8;
1277:         int requiredFloatingBuffersPerGate;
1278:         int totalFloatingBuffersPerGate;
1279:         if (targetTotalBuffersPerGate >= expectMaxRequiredBuffersPerGate.get()) {
1280:             requiredFloatingBuffersPerGate = expectMaxRequiredBuffersPerGate.get();
1281:             totalFloatingBuffersPerGate = targetTotalBuffersPerGate;
1282:         } else {
1283:             requiredFloatingBuffersPerGate = 1;
1284:             totalFloatingBuffersPerGate = 8;
1285:         }
1286:         assertThat(gate.getBufferPool().getNumberOfRequiredMemorySegments())
1287:                 .isEqualTo(requiredFloatingBuffersPerGate);
1288:         assertThat(gate.getBufferPool().getMaxNumberOfMemorySegments())
1289:                 .isEqualTo(totalFloatingBuffersPerGate);
