690:                                 restoreStateHandles, keyGroupRange, overlapFractionThreshold);
691:                 notImportableHandles.remove(bestStateHandleForInit);
692:                 StateHandleTransferSpec baseSpec =
693:                         new StateHandleTransferSpec(
