730:             RocksDB db,
731:             List<ColumnFamilyHandle> columnFamilyHandles,
732:             List<RegisteredStateMetaInfoBase> registeredStateMetaInfoBases,
733:             Path exportBasePath,
734:             Map<RegisteredStateMetaInfoBase.Key, List<ExportImportFilesMetaData>> resultOutput)
735:             throws RocksDBException, IOException {
