758:                 if (exportedSstFiles != null) {
759:                     int sstFileCount = 0;
760:                     for (FileStatus exportedSstFile : exportedSstFiles) {
761:                         if (exportedSstFile.getPath().getName().endsWith(".sst")) {
762:                             sstFileCount++;
