819:     /**
820:      * Prepares the data for importing by exporting from temporary RocksDB instances. We can only
821:      * import data that does not exceed the target key-groups range and skip state handles that
822:      * exceed their range.
823:      *
824:      * @param exportCfBasePath the base path for the export files.
825:      * @param stateHandleSpecs the state handles to prepare for import.
826:      * @param exportedColumnFamiliesOut output parameter for the metadata of completed exports.
827:      * @param skipped output parameter for state handles that could not be exported because the data
828:      *     exceeded the proclaimed range.
829:      * @return the total key-groups range of the exported data.
830:      * @throws Exception on any export error.
831:      */
832:     private KeyGroupRange exportColumnFamiliesWithSstDataInKeyGroupsRange(
833:             Path exportCfBasePath,
834:             List<StateHandleTransferSpec> stateHandleSpecs,
835:             Map<RegisteredStateMetaInfoBase.Key, List<ExportImportFilesMetaData>>
836:                     exportedColumnFamiliesOut,
837:             List<StateHandleTransferSpec> skipped)
838:             throws Exception {
839: 
840:         logger.info(
841:                 "Starting restore export for backend with range {} in operator {}.",
842:                 keyGroupRange.prettyPrintInterval(),
843:                 operatorIdentifier);
844: 
845:         int minExportKeyGroup = Integer.MAX_VALUE;
846:         int maxExportKeyGroup = Integer.MIN_VALUE;
847:         int index = 0;
848:         for (StateHandleTransferSpec stateHandleSpec : stateHandleSpecs) {
849:             IncrementalRemoteKeyedStateHandle stateHandle = stateHandleSpec.getStateHandle();
850: 
851:             final String logLineSuffix =
852:                     " for state handle at index "
853:                             + index
854:                             + " with proclaimed key-group range "
855:                             + stateHandle.getKeyGroupRange().prettyPrintInterval()
856:                             + " for backend with range "
857:                             + keyGroupRange.prettyPrintInterval()
858:                             + " in operator "
859:                             + operatorIdentifier
860:                             + ".";
861: 
862:             logger.debug("Opening temporary database" + logLineSuffix);
863:             try (ForStIncrementalRestoreOperation.RestoredDBInstance tmpRestoreDBInfo =
864:                     restoreTempDBInstance(stateHandleSpec)) {
865: 
866:                 List<ColumnFamilyHandle> tmpColumnFamilyHandles =
867:                         tmpRestoreDBInfo.columnFamilyHandles;
868: 
869:                 logger.debug("Checking actual keys of sst files" + logLineSuffix);
870: 
871:                 // Check if the data in all SST files referenced in the handle is within the
872:                 // proclaimed key-groups range of the handle.
873:                 ForStIncrementalCheckpointUtils.RangeCheckResult rangeCheckResult =
874:                         checkSstDataAgainstKeyGroupRange(
875:                                 tmpRestoreDBInfo.db,
876:                                 keyGroupPrefixBytes,
877:                                 stateHandle.getKeyGroupRange());
878: 
879:                 logger.info("{}" + logLineSuffix, rangeCheckResult);
880: 
881:                 if (rangeCheckResult.allInRange()) {
882: 
883:                     logger.debug("Start exporting" + logLineSuffix);
884: 
885:                     List<RegisteredStateMetaInfoBase> registeredStateMetaInfoBases =
886:                             tmpRestoreDBInfo.stateMetaInfoSnapshots.stream()
887:                                     .map(RegisteredStateMetaInfoBase::fromMetaInfoSnapshot)
888:                                     .collect(Collectors.toList());
889: 
890:                     // Export all the Column Families and store the result in
891:                     // exportedColumnFamiliesOut
892:                     exportColumnFamilies(
893:                             tmpRestoreDBInfo.db,
894:                             tmpColumnFamilyHandles,
895:                             registeredStateMetaInfoBases,
896:                             exportCfBasePath,
897:                             exportedColumnFamiliesOut);
898: 
899:                     minExportKeyGroup =
900:                             Math.min(
901:                                     minExportKeyGroup,
902:                                     stateHandle.getKeyGroupRange().getStartKeyGroup());
903:                     maxExportKeyGroup =
904:                             Math.max(
905:                                     maxExportKeyGroup,
906:                                     stateHandle.getKeyGroupRange().getEndKeyGroup());
907: 
908:                     logger.debug("Done exporting" + logLineSuffix);
909:                 } else {
910:                     // Actual key range in files exceeds proclaimed range, cannot import. We
911:                     // will copy this handle using a temporary DB later.
912:                     skipped.add(stateHandleSpec);
913:                     logger.debug("Skipped export" + logLineSuffix);
914:                 }
915:             }
916:             ++index;
917:         }
918: 
919:         KeyGroupRange exportedKeyGroupsRange =
920:                 minExportKeyGroup <= maxExportKeyGroup
921:                         ? new KeyGroupRange(minExportKeyGroup, maxExportKeyGroup)
922:                         : KeyGroupRange.EMPTY_KEY_GROUP_RANGE;
923: 
924:         logger.info(
925:                 "Completed restore export for backend with range {} in operator {}. {} exported handles with overall exported range {}. {} Skipped handles: {}.",
926:                 keyGroupRange.prettyPrintInterval(),
927:                 operatorIdentifier,
928:                 stateHandleSpecs.size() - skipped.size(),
929:                 exportedKeyGroupsRange.prettyPrintInterval(),
930:                 skipped.size(),
931:                 skipped);
932: 
933:         return exportedKeyGroupsRange;
934:     }
