76:     private List<GenericContainer<?>> configureTaskManagerContainers(Path tempDirectory) {
77:         List<GenericContainer<?>> taskManagers = new ArrayList<>();
78:         for (int i = 0; i < flinkContainersSettings.getNumTaskManagers(); i++) {
79:             // Configure TaskManager
80:             final Configuration taskManagerConf = new Configuration();
81:             taskManagerConf.addAll(flinkContainersSettings.getFlinkConfig());
82:             final String taskManagerHostName =
83:                     flinkContainersSettings.getTaskManagerHostnamePrefix() + i;
84:             taskManagerConf.set(TaskManagerOptions.HOST, taskManagerHostName);
85:             // Build TaskManager container
86:             final ImageFromDockerfile taskManagerImage;
87:             try {
88:                 taskManagerImage =
89:                         new FlinkImageBuilder()
90:                                 .setTempDirectory(tempDirectory)
91:                                 .setConfiguration(taskManagerConf)
92:                                 .setLogProperties(flinkContainersSettings.getLogProperties())
93:                                 .setBaseImage(flinkContainersSettings.getBaseImage())
94:                                 .asTaskManager()
95:                                 .build();
96:             } catch (ImageBuildException e) {
97:                 throw new RuntimeException("Failed to build TaskManager image", e);
98:             }
99:             taskManagers.add(
100:                     configureContainer(
101:                             new GenericContainer<>(taskManagerImage),
102:                             taskManagerHostName,
103:                             "TaskManager-" + i));
