146:         // Build JobManager
147:         final GenericContainer<?> jobManager = configureJobManagerContainer(imageBuildingTempDir);
148: 
149:         // Build TaskManagers
150:         final List<GenericContainer<?>> taskManagers =
151:                 configureTaskManagerContainers(imageBuildingTempDir);
152: 
153:         // Setup Zookeeper HA
154:         GenericContainer<?> zookeeper = null;
155:         // Mount HA storage to JobManager
156:         if (flinkContainersSettings.isZookeeperHA()) {
157:             zookeeper = configureZookeeperContainer();
158:             createTempDirAndMountToContainer(
159:                     "flink-recovery", flinkContainersSettings.getHaStoragePath(), jobManager);
160:         }
161: 
162:         // Mount checkpoint storage to JobManager
163:         createTempDirAndMountToContainer(
164:                 "flink-checkpoint", flinkContainersSettings.getCheckpointPath(), jobManager);
165: 
166:         return new FlinkContainers(
167:                 jobManager, taskManagers, zookeeper, flinkContainersSettings.getFlinkConfig());
168:     }
169: 
170:     void createTempDirAndMountToContainer(
171:             String tempDirPrefix, String containerPath, GenericContainer<?> container) {
172:         try {
