228:         toBeSerializedConfigObjects.forEach(
229:                 (key, object) -> {
230:                     try {
231:                         InstantiationUtil.writeObjectToConfig(object, this.config, key);
232:                     } catch (IOException e) {
233:                         throw new StreamTaskException(
234:                                 String.format("Could not serialize object for key %s.", key), e);
235:                     }
236:                 });
237:     }
