429:     public <T extends StreamOperatorFactory<?>> T getStreamOperatorFactory(ClassLoader cl) {
430:         try {
431:             checkState(
432:                     !removedKeys.contains(SERIALIZED_UDF),
433:                     String.format("%s has been removed.", SERIALIZED_UDF));
434:             return InstantiationUtil.readObjectFromConfig(this.config, SERIALIZED_UDF, cl);
435:         } catch (ClassNotFoundException e) {
436:             String classLoaderInfo = ClassLoaderUtil.getUserCodeClassLoaderInfo(cl);
437:             boolean loadableDoubleCheck = ClassLoaderUtil.validateClassLoadable(e, cl);
438: 
439:             String exceptionMessage =
440:                     "Cannot load user class: "
441:                             + e.getMessage()
442:                             + "\nClassLoader info: "
443:                             + classLoaderInfo
444:                             + (loadableDoubleCheck
445:                                     ? "\nClass was actually found in classloader - deserialization issue."
446:                                     : "\nClass not resolvable through given classloader.");
447: 
448:             throw new StreamTaskException(exceptionMessage, e);
449:         } catch (Exception e) {
450:             throw new StreamTaskException("Cannot instantiate user function.", e);
451:         }
452:     }
