380:     private void triggerCheckpointWaitForFinish(
381:             StreamTaskMailboxTestHarness<Integer> testHarness,
382:             long checkpointId,
383:             CheckpointOptions checkpointOptions)
384:             throws Exception {
385:         // Trigger a checkpoint.
386:         testHarness.taskStateManager.getWaitForReportLatch().reset();
387:         CheckpointMetaData checkpointMetaData = new CheckpointMetaData(checkpointId, checkpointId);
388:         Future<Boolean> checkpointFuture =
389:                 testHarness
390:                         .getStreamTask()
391:                         .triggerCheckpointAsync(checkpointMetaData, checkpointOptions);
392: 
393:         // Wait until the checkpoint finishes.
394:         // We have to mark the source reader as available here, otherwise the runMailboxStep() call
395:         // after
396:         // checkpoint is completed will block.
397:         getSourceReaderFromTask(testHarness).markAvailable();
398:         processUntil(testHarness, checkpointFuture::isDone);
399:         Future<Void> checkpointNotified =
400:                 testHarness.getStreamTask().notifyCheckpointCompleteAsync(checkpointId);
401:         processUntil(testHarness, checkpointNotified::isDone);
402:         testHarness.taskStateManager.getWaitForReportLatch().await();
403:     }
