484:     /**
485:      * This method checks the written TaskManager and JobManager log files for exceptions.
486:      *
487:      * <p>WARN: Please make sure the tool doesn't find old logfiles from previous test runs. So
488:      * always run "mvn clean" before running the tests here.
489:      */
490:     public static void ensureNoProhibitedStringInLogFiles(
491:             final String[] prohibited, final Pattern[] whitelisted) {
492:         File cwd =
493:                 new File(
494:                         GenericTestUtils.getTestDir(),
495:                         YARN_CONFIGURATION.get(TEST_CLUSTER_NAME_KEY));
496:         assertThat(cwd).exists();
497:         assertThat(cwd).isDirectory();
498: 
499:         List<String> prohibitedExcerpts = new ArrayList<>();
500:         File foundFile =
501:                 TestUtils.findFile(
502:                         cwd.getAbsolutePath(),
503:                         new FilenameFilter() {
504:                             @Override
505:                             public boolean accept(File dir, String name) {
506:                                 // scan each file for prohibited strings.
507:                                 File logFile = new File(dir.getAbsolutePath() + "/" + name);
508:                                 try {
509:                                     BufferingScanner scanner =
510:                                             new BufferingScanner(new Scanner(logFile), 10);
511:                                     while (scanner.hasNextLine()) {
512:                                         final String lineFromFile = scanner.nextLine();
513:                                         for (String aProhibited : prohibited) {
514:                                             if (lineFromFile.contains(aProhibited)) {
515: 
516:                                                 boolean whitelistedFound = false;
517:                                                 for (Pattern whitelistPattern : whitelisted) {
518:                                                     Matcher whitelistMatch =
519:                                                             whitelistPattern.matcher(lineFromFile);
520:                                                     if (whitelistMatch.find()) {
521:                                                         whitelistedFound = true;
522:                                                         break;
523:                                                     }
524:                                                 }
525: 
526:                                                 if (!whitelistedFound) {
527:                                                     // logging in FATAL to see the actual message in
528:                                                     // CI tests.
529:                                                     Marker fatal = MarkerFactory.getMarker("FATAL");
530:                                                     LOG.error(
531:                                                             fatal,
532:                                                             "Prohibited String '{}' in '{}:{}'",
533:                                                             aProhibited,
534:                                                             logFile.getAbsolutePath(),
535:                                                             lineFromFile);
536: 
537:                                                     StringBuilder logExcerpt = new StringBuilder();
538: 
539:                                                     logExcerpt.append(System.lineSeparator());
540: 
541:                                                     // include some previous lines in case of
542:                                                     // irregular formatting
543:                                                     for (String previousLine :
544:                                                             scanner.getPreviousLines()) {
545:                                                         logExcerpt.append(previousLine);
546:                                                         logExcerpt.append(System.lineSeparator());
547:                                                     }
548: 
549:                                                     logExcerpt.append(lineFromFile);
550:                                                     logExcerpt.append(System.lineSeparator());
551:                                                     // extract potential stack trace from log
552:                                                     while (scanner.hasNextLine()) {
553:                                                         String line = scanner.nextLine();
554:                                                         logExcerpt.append(line);
555:                                                         logExcerpt.append(System.lineSeparator());
556:                                                         if (line.isEmpty()
557:                                                                 || (!Character.isWhitespace(
558:                                                                                 line.charAt(0))
559:                                                                         && !line.startsWith(
560:                                                                                 "Caused by"))) {
561:                                                             // the cause has been printed, now add a
562:                                                             // few more lines in case of irregular
563:                                                             // formatting
564:                                                             for (int x = 0;
565:                                                                     x < 10 && scanner.hasNextLine();
566:                                                                     x++) {
567:                                                                 logExcerpt.append(
568:                                                                         scanner.nextLine());
569:                                                                 logExcerpt.append(
570:                                                                         System.lineSeparator());
571:                                                             }
572:                                                             break;
573:                                                         }
574:                                                     }
575:                                                     prohibitedExcerpts.add(logExcerpt.toString());
576: 
577:                                                     return true;
578:                                                 }
579:                                             }
580:                                         }
581:                                     }
582:                                 } catch (FileNotFoundException e) {
583:                                     LOG.warn(
584:                                             "Unable to locate file: "
585:                                                     + e.getMessage()
586:                                                     + " file: "
587:                                                     + logFile.getAbsolutePath());
588:                                 }
589: 
590:                                 return false;
591:                             }
592:                         });
593:         if (foundFile != null) {
594:             Scanner scanner = null;
595:             try {
596:                 scanner = new Scanner(foundFile);
597:             } catch (FileNotFoundException e) {
598:                 fail(
599:                         "Unable to locate file: "
600:                                 + e.getMessage()
601:                                 + " file: "
602:                                 + foundFile.getAbsolutePath());
603:             }
604:             LOG.warn("Found a file with a prohibited string. Printing contents:");
605:             while (scanner.hasNextLine()) {
606:                 LOG.warn("LINE: " + scanner.nextLine());
607:             }
608:             fail(
609:                     "Found a file "
610:                             + foundFile
611:                             + " with a prohibited string (one of "
612:                             + Arrays.toString(prohibited)
613:                             + "). "
614:                             + "Excerpts:"
615:                             + System.lineSeparator()
616:                             + prohibitedExcerpts);
617:         }
618:     }
