256:     private Map<ExecutionSlotSharingGroup, SharedSlot> allocateSharedSlots(
257:             Set<ExecutionSlotSharingGroup> executionSlotSharingGroups,
258:             SharedSlotProfileRetriever sharedSlotProfileRetriever) {
259: 
260:         List<PhysicalSlotRequest> slotRequests = new ArrayList<>();
261:         Map<ExecutionSlotSharingGroup, SharedSlot> allocatedSlots = new HashMap<>();
262: 
263:         Map<SlotRequestId, ExecutionSlotSharingGroup> requestToGroup = new HashMap<>();
264:         Map<SlotRequestId, ResourceProfile> requestToPhysicalResources = new HashMap<>();
265: 
266:         for (ExecutionSlotSharingGroup group : executionSlotSharingGroups) {
267:             SlotRequestId physicalSlotRequestId = new SlotRequestId();
268:             ResourceProfile physicalSlotResourceProfile = getPhysicalSlotResourceProfile(group);
269:             SlotProfile slotProfile =
270:                     sharedSlotProfileRetriever.getSlotProfile(group, physicalSlotResourceProfile);
271:             PhysicalSlotRequest request =
272:                     new PhysicalSlotRequest(
273:                             physicalSlotRequestId, slotProfile, slotWillBeOccupiedIndefinitely);
274:             slotRequests.add(request);
275:             requestToGroup.put(physicalSlotRequestId, group);
276:             requestToPhysicalResources.put(physicalSlotRequestId, physicalSlotResourceProfile);
277:         }
278: 
279:         Map<SlotRequestId, CompletableFuture<PhysicalSlotRequest.Result>> allocateResult =
280:                 slotProvider.allocatePhysicalSlots(slotRequests);
281: 
282:         allocateResult.forEach(
283:                 (slotRequestId, resultCompletableFuture) -> {
284:                     ExecutionSlotSharingGroup group = requestToGroup.get(slotRequestId);
285:                     CompletableFuture<PhysicalSlot> physicalSlotFuture =
286:                             resultCompletableFuture.thenApply(
287:                                     PhysicalSlotRequest.Result::getPhysicalSlot);
288:                     SharedSlot slot =
289:                             new SharedSlot(
290:                                     slotRequestId,
291:                                     requestToPhysicalResources.get(slotRequestId),
292:                                     group,
293:                                     physicalSlotFuture,
294:                                     slotWillBeOccupiedIndefinitely,
295:                                     this::releaseSharedSlot);
296:                     allocatedSlots.put(group, slot);
297:                     Preconditions.checkState(!sharedSlots.containsKey(group));
298:                     sharedSlots.put(group, slot);
299:                 });
300:         return allocatedSlots;
301:     }
