303:     private void releaseSharedSlot(ExecutionSlotSharingGroup executionSlotSharingGroup) {
304:         SharedSlot slot = sharedSlots.remove(executionSlotSharingGroup);
305:         Preconditions.checkNotNull(slot);
306:         Preconditions.checkState(
307:                 slot.isEmpty(),
308:                 "Trying to remove a shared slot with physical request id %s which has assigned logical slots",
309:                 slot.getPhysicalSlotRequestId());
310:         slotProvider.cancelSlotRequest(
311:                 slot.getPhysicalSlotRequestId(),
312:                 new FlinkException(
313:                         "Slot is being returned from SlotSharingExecutionSlotAllocator."));
314:     }
