243:     private Map<ExecutionSlotSharingGroup, SharedSlot> tryAssignExistingSharedSlots(
244:             Set<ExecutionSlotSharingGroup> executionSlotSharingGroups) {
245:         Map<ExecutionSlotSharingGroup, SharedSlot> assignedSlots =
246:                 new HashMap<>(executionSlotSharingGroups.size());
247:         for (ExecutionSlotSharingGroup group : executionSlotSharingGroups) {
248:             SharedSlot sharedSlot = sharedSlots.get(group);
249:             if (sharedSlot != null) {
250:                 assignedSlots.put(group, sharedSlot);
251:             }
252:         }
253:         return assignedSlots;
254:     }
