329:     private SharingPhysicalSlotRequestBulk createBulk(
330:             Map<ExecutionSlotSharingGroup, SharedSlot> slots,
331:             Map<ExecutionSlotSharingGroup, List<ExecutionVertexID>> executions) {
332:         Map<ExecutionSlotSharingGroup, ResourceProfile> pendingRequests =
333:                 executions.keySet().stream()
334:                         .collect(
335:                                 Collectors.toMap(
336:                                         group -> group,
337:                                         group ->
338:                                                 slots.get(group).getPhysicalSlotResourceProfile()));
339:         SharingPhysicalSlotRequestBulk bulk =
340:                 new SharingPhysicalSlotRequestBulk(
341:                         executions, pendingRequests, this::cancelLogicalSlotRequest);
342:         registerPhysicalSlotRequestBulkCallbacks(slots, executions.keySet(), bulk);
343:         return bulk;
344:     }
345: 
346:     private static void registerPhysicalSlotRequestBulkCallbacks(
347:             Map<ExecutionSlotSharingGroup, SharedSlot> slots,
348:             Iterable<ExecutionSlotSharingGroup> executions,
349:             SharingPhysicalSlotRequestBulk bulk) {
350:         for (ExecutionSlotSharingGroup group : executions) {
351:             CompletableFuture<PhysicalSlot> slotContextFuture =
352:                     slots.get(group).getSlotContextFuture();
353:             slotContextFuture.thenAccept(
354:                     physicalSlot -> bulk.markFulfilled(group, physicalSlot.getAllocationId()));
355:             slotContextFuture.exceptionally(
356:                     t -> {
357:                         // clear the bulk to stop the fulfillability check
358:                         bulk.clearPendingRequests();
359:                         return null;
360:                     });
361:         }
362:     }
