476:     public void connectToPredecessors(
477:             Map<IntermediateDataSetID, IntermediateResult> intermediateDataSets)
478:             throws JobException {
479:         checkState(isInitialized());
480: 
481:         List<JobEdge> inputs = jobVertex.getInputs();
482: 
483:         if (LOG.isDebugEnabled()) {
484:             LOG.debug(
485:                     String.format(
486:                             "Connecting ExecutionJobVertex %s (%s) to %d predecessors.",
487:                             jobVertex.getID(), jobVertex.getName(), inputs.size()));
488:         }
489: 
490:         for (int num = 0; num < inputs.size(); num++) {
491:             JobEdge edge = inputs.get(num);
492: 
493:             if (LOG.isDebugEnabled()) {
494:                 if (edge.getSource() == null) {
495:                     LOG.debug(
496:                             String.format(
497:                                     "Connecting input %d of vertex %s (%s) to intermediate result referenced via ID %s.",
498:                                     num,
499:                                     jobVertex.getID(),
500:                                     jobVertex.getName(),
501:                                     edge.getSourceId()));
502:                 } else {
503:                     LOG.debug(
504:                             String.format(
505:                                     "Connecting input %d of vertex %s (%s) to intermediate result referenced via predecessor %s (%s).",
506:                                     num,
507:                                     jobVertex.getID(),
508:                                     jobVertex.getName(),
509:                                     edge.getSource().getProducer().getID(),
510:                                     edge.getSource().getProducer().getName()));
511:                 }
512:             }
513: 
514:             // fetch the intermediate result via ID. if it does not exist, then it either has not
515:             // been created, or the order
516:             // in which this method is called for the job vertices is not a topological order
517:             IntermediateResult ires = intermediateDataSets.get(edge.getSourceId());
518:             if (ires == null) {
519:                 throw new JobException(
520:                         "Cannot connect this job graph to the previous graph. No previous intermediate result found for ID "
521:                                 + edge.getSourceId());
522:             }
523: 
524:             this.inputs.add(ires);
525: 
526:             EdgeManagerBuildUtil.connectVertexToResult(this, ires);
527:         }
528:     }
