209:             this.producedDataSets[i] =
210:                     new IntermediateResult(
211:                             result,
212:                             this,
213:                             this.parallelismInfo.getParallelism(),
214:                             result.getResultType());
215:         }
216: 
217:         // create all task vertices
218:         for (int i = 0; i < this.parallelismInfo.getParallelism(); i++) {
219:             ExecutionVertex vertex =
220:                     createExecutionVertex(
221:                             this,
222:                             i,
223:                             producedDataSets,
