68:         this(primaryOutputStream, secondaryOutputStream, DEFAULT_BUFFER_SIZER);
69:     }
70: 
71:     public DuplicatingCheckpointOutputStream(
72:             CheckpointStateOutputStream primaryOutputStream,
73:             CheckpointStateOutputStream secondaryOutputStream,
74:             int bufferSize)
75:             throws IOException {
76: 
77:         this.primaryOutputStream = Preconditions.checkNotNull(primaryOutputStream);
78:         this.secondaryOutputStream = Preconditions.checkNotNull(secondaryOutputStream);
79: 
80:         this.buffer = new byte[bufferSize];
81:         this.bufferIdx = 0;
82: 
83:         this.secondaryStreamException = null;
84: 
85:         checkForAlignedStreamPositions();
86:     }
87: 
88:     @Override
89:     public void write(int b) throws IOException {
90: 
91:         if (buffer.length <= bufferIdx) {
92:             flushInternalBuffer();
93:         }
94: 
95:         buffer[bufferIdx] = (byte) b;
96:         ++bufferIdx;
97:     }
98: 
99:     @Override
100:     public void write(byte[] b) throws IOException {
101: 
102:         write(b, 0, b.length);
103:     }
104: 
105:     @Override
106:     public void write(byte[] b, int off, int len) throws IOException {
107: 
108:         if (buffer.length <= len) {
109: 
110:             flushInternalBuffer();
111:             writeThroughInternal(b, off, len);
112:         } else {
113: 
114:             if (buffer.length < len + bufferIdx) {
115:                 flushInternalBuffer();
116:             }
117: 
118:             System.arraycopy(b, off, buffer, bufferIdx, len);
119:             bufferIdx += len;
120:         }
121:     }
122: 
123:     @Override
124:     public long getPos() throws IOException {
125:         final long referencePos = primaryOutputStream.getPos();
126:         return referencePos + bufferIdx;
127:     }
128: 
129:     @Override
130:     public void flush() throws IOException {
131: 
132:         flushInternalBuffer();
133:         primaryOutputStream.flush();
134: 
135:         if (secondaryStreamException == null) {
136:             try {
137:                 secondaryOutputStream.flush();
138:             } catch (Exception flushEx) {
139:                 handleSecondaryStreamOnException(flushEx);
140:             }
141:         }
142:     }
143: 
144:     @Override
145:     public void sync() throws IOException {
146: 
147:         flushInternalBuffer();
148:         primaryOutputStream.sync();
149: 
150:         if (secondaryStreamException == null) {
151:             try {
152:                 secondaryOutputStream.sync();
153:             } catch (Exception syncEx) {
154:                 handleSecondaryStreamOnException(syncEx);
155:             }
156:         }
157:     }
158: 
159:     @Override
160:     public void close() throws IOException {
161: 
162:         Exception exCollector = null;
163: 
164:         try {
165:             flushInternalBuffer();
166:         } catch (Exception flushEx) {
167:             exCollector = flushEx;
168:         }
169: 
170:         try {
171:             primaryOutputStream.close();
172:         } catch (Exception closeEx) {
173:             exCollector = ExceptionUtils.firstOrSuppressed(closeEx, exCollector);
174:         }
175: 
176:         if (secondaryStreamException == null) {
177:             try {
178:                 secondaryOutputStream.close();
179:             } catch (Exception closeEx) {
180:                 handleSecondaryStreamOnException(closeEx);
181:             }
182:         }
183: 
184:         if (exCollector != null) {
185:             throw new IOException("Exception while closing duplicating stream.", exCollector);
186:         }
187:     }
188: 
189:     private void checkForAlignedStreamPositions() throws IOException {
190: 
191:         if (secondaryStreamException != null) {
192:             return;
193:         }
194: 
195:         final long primaryPos = primaryOutputStream.getPos();
196: 
197:         try {
198:             final long secondaryPos = secondaryOutputStream.getPos();
199: 
200:             if (primaryPos != secondaryPos) {
201:                 handleSecondaryStreamOnException(
202:                         new IOException(
203:                                 "Stream positions are out of sync between primary stream and secondary stream. "
204:                                         + "Reported positions are "
205:                                         + primaryPos
206:                                         + " (primary) and "
207:                                         + secondaryPos
208:                                         + " (secondary)."));
209:             }
210:         } catch (Exception posEx) {
211:             handleSecondaryStreamOnException(posEx);
212:         }
213:     }
214: 
215:     private void flushInternalBuffer() throws IOException {
216: 
217:         if (bufferIdx > 0) {
218:             writeThroughInternal(buffer, 0, bufferIdx);
219:             bufferIdx = 0;
220:         }
221:     }
222: 
223:     private void writeThroughInternal(byte[] b, int off, int len) throws IOException {
224: 
225:         primaryOutputStream.write(b, off, len);
226: 
227:         if (secondaryStreamException == null) {
228:             try {
229:                 secondaryOutputStream.write(b, off, len);
230:             } catch (Exception writeEx) {
231:                 handleSecondaryStreamOnException(writeEx);
232:             }
233:         }
234:     }
235: 
236:     private void handleSecondaryStreamOnException(Exception ex) {
237: 
238:         Preconditions.checkState(
239:                 secondaryStreamException == null,
240:                 "Secondary stream already failed from previous exception!");
241: 
242:         try {
243:             secondaryOutputStream.close();
244:         } catch (Exception closeEx) {
245:             ex = ExceptionUtils.firstOrSuppressed(closeEx, ex);
246:         }
247: 
248:         secondaryStreamException = Preconditions.checkNotNull(ex);
249:     }
250: 
251:     @Nullable
252:     @Override
253:     public StreamStateHandle closeAndGetHandle() throws IOException {
254:         return closeAndGetPrimaryHandle();
255:     }
256: 
257:     /** Returns the state handle from the {@link #primaryOutputStream}. */
258:     public StreamStateHandle closeAndGetPrimaryHandle() throws IOException {
259:         flushInternalBuffer();
260:         return primaryOutputStream.closeAndGetHandle();
261:     }
262: 
263:     /**
264:      * Returns the state handle from the {@link #secondaryOutputStream}. Also reports suppressed
265:      * exceptions from earlier interactions with that stream.
266:      */
267:     public StreamStateHandle closeAndGetSecondaryHandle() throws IOException {
268:         if (secondaryStreamException == null) {
269:             flushInternalBuffer();
270:             return secondaryOutputStream.closeAndGetHandle();
271:         } else {
272:             throw new IOException(
273:                     "Secondary stream previously failed exceptionally", secondaryStreamException);
274:         }
275:     }
276: 
277:     public Exception getSecondaryStreamException() {
278:         return secondaryStreamException;
279:     }
280: 
281:     @VisibleForTesting
282:     CheckpointStateOutputStream getPrimaryOutputStream() {
283:         return primaryOutputStream;
284:     }
285: 
286:     @VisibleForTesting
287:     CheckpointStateOutputStream getSecondaryOutputStream() {
288:         return secondaryOutputStream;
289:     }
290: }
