145:         checkArgument(source.hasRemaining(), "Cannot append empty data.");
146:         checkState(!isFinished, "Sort buffer is already finished.");
147:         checkState(!isReleased, "Sort buffer is already released.");
148: 
149:         int totalBytes = source.remaining();
150:         if (dataType.isBuffer()) {
151:             writeRecord(source, targetSubpartition);
152:         } else {
153:             writeEvent(source, targetSubpartition, dataType);
154:         }
