247:         final List<MemorySegment> memory;
248:         if (this.memorySegments != null) {
249:             memory = this.memorySegments;
250:         } else {
251:             memory =
252:                     memoryManager.allocatePages(
253:                             parentTask, memoryManager.computeNumberOfPages(memoryFraction));
254:         }
255: 
256:         // adjust the memory quotas to the page size
257:         final int numPagesTotal = memory.size();
258: 
259:         if (numPagesTotal < MIN_NUM_WRITE_BUFFERS + MIN_NUM_SORT_MEM_SEGMENTS) {
260:             throw new IllegalArgumentException(
261:                     "Too little memory provided to sorter to perform task. "
262:                             + "Required are at least "
263:                             + (MIN_NUM_WRITE_BUFFERS + MIN_NUM_SORT_MEM_SEGMENTS)
264:                             + " pages. Current page size is "
265:                             + memoryManager.getPageSize()
266:                             + " bytes.");
267:         }
268: 
269:         // determine how many buffers to use for writing
270:         final int numWriteBuffers;
271:         final int numLargeRecordBuffers;
272: 
273:         if (noSpillingMemory && !handleLargeRecords) {
274:             numWriteBuffers = 0;
275:             numLargeRecordBuffers = 0;
276:         } else {
277:             int numConsumers = (noSpillingMemory ? 0 : 1) + (handleLargeRecords ? 2 : 0);
278: 
279:             // determine how many buffers we have when we do a full merge with maximal fan-in
280:             final int minBuffersForMerging =
281:                     maxNumFileHandles + numConsumers * MIN_NUM_WRITE_BUFFERS;
282: 
283:             if (minBuffersForMerging > numPagesTotal) {
284:                 numWriteBuffers = noSpillingMemory ? 0 : MIN_NUM_WRITE_BUFFERS;
285:                 numLargeRecordBuffers = handleLargeRecords ? 2 * MIN_NUM_WRITE_BUFFERS : 0;
286: 
287:                 maxNumFileHandles = numPagesTotal - numConsumers * MIN_NUM_WRITE_BUFFERS;
288:                 if (LOG.isDebugEnabled()) {
289:                     LOG.debug(
290:                             "Reducing maximal merge fan-in to "
291:                                     + maxNumFileHandles
292:                                     + " due to limited memory availability during merge");
293:                 }
294:             } else {
295:                 // we are free to choose. make sure that we do not eat up too much memory for
296:                 // writing
297:                 final int fractionalAuxBuffers = numPagesTotal / (numConsumers * 100);
298: 
299:                 if (fractionalAuxBuffers >= MAX_NUM_WRITE_BUFFERS) {
300:                     numWriteBuffers = noSpillingMemory ? 0 : MAX_NUM_WRITE_BUFFERS;
301:                     numLargeRecordBuffers = handleLargeRecords ? 2 * MAX_NUM_WRITE_BUFFERS : 0;
302:                 } else {
303:                     numWriteBuffers =
304:                             noSpillingMemory
305:                                     ? 0
306:                                     : Math.max(
307:                                             MIN_NUM_WRITE_BUFFERS,
308:                                             fractionalAuxBuffers); // at least the lower bound
309: 
310:                     numLargeRecordBuffers = handleLargeRecords ? 2 * MIN_NUM_WRITE_BUFFERS : 0;
311:                 }
312:             }
313:         }
314: 
315:         final int sortMemPages = numPagesTotal - numWriteBuffers - numLargeRecordBuffers;
316:         final long sortMemory = ((long) sortMemPages) * memoryManager.getPageSize();
317: 
318:         // decide how many sort buffers to use
319:         if (numSortBuffers < 1) {
320:             if (sortMemory > 100 * 1024 * 1024) {
321:                 numSortBuffers = 2;
322:             } else {
323:                 numSortBuffers = 1;
324:             }
325:         }
326:         final int numSegmentsPerSortBuffer = sortMemPages / numSortBuffers;
327: 
328:         LOG.debug(
329:                 String.format(
330:                         "Instantiating sorter with %d pages of sorting memory (="
331:                                 + "%d bytes total) divided over %d sort buffers (%d pages per buffer). Using %d"
332:                                 + " buffers for writing sorted results and merging maximally %d streams at once. "
333:                                 + "Using %d memory segments for large record spilling.",
334:                         sortMemPages,
335:                         sortMemory,
336:                         numSortBuffers,
337:                         numSegmentsPerSortBuffer,
338:                         numWriteBuffers,
339:                         maxNumFileHandles,
340:                         numLargeRecordBuffers));
341: 
342:         List<MemorySegment> writeMemory = new ArrayList<>(numWriteBuffers);
343: 
344:         LargeRecordHandler<T> largeRecordHandler;
345:         // move some pages from the sort memory to the write memory
346:         if (numWriteBuffers > 0) {
347:             for (int i = 0; i < numWriteBuffers; i++) {
348:                 writeMemory.add(memory.remove(memory.size() - 1));
349:             }
350:         }
351:         if (numLargeRecordBuffers > 0) {
352:             List<MemorySegment> mem = new ArrayList<>();
353:             for (int i = 0; i < numLargeRecordBuffers; i++) {
354:                 mem.add(memory.remove(memory.size() - 1));
355:             }
356: 
357:             largeRecordHandler =
358:                     new LargeRecordHandler<>(
359:                             serializer,
360:                             comparator.duplicate(),
361:                             ioManager,
362:                             memoryManager,
363:                             mem,
364:                             parentTask,
365:                             maxNumFileHandles,
366:                             executionConfig);
367:         } else {
368:             largeRecordHandler = null;
369:         }
370: 
371:         // circular queues pass buffers between the threads
372:         final CircularQueues<T> circularQueues = new CircularQueues<>();
373: 
374:         final List<InMemorySorter<T>> inMemorySorters = new ArrayList<>(numSortBuffers);
375: 
376:         // allocate the sort buffers and fill empty queue with them
377:         final Iterator<MemorySegment> segments = memory.iterator();
378:         for (int i = 0; i < numSortBuffers; i++) {
379:             // grab some memory
380:             final List<MemorySegment> sortSegments = new ArrayList<>(numSegmentsPerSortBuffer);
381:             for (int k = (i == numSortBuffers - 1 ? Integer.MAX_VALUE : numSegmentsPerSortBuffer);
382:                     k > 0 && segments.hasNext();
383:                     k--) {
384:                 sortSegments.add(segments.next());
385:             }
386: 
387:             final InMemorySorter<T> inMemorySorter = inMemorySorterFactory.create(sortSegments);
388:             inMemorySorters.add(inMemorySorter);
389: 
390:             // add to empty queue
391:             CircularElement<T> element = new CircularElement<>(i, inMemorySorter, sortSegments);
392:             circularQueues.send(StageRunner.SortStage.READ, element);
393:         }
394: 
395:         // exception handling
396:         ExceptionHandler<IOException> exceptionHandler =
397:                 exception -> circularQueues.getIteratorFuture().completeExceptionally(exception);
398: 
399:         SpillChannelManager spillChannelManager = new SpillChannelManager();
400: 
401:         // start the thread that reads the input channels
402:         StageRunner readingThread =
403:                 readingStageFactory.createReadingStage(
404:                         exceptionHandler,
405:                         circularQueues,
406:                         largeRecordHandler,
407:                         ((long) (startSpillingFraction * sortMemory)));
408: 
409:         // start the thread that sorts the buffers
410:         StageRunner sortingStage = new SortingThread<>(exceptionHandler, circularQueues);
411: 
412:         // start the thread that handles spilling to secondary storage
413:         final SpillingThread.SpillingBehaviour<T> spillingBehaviour;
414:         if (combineFunction != null) {
415:             spillingBehaviour =
416:                     new CombiningSpillingBehaviour<>(
417:                             combineFunction, serializer, comparator, objectReuseEnabled, udfConfig);
418:         } else {
419:             spillingBehaviour = new DefaultSpillingBehaviour<>(objectReuseEnabled, serializer);
420:         }
421: 
422:         StageRunner spillingStage =
423:                 new SpillingThread<>(
424:                         exceptionHandler,
425:                         circularQueues,
426:                         memoryManager,
427:                         ioManager,
428:                         serializer,
429:                         comparator,
430:                         memory,
431:                         writeMemory,
432:                         maxNumFileHandles,
433:                         spillChannelManager,
434:                         largeRecordHandler,
435:                         spillingBehaviour,
436:                         MIN_NUM_WRITE_BUFFERS,
437:                         MAX_NUM_WRITE_BUFFERS);
438: 
439:         return new ExternalSorter<>(
440:                 readingThread,
441:                 sortingStage,
442:                 spillingStage,
443:                 memory,
444:                 writeMemory,
445:                 memoryManager,
446:                 largeRecordHandler,
447:                 spillChannelManager,
448:                 inMemorySorters,
449:                 circularQueues);
450:     }
