161:             while ((circElement = this.dispatcher.poll(SortStage.READ)) != null) {
162:                 circElement.getBuffer().dispose();
163:                 memoryForLargeRecordSorting.addAll(circElement.getMemory());
164:             }
165: 
166:             if (memoryForLargeRecordSorting.isEmpty()) {
167:                 cacheOnly = false;
168:                 LOG.debug("Going to disk-based merge because of large records.");
169:             } else {
170:                 LOG.debug("Sorting large records, to add them to in-memory merge.");
171:                 largeRecords =
172:                         largeRecordHandler.finishWriteAndSortKeys(memoryForLargeRecordSorting);
173:             }
174:         }
175: 
176:         // ------------------- In-Memory Merge ------------------------
177:         if (cacheOnly) {
178:             mergeInMemory(cache, largeRecords);
179:             return;
180:         }
181: 
182:         // ------------------- Spilling Phase ------------------------
183:         List<ChannelWithBlockCount> channelIDs = startSpilling(cache);
184: 
185:         // ------------------- Merging Phase ------------------------
186: 
187:         mergeOnDisk(channelIDs);
188:     }
