296:     private void mergeInMemory(
297:             Queue<CircularElement<E>> cache, MutableObjectIterator<E> largeRecords)
298:             throws IOException {
299:         // operates on in-memory buffers only
300:         LOG.debug("Initiating in memory merge.");
301: 
302:         List<MutableObjectIterator<E>> iterators = new ArrayList<>(cache.size() + 1);
303: 
304:         // iterate buffers and collect a set of iterators
305:         for (CircularElement<E> cached : cache) {
306:             // note: the yielded iterator only operates on the buffer heap (and disregards the
307:             // stack)
308:             iterators.add(cached.getBuffer().getIterator());
309:         }
310: 
311:         if (largeRecords != null) {
312:             iterators.add(largeRecords);
313:         }
314: 
315:         // release the remaining sort-buffers
316:         LOG.debug("Releasing unused sort-buffer memory.");
317:         disposeSortBuffers(true);
318: 
319:         // set lazy iterator
320:         if (iterators.isEmpty()) {
321:             this.dispatcher.sendResult(EmptyMutableObjectIterator.get());
322:         } else if (iterators.size() == 1) {
323:             this.dispatcher.sendResult(iterators.get(0));
324:         } else {
325:             this.dispatcher.sendResult(new MergeIterator<>(iterators, this.comparator));
326:         }
327:     }
