410:     /**
411:      * Returns an iterator that iterates over the merged result from all given channels.
412:      *
413:      * @param channelIDs The channels that are to be merged and returned.
414:      * @param inputSegments The buffers to be used for reading. The list contains for each channel
415:      *     one list of input segments. The size of the <code>inputSegments</code> list must be equal
416:      *     to that of the <code>channelIDs</code> list.
417:      * @return An iterator over the merged records of the input channels.
418:      * @throws IOException Thrown, if the readers encounter an I/O problem.
419:      */
420:     private MergeIterator<E> getMergingIterator(
421:             final List<ChannelWithBlockCount> channelIDs,
422:             final List<List<MemorySegment>> inputSegments,
423:             List<FileIOChannel> readerList,
424:             MutableObjectIterator<E> largeRecords)
425:             throws IOException {
426:         // create one iterator per channel id
427:         LOG.debug("Performing merge of {} sorted streams.", channelIDs.size());
428: 
429:         final List<MutableObjectIterator<E>> iterators = new ArrayList<>(channelIDs.size() + 1);
430: 
431:         for (int i = 0; i < channelIDs.size(); i++) {
432:             final ChannelWithBlockCount channel = channelIDs.get(i);
433:             final List<MemorySegment> segsForChannel = inputSegments.get(i);
434: 
435:             // create a reader. if there are multiple segments for the reader, issue multiple
436:             // together per I/O request
437:             final BlockChannelReader<MemorySegment> reader =
438:                     this.ioManager.createBlockChannelReader(channel.getChannel());
439: 
440:             readerList.add(reader);
441:             spillChannelManager.registerOpenChannelToBeRemovedAtShutdown(reader);
442:             spillChannelManager.unregisterChannelToBeRemovedAtShutdown(channel.getChannel());
443: 
444:             // wrap channel reader as a view, to get block spanning record deserialization
445:             final ChannelReaderInputView inView =
446:                     new ChannelReaderInputView(
447:                             reader, segsForChannel, channel.getBlockCount(), false);
448:             iterators.add(new ChannelReaderInputViewIterator<>(inView, null, this.serializer));
449:         }
450: 
451:         if (largeRecords != null) {
452:             iterators.add(largeRecords);
453:         }
454: 
455:         return new MergeIterator<>(iterators, this.comparator);
456:     }
