562:     /**
563:      * Divides the given collection of memory buffers among {@code numChannels} sublists.
564:      *
565:      * @param target The list into which the lists with buffers for the channels are put.
566:      * @param memory A list containing the memory buffers to be distributed. The buffers are not
567:      *     removed from this list.
568:      * @param numChannels The number of channels for which to allocate buffers. Must not be zero.
569:      */
570:     private void getSegmentsForReaders(
571:             List<List<MemorySegment>> target, List<MemorySegment> memory, int numChannels) {
572:         // determine the memory to use per channel and the number of buffers
573:         final int numBuffers = memory.size();
574:         final int buffersPerChannelLowerBound = numBuffers / numChannels;
575:         final int numChannelsWithOneMore = numBuffers % numChannels;
576: 
577:         final Iterator<MemorySegment> segments = memory.iterator();
578: 
579:         // collect memory for the channels that get one segment more
580:         for (int i = 0; i < numChannelsWithOneMore; i++) {
581:             final ArrayList<MemorySegment> segs = new ArrayList<>(buffersPerChannelLowerBound + 1);
582:             target.add(segs);
583:             for (int k = buffersPerChannelLowerBound; k >= 0; k--) {
584:                 segs.add(segments.next());
585:             }
586:         }
587: 
588:         // collect memory for the remaining channels
589:         for (int i = numChannelsWithOneMore; i < numChannels; i++) {
590:             final ArrayList<MemorySegment> segs = new ArrayList<>(buffersPerChannelLowerBound);
591:             target.add(segs);
592:             for (int k = buffersPerChannelLowerBound; k > 0; k--) {
593:                 segs.add(segments.next());
594:             }
595:         }
596:     }
597: }
