199:     private boolean readCache(Queue<CircularElement<E>> cache) throws InterruptedException {
200:         // fill cache
201:         while (isRunning()) {
202:             // take next element from queue
203:             final CircularElement<E> element = this.dispatcher.take(SortStage.SPILL);
204: 
205:             if (element == SPILLING_MARKER) {
206:                 return false;
