215:     private void mergeOnDisk(List<ChannelWithBlockCount> channelIDs) throws IOException {
216:         // make sure we have enough memory to merge and for large record handling
217:         List<MemorySegment> mergeReadMemory;
218:         MutableObjectIterator<E> largeRecords = null;
219: 
220:         if (largeRecordHandler != null && largeRecordHandler.hasData()) {
221: 
222:             List<MemorySegment> longRecMem;
223:             if (channelIDs.isEmpty()) {
224:                 // only long records
225:                 longRecMem = this.mergeReadMemory;
226:                 mergeReadMemory = Collections.emptyList();
227:             } else {
228:                 int maxMergedStreams = Math.min(this.maxFanIn, channelIDs.size());
229: 
230:                 int pagesPerStream =
231:                         Math.max(
232:                                 numberOfRequiredMemorySegments,
233:                                 Math.min(
234:                                         maxNumWriteBuffers,
235:                                         this.mergeReadMemory.size() / 2 / maxMergedStreams));
236: 
237:                 int totalMergeReadMemory = maxMergedStreams * pagesPerStream;
238: 
239:                 // grab the merge memory
240:                 mergeReadMemory = new ArrayList<>(totalMergeReadMemory);
241:                 for (int i = 0; i < totalMergeReadMemory; i++) {
242:                     mergeReadMemory.add(this.mergeReadMemory.get(i));
243:                 }
244: 
245:                 // the remainder of the memory goes to the long record sorter
246:                 longRecMem = new ArrayList<>();
247:                 for (int i = totalMergeReadMemory; i < this.mergeReadMemory.size(); i++) {
248:                     longRecMem.add(this.mergeReadMemory.get(i));
249:                 }
250:             }
251: 
252:             LOG.debug("Sorting keys for large records.");
253:             largeRecords = largeRecordHandler.finishWriteAndSortKeys(longRecMem);
254:         } else {
255:             mergeReadMemory = this.mergeReadMemory;
256:         }
257: 
258:         // merge channels until sufficient file handles are available
259:         while (isRunning() && channelIDs.size() > this.maxFanIn) {
260:             channelIDs = mergeChannelList(channelIDs, mergeReadMemory, this.writeMemory);
261:         }
262: 
263:         // from here on, we won't write again
264:         this.memManager.release(this.writeMemory);
265:         this.writeMemory.clear();
266: 
267:         // check if we have spilled some data at all
268:         if (channelIDs.isEmpty()) {
269:             if (largeRecords == null) {
270:                 this.dispatcher.sendResult(EmptyMutableObjectIterator.get());
271:             } else {
272:                 this.dispatcher.sendResult(largeRecords);
273:             }
274:         } else {
275:             LOG.debug("Beginning final merge.");
276: 
277:             // allocate the memory for the final merging step
278:             List<List<MemorySegment>> readBuffers = new ArrayList<>(channelIDs.size());
279: 
280:             // allocate the read memory and register it to be released
281:             getSegmentsForReaders(readBuffers, mergeReadMemory, channelIDs.size());
282: 
283:             // get the readers and register them to be released
284:             this.dispatcher.sendResult(
285:                     getMergingIterator(
286:                             channelIDs,
287:                             readBuffers,
288:                             new ArrayList<>(channelIDs.size()),
289:                             largeRecords));
290:         }
291: 
292:         // done
293:         LOG.debug("Spilling and merging thread done.");
294:     }
