329:     private List<ChannelWithBlockCount> startSpilling(Queue<CircularElement<E>> cache)
330:             throws IOException, InterruptedException {
331:         final FileIOChannel.Enumerator enumerator = this.ioManager.createChannelEnumerator();
332:         List<ChannelWithBlockCount> channelIDs = new ArrayList<>();
333: 
334:         // loop as long as the thread is marked alive and we do not see the final element
335:         openSpillingBehaviour();
336:         while (isRunning()) {
337:             final CircularElement<E> element =
338:                     cache.isEmpty() ? this.dispatcher.take(SortStage.SPILL) : cache.poll();
339: 
340:             // check if we are still running
341:             if (!isRunning()) {
342:                 return Collections.emptyList();
343:             }
344:             // check if this is the end-of-work buffer
345:             if (element == EOF_MARKER) {
346:                 break;
347:             }
348: 
349:             // open next channel
350:             FileIOChannel.ID channel = enumerator.next();
351:             spillChannelManager.registerChannelToBeRemovedAtShutdown(channel);
352: 
353:             // create writer
354:             final BlockChannelWriter<MemorySegment> writer =
355:                     this.ioManager.createBlockChannelWriter(channel);
356:             spillChannelManager.registerOpenChannelToBeRemovedAtShutdown(writer);
357:             final ChannelWriterOutputView output =
358:                     new ChannelWriterOutputView(
359:                             writer, this.writeMemory, this.memManager.getPageSize());
360: 
361:             // write sort-buffer to channel
362:             LOG.debug("Spilling buffer " + element.getId() + ".");
363:             spillingBehaviour.spillBuffer(element, output, largeRecordHandler);
364:             LOG.debug("Spilled buffer " + element.getId() + ".");
365: 
366:             output.close();
367:             spillChannelManager.unregisterOpenChannelToBeRemovedAtShutdown(writer);
368: 
369:             if (output.getBytesWritten() > 0) {
370:                 channelIDs.add(new ChannelWithBlockCount(channel, output.getBlockCount()));
371:             }
372: 
373:             // pass empty sort-buffer to reading thread
374:             element.getBuffer().reset();
375:             this.dispatcher.send(SortStage.READ, element);
376:         }
377: 
378:         // done with the spilling
379:         LOG.debug("Spilling done.");
380:         LOG.debug("Releasing sort-buffer memory.");
381: 
382:         // clear the sort buffers, but do not return the memory to the manager, as we use it for
383:         // merging
384:         disposeSortBuffers(false);
385:         return channelIDs;
386:     }
