458:     /**
459:      * Merges the given sorted runs to a smaller number of sorted runs.
460:      *
461:      * @param channelIDs The IDs of the sorted runs that need to be merged.
462:      * @param allReadBuffers
463:      * @param writeBuffers The buffers to be used by the writers.
464:      * @return A list of the IDs of the merged channels.
465:      * @throws IOException Thrown, if the readers or writers encountered an I/O problem.
466:      */
467:     private List<ChannelWithBlockCount> mergeChannelList(
468:             final List<ChannelWithBlockCount> channelIDs,
469:             final List<MemorySegment> allReadBuffers,
470:             final List<MemorySegment> writeBuffers)
471:             throws IOException {
472:         // A channel list with length maxFanIn<sup>i</sup> can be merged to maxFanIn files in i-1
473:         // rounds where every merge
474:         // is a full merge with maxFanIn input channels. A partial round includes merges with fewer
475:         // than maxFanIn
476:         // inputs. It is most efficient to perform the partial round first.
477:         final double scale = Math.ceil(Math.log(channelIDs.size()) / Math.log(this.maxFanIn)) - 1;
478: 
479:         final int numStart = channelIDs.size();
480:         final int numEnd = (int) Math.pow(this.maxFanIn, scale);
481: 
482:         final int numMerges = (int) Math.ceil((numStart - numEnd) / (double) (this.maxFanIn - 1));
483: 
484:         final int numNotMerged = numEnd - numMerges;
485:         final int numToMerge = numStart - numNotMerged;
486: 
487:         // unmerged channel IDs are copied directly to the result list
488:         final List<ChannelWithBlockCount> mergedChannelIDs = new ArrayList<>(numEnd);
489:         mergedChannelIDs.addAll(channelIDs.subList(0, numNotMerged));
490: 
491:         final int channelsToMergePerStep = (int) Math.ceil(numToMerge / (double) numMerges);
492: 
493:         // allocate the memory for the merging step
494:         final List<List<MemorySegment>> readBuffers = new ArrayList<>(channelsToMergePerStep);
495:         getSegmentsForReaders(readBuffers, allReadBuffers, channelsToMergePerStep);
496: 
497:         final List<ChannelWithBlockCount> channelsToMergeThisStep =
498:                 new ArrayList<>(channelsToMergePerStep);
499:         int channelNum = numNotMerged;
500:         while (isRunning() && channelNum < channelIDs.size()) {
501:             channelsToMergeThisStep.clear();
502: 
503:             for (int i = 0;
504:                     i < channelsToMergePerStep && channelNum < channelIDs.size();
505:                     i++, channelNum++) {
506:                 channelsToMergeThisStep.add(channelIDs.get(channelNum));
507:             }
508: 
509:             mergedChannelIDs.add(mergeChannels(channelsToMergeThisStep, readBuffers, writeBuffers));
510:         }
511: 
512:         return mergedChannelIDs;
513:     }
