515:     /**
516:      * Merges the sorted runs described by the given Channel IDs into a single sorted run. The
517:      * merging process uses the given read and write buffers.
518:      *
519:      * @param channelIDs The IDs of the runs' channels.
520:      * @param readBuffers The buffers for the readers that read the sorted runs.
521:      * @param writeBuffers The buffers for the writer that writes the merged channel.
522:      * @return The ID and number of blocks of the channel that describes the merged run.
523:      */
524:     private ChannelWithBlockCount mergeChannels(
525:             List<ChannelWithBlockCount> channelIDs,
526:             List<List<MemorySegment>> readBuffers,
527:             List<MemorySegment> writeBuffers)
528:             throws IOException {
529:         // the list with the readers, to be closed at shutdown
530:         final List<FileIOChannel> channelAccesses = new ArrayList<>(channelIDs.size());
531: 
532:         // the list with the target iterators
533:         final MergeIterator<E> mergeIterator =
534:                 getMergingIterator(channelIDs, readBuffers, channelAccesses, null);
535: 
536:         // create a new channel writer
537:         final FileIOChannel.ID mergedChannelID = this.ioManager.createChannel();
538:         spillChannelManager.registerChannelToBeRemovedAtShutdown(mergedChannelID);
539:         final BlockChannelWriter<MemorySegment> writer =
540:                 this.ioManager.createBlockChannelWriter(mergedChannelID);
541:         spillChannelManager.registerOpenChannelToBeRemovedAtShutdown(writer);
542:         final ChannelWriterOutputView output =
543:                 new ChannelWriterOutputView(writer, writeBuffers, this.memManager.getPageSize());
544: 
545:         openSpillingBehaviour();
546:         spillingBehaviour.mergeRecords(mergeIterator, output);
547:         output.close();
548:         final int numBlocksWritten = output.getBlockCount();
549: 
550:         // register merged result to be removed at shutdown
551:         spillChannelManager.unregisterOpenChannelToBeRemovedAtShutdown(writer);
552: 
553:         // remove the merged channel readers from the clear-at-shutdown list
554:         for (FileIOChannel access : channelAccesses) {
555:             access.closeAndDelete();
556:             spillChannelManager.unregisterOpenChannelToBeRemovedAtShutdown(access);
557:         }
558: 
559:         return new ChannelWithBlockCount(mergedChannelID, numBlocksWritten);
560:     }
