183:             boolean asyncMergeEnabled) {
184:         this(
185:                 owner,
186:                 memoryManager,
187:                 reservedMemorySize,
188:                 ioManager,
189:                 inputSerializer,
190:                 serializer,
191:                 normalizedKeyComputer,
192:                 comparator,
193:                 maxNumFileHandles,
194:                 compressionEnabled,
195:                 compressionBlockSize,
196:                 asyncMergeEnabled,
197:                 AlgorithmOptions.SORT_SPILLING_THRESHOLD.defaultValue());
198:     }
199: 
200:     public BinaryExternalSorter(
201:             final Object owner,
202:             MemoryManager memoryManager,
203:             long reservedMemorySize,
204:             IOManager ioManager,
205:             AbstractRowDataSerializer<RowData> inputSerializer,
206:             BinaryRowDataSerializer serializer,
207:             NormalizedKeyComputer normalizedKeyComputer,
208:             RecordComparator comparator,
209:             int maxNumFileHandles,
210:             boolean compressionEnabled,
211:             int compressionBlockSize,
212:             boolean asyncMergeEnabled,
213:             float startSpillingFraction) {
214:         this.compressionEnabled = compressionEnabled;
215:         this.compressionCodecFactory =
216:                 this.compressionEnabled
217:                         ? BlockCompressionFactory.createBlockCompressionFactory(
218:                                 CompressionCodec.LZ4)
219:                         : null;
220:         this.compressionBlockSize = compressionBlockSize;
221:         this.asyncMergeEnabled = asyncMergeEnabled;
222: 
223:         checkArgument(maxNumFileHandles >= 2);
224:         checkNotNull(ioManager);
225:         checkNotNull(normalizedKeyComputer);
226:         checkNotNull(memoryManager);
227:         this.serializer = (BinaryRowDataSerializer) serializer.duplicate();
228:         this.memorySegmentSize = memoryManager.getPageSize();
229: 
230:         if (reservedMemorySize < SORTER_MIN_NUM_SORT_MEM) {
231:             throw new IllegalArgumentException(
232:                     "Too little memory provided to sorter to perform task. "
233:                             + "Required are at least "
234:                             + SORTER_MIN_NUM_SORT_MEM
235:                             + " bytes. Current memory size is "
236:                             + reservedMemorySize
237:                             + " bytes.");
238:         }
239: 
240:         // adjust the memory quotas to the page size
241:         final int sortMemPages = (int) (reservedMemorySize / memoryManager.getPageSize());
242:         final long sortMemory = ((long) sortMemPages) * memoryManager.getPageSize();
243: 
244:         // decide how many sort buffers to use
245:         int numSortBuffers = 1;
246:         if (reservedMemorySize > 100 * 1024 * 1024L) {
247:             numSortBuffers = 2;
248:         }
249:         final int numSegmentsPerSortBuffer = sortMemPages / numSortBuffers;
250:         this.sortReadMemory = new ArrayList<>();
251: 
252:         // circular circularQueues pass buffers between the threads
253:         final CircularQueues circularQueues = new CircularQueues();
254: 
255:         LOG.info(
256:                 "BinaryExternalSorter with initial memory segments {}, "
257:                         + "maxNumFileHandles({}), compressionEnable({}), compressionCodecFactory({}), compressionBlockSize({}).",
258:                 sortMemPages,
259:                 maxNumFileHandles,
260:                 compressionEnabled,
261:                 compressionEnabled ? compressionCodecFactory.getClass() : null,
262:                 compressionBlockSize);
263: 
264:         this.sortBuffers = new ArrayList<>();
265:         int totalBuffers = sortMemPages;
266:         for (int i = 0; i < numSortBuffers; i++) {
267:             // grab some memory
268:             int sortSegments =
269:                     Math.min(
270:                             i == numSortBuffers - 1 ? Integer.MAX_VALUE : numSegmentsPerSortBuffer,
271:                             totalBuffers);
272:             totalBuffers -= sortSegments;
273:             LazyMemorySegmentPool pool =
274:                     new LazyMemorySegmentPool(owner, memoryManager, sortSegments);
275:             this.sortReadMemory.add(pool);
276:             final BinaryInMemorySortBuffer buffer =
277:                     BinaryInMemorySortBuffer.createBuffer(
278:                             normalizedKeyComputer, inputSerializer, serializer, comparator, pool);
279: 
280:             // add to empty queue
281:             CircularElement element = new CircularElement(i, buffer);
282:             circularQueues.empty.add(element);
283:             this.sortBuffers.add(buffer);
284:         }
285: 
286:         // exception handling
287:         ExceptionHandler<IOException> exceptionHandler =
288:                 exception -> {
289:                     // forward exception
290:                     if (!closed) {
291:                         setResultIteratorException(exception);
292:                         close();
293:                     }
294:                 };
295: 
296:         // init adding currWriteBuffer
297:         this.exceptionHandler = exceptionHandler;
298:         this.circularQueues = circularQueues;
299: 
300:         bytesUntilSpilling = ((long) (startSpillingFraction * sortMemory));
301: 
302:         // check if we should directly spill
303:         if (bytesUntilSpilling < 1) {
304:             bytesUntilSpilling = 0;
305:             // add the spilling marker
306:             this.circularQueues.sort.add(SPILLING_MARKER);
307:         }
308: 
309:         this.channelManager = new SpillChannelManager();
310:         this.merger =
311:                 new BinaryExternalMerger(
312:                         ioManager,
313:                         memoryManager.getPageSize(),
314:                         maxNumFileHandles,
315:                         channelManager,
316:                         (BinaryRowDataSerializer) serializer.duplicate(),
317:                         comparator,
318:                         compressionEnabled,
319:                         compressionCodecFactory,
320:                         compressionBlockSize);
321: 
322:         // start the thread that sorts the buffers
323:         this.sortThread = getSortingThread(exceptionHandler, circularQueues);
324: 
325:         // start the thread that handles spilling to secondary storage
326:         this.spillThread =
327:                 getSpillingThread(
328:                         exceptionHandler,
329:                         circularQueues,
330:                         ioManager,
331:                         (BinaryRowDataSerializer) serializer.duplicate(),
332:                         comparator);
333: 
334:         // start the thread that handles merging from second storage
335:         this.mergeThread =
336:                 getMergingThread(exceptionHandler, circularQueues, maxNumFileHandles, merger);
337: 
338:         // propagate the context class loader to the spawned threads
339:         ClassLoader contextLoader = Thread.currentThread().getContextClassLoader();
340:         if (contextLoader != null) {
341:             if (this.sortThread != null) {
342:                 this.sortThread.setContextClassLoader(contextLoader);
343:             }
344:             if (this.spillThread != null) {
345:                 this.spillThread.setContextClassLoader(contextLoader);
346:             }
347:             if (this.mergeThread != null) {
348:                 this.mergeThread.setContextClassLoader(contextLoader);
349:             }
350:         }
351:     }
