353:     // ------------------------------------------------------------------------
354:     //                           Factory Methods
355:     // ------------------------------------------------------------------------
356: 
357:     /** Starts all the threads that are used by this sorter. */
358:     public void startThreads() {
359:         if (this.sortThread != null) {
360:             this.sortThread.start();
361:         }
362:         if (this.spillThread != null) {
363:             this.spillThread.start();
364:         }
365:         if (this.mergeThread != null) {
366:             this.mergeThread.start();
367:         }
368:     }
369: 
370:     /**
371:      * Shuts down all the threads initiated by this sorter. Also releases all previously allocated
372:      * memory, if it has not yet been released by the threads, and closes and deletes all channels
373:      * (removing the temporary files).
374:      *
375:      * <p>The threads are set to exit directly, but depending on their operation, it may take a
376:      * while to actually happen. The sorting thread will for example not finish before the current
377:      * batch is sorted. This method attempts to wait for the working thread to exit. If it is
378:      * however interrupted, the method exits immediately and is not guaranteed how long the threads
379:      * continue to exist and occupy resources afterwards.
380:      */
381:     @Override
382:     public void close() {
383:         // check if the sorter has been closed before
384:         synchronized (this) {
385:             if (this.closed) {
386:                 return;
387:             }
388: 
389:             // mark as closed
390:             this.closed = true;
391:         }
392: 
393:         // from here on, the code is in a try block, because even through errors might be thrown in
394:         // this block,
395:         // we need to make sure that all the memory is released.
396:         try {
397:             // if the result iterator has not been obtained yet, set the exception
398:             synchronized (this.iteratorLock) {
399:                 if (this.iteratorException == null) {
400:                     this.iteratorException = new IOException("The sorter has been closed.");
401:                     this.iteratorLock.notifyAll();
402:                 }
403:             }
404: 
405:             // stop all the threads
406:             if (this.sortThread != null) {
407:                 try {
408:                     this.sortThread.shutdown();
409:                 } catch (Throwable t) {
410:                     LOG.error("Error shutting down sorter thread: " + t.getMessage(), t);
411:                 }
412:             }
413:             if (this.spillThread != null) {
414:                 try {
415:                     this.spillThread.shutdown();
416:                 } catch (Throwable t) {
417:                     LOG.error("Error shutting down spilling thread: " + t.getMessage(), t);
418:                 }
419:             }
420:             if (this.mergeThread != null) {
421:                 try {
422:                     this.mergeThread.shutdown();
423:                 } catch (Throwable t) {
424:                     LOG.error("Error shutting down merging thread: " + t.getMessage(), t);
425:                 }
426:             }
427: 
428:             try {
429:                 if (this.sortThread != null) {
430:                     this.sortThread.join();
431:                     this.sortThread = null;
432:                 }
433:                 if (this.spillThread != null) {
434:                     this.spillThread.join();
435:                     this.spillThread = null;
436:                 }
437:                 if (this.mergeThread != null) {
438:                     this.mergeThread.join();
439:                     this.mergeThread = null;
440:                 }
441:             } catch (InterruptedException iex) {
442:                 LOG.debug(
443:                         "Closing of sort/merger was interrupted. "
444:                                 + "The reading/sorting/spilling/merging threads may still be working.",
445:                         iex);
446:             }
447:         } finally {
448:             releaseSortMemory();
449: 
450:             // Eliminate object references for MemorySegments.
451:             circularQueues = null;
452:             currWriteBuffer = null;
453:             iterator = null;
454: 
455:             merger.close();
456:             channelManager.close();
457:         }
458:     }
459: 
460:     private void releaseSortMemory() {
461:         // RELEASE ALL MEMORY. If the threads and channels are still running, this should cause
462:         // exceptions, because their memory segments are freed
463: 
464:         try {
465:             // floating segments are released in `dispose()` method
466:             this.sortBuffers.forEach(BinaryInMemorySortBuffer::dispose);
467:             this.sortBuffers.clear();
468:         } catch (Throwable e) {
469:             LOG.info("error.", e);
470:         }
471: 
472:         sortReadMemory.forEach(LazyMemorySegmentPool::close);
473:         sortReadMemory.clear();
474:     }
