498:     public void write(RowData current) throws IOException {
499:         checkArgument(!writingDone, "Adding already done!");
500:         try {
501:             while (true) {
502:                 if (closed) {
503:                     throw new IOException("Already closed!", iteratorException);
504:                 }
505: 
506:                 synchronized (writeLock) {
507:                     // grab the next buffer
508:                     if (currWriteBuffer == null) {
509:                         try {
510:                             currWriteBuffer = this.circularQueues.empty.poll(1, TimeUnit.SECONDS);
511:                             if (currWriteBuffer == null) {
512:                                 // maybe something happened, release lock.
513:                                 continue;
514:                             }
515:                             if (!currWriteBuffer.buffer.isEmpty()) {
516:                                 throw new IOException("New buffer is not empty.");
517:                             }
518:                         } catch (InterruptedException iex) {
519:                             throw new IOException(iex);
520:                         }
521:                     }
522: 
523:                     final BinaryInMemorySortBuffer buffer = currWriteBuffer.buffer;
524: 
525:                     if (LOG.isDebugEnabled()) {
526:                         LOG.debug("Retrieved empty read buffer " + currWriteBuffer.id + ".");
527:                     }
528: 
529:                     long occupancy = buffer.getOccupancy();
530:                     if (!buffer.write(current)) {
531:                         if (buffer.isEmpty()) {
532:                             // did not fit in a fresh buffer, must be large...
533:                             throw new IOException(
534:                                     "The record exceeds the maximum size of a sort buffer (current maximum: "
535:                                             + buffer.getCapacity()
536:                                             + " bytes).");
537:                         } else {
538:                             // buffer is full, send the buffer
539:                             if (LOG.isDebugEnabled()) {
540:                                 LOG.debug("Emitting full buffer: " + currWriteBuffer.id + ".");
541:                             }
542: 
543:                             this.circularQueues.sort.add(currWriteBuffer);
544: 
545:                             // Deadlocks may occur when there are fewer MemorySegments, because of
546:                             // the fragmentation of buffer.getOccupancy ().
547:                             if (bytesUntilSpilling > 0 && circularQueues.empty.size() == 0) {
548:                                 bytesUntilSpilling = 0;
549:                                 this.circularQueues.sort.add(SPILLING_MARKER);
550:                             }
551: 
552:                             currWriteBuffer = null;
553:                             // continue to process current record.
554:                         }
555:                     } else {
556:                         // successfully added record
557:                         // it may be that the last currWriteBuffer would have crossed the
558:                         // spilling threshold, so check it
559:                         if (bytesUntilSpilling > 0) {
560:                             bytesUntilSpilling -= buffer.getOccupancy() - occupancy;
561:                             if (bytesUntilSpilling <= 0) {
562:                                 bytesUntilSpilling = 0;
563:                                 this.circularQueues.sort.add(SPILLING_MARKER);
564:                             }
565:                         }
566:                         break;
567:                     }
568:                 }
569:             }
570:         } catch (Throwable e) {
571:             IOException ioe = new IOException(e);
572:             if (this.exceptionHandler != null) {
573:                 this.exceptionHandler.handleException(ioe);
574:             }
575:             throw ioe;
576:         }
577:     }
