579:     @VisibleForTesting
580:     public void write(MutableObjectIterator<BinaryRowData> iterator) throws IOException {
581:         BinaryRowData row = serializer.createInstance();
582:         while ((row = iterator.next(row)) != null) {
583:             write(row);
584:         }
