587:     @Override
588:     public MutableObjectIterator<BinaryRowData> getIterator() throws InterruptedException {
589:         if (!writingDone) {
590:             writingDone = true;
591: 
592:             if (currWriteBuffer != null) {
593:                 this.circularQueues.sort.add(currWriteBuffer);
594:             }
595: 
596:             // add the sentinel to notify the receivers that the work is done
597:             // send the EOF marker
598:             this.circularQueues.sort.add(EOF_MARKER);
599:             LOG.debug("Sending done.");
600:         }
601: 
602:         synchronized (this.iteratorLock) {
603:             // wait while both the iterator and the exception are not set
604:             while (this.iterator == null && this.iteratorException == null) {
605:                 this.iteratorLock.wait();
606:             }
607: 
608:             if (this.iteratorException != null) {
609:                 throw new RuntimeException(
610:                         "Error obtaining the sorted input: " + this.iteratorException.getMessage(),
611:                         this.iteratorException);
612:             } else {
613:                 return this.iterator;
614:             }
615:         }
616:     }
