619:     // Inter-Thread Communication
620:     // ------------------------------------------------------------------------
621: 
622:     /**
623:      * Sets the result iterator. By setting the result iterator, all threads that are waiting for
624:      * the result iterator are notified and will obtain it.
625:      *
626:      * @param iterator The result iterator to set.
627:      */
628:     private void setResultIterator(MutableObjectIterator<BinaryRowData> iterator) {
629:         synchronized (this.iteratorLock) {
630:             // set the result iterator only, if no exception has occurred
631:             if (this.iteratorException == null) {
632:                 this.iterator = iterator;
633:                 this.iteratorLock.notifyAll();
634:             }
635:         }
636:     }
637: 
638:     /**
639:      * Reports an exception to all threads that are waiting for the result iterator.
640:      *
641:      * @param ioex The exception to be reported to the threads that wait for the result iterator.
642:      */
643:     private void setResultIteratorException(IOException ioex) {
644:         synchronized (this.iteratorLock) {
645:             if (this.iteratorException == null) {
646:                 this.iteratorException = ioex;
647:                 this.iteratorLock.notifyAll();
648:             }
649:         }
650:     }
