652:     /**
653:      * Class representing buffers that circulate between the reading, sorting and spilling thread.
654:      */
655:     private static final class CircularElement {
656: 
657:         final int id; // just for debug.
658:         final BinaryInMemorySortBuffer buffer;
659: 
660:         private CircularElement() {
661:             this.id = -1;
662:             this.buffer = null;
663:         }
664: 
665:         private CircularElement(int id, BinaryInMemorySortBuffer buffer) {
666:             this.id = id;
667:             this.buffer = buffer;
668:         }
669:     }
