671:     /** Collection of circularQueues that are used for the communication between the threads. */
672:     private static final class CircularQueues {
673: 
674:         final BlockingQueue<CircularElement> empty;
675: 
676:         final BlockingQueue<CircularElement> sort;
677: 
678:         final BlockingQueue<CircularElement> spill;
679: 
680:         final BlockingQueue<ChannelWithMeta> merge;
681: 
682:         private CircularQueues() {
683:             this.empty = new LinkedBlockingQueue<>();
684:             this.sort = new LinkedBlockingQueue<>();
685:             this.spill = new LinkedBlockingQueue<>();
686:             this.merge = new LinkedBlockingQueue<>();
