690:     // ------------------------------------------------------------------------
691:     // Threads
692:     // ------------------------------------------------------------------------
693: 
694:     /**
695:      * Base class for all working threads in this sorter. The specific threads for sorting,
696:      * spilling, etc... extend this subclass.
697:      *
698:      * <p>The threads are designed to terminate themselves when the task they are set up to do is
699:      * completed. Further more, they terminate immediately when the <code>shutdown()</code> method
700:      * is called.
701:      */
702:     private abstract static class ThreadBase extends Thread
703:             implements Thread.UncaughtExceptionHandler {
704: 
705:         /** The queue of empty buffer that can be used for reading. */
706:         final CircularQueues queues;
707: 
708:         /** The exception handler for any problems. */
709:         private final ExceptionHandler<IOException> exceptionHandler;
710: 
711:         /** The flag marking this thread as alive. */
712:         private volatile boolean alive;
713: 
714:         /**
715:          * Creates a new thread.
716:          *
717:          * @param exceptionHandler The exception handler to call for all exceptions.
718:          * @param name The name of the thread.
719:          * @param queues The circularQueues used to pass buffers between the threads.
720:          */
721:         private ThreadBase(
722:                 ExceptionHandler<IOException> exceptionHandler,
723:                 String name,
724:                 CircularQueues queues) {
725:             // thread setup
726:             super(name);
727:             this.setDaemon(true);
728: 
729:             // exception handling
730:             this.exceptionHandler = exceptionHandler;
731:             this.setUncaughtExceptionHandler(this);
732: 
733:             this.queues = queues;
734:             this.alive = true;
735:         }
736: 
737:         /** Implements exception handling and delegates to go(). */
738:         public void run() {
739:             try {
740:                 go();
741:             } catch (Throwable t) {
742:                 internalHandleException(
743:                         new IOException(
744:                                 "Thread '"
745:                                         + getName()
746:                                         + "' terminated due to an exception: "
747:                                         + t.getMessage(),
748:                                 t));
749:             }
750:         }
751: 
752:         /**
753:          * Equivalent to the run() method.
754:          *
755:          * @throws IOException Exceptions that prohibit correct completion of the work may be thrown
756:          *     by the thread.
757:          */
758:         abstract void go() throws IOException;
759: 
760:         /**
761:          * Checks whether this thread is still alive.
762:          *
763:          * @return true, if the thread is alive, false otherwise.
764:          */
765:         public boolean isRunning() {
766:             return this.alive;
767:         }
768: 
769:         /**
770:          * Forces an immediate shutdown of the thread. Loses any state and all buffers that the
771:          * thread is currently working on. This terminates cleanly for the JVM, but loses
772:          * intermediate results.
773:          */
774:         public void shutdown() {
775:             this.alive = false;
776:             this.interrupt();
777:         }
778: 
779:         /**
780:          * Internally handles an exception and makes sure that this method returns without a
781:          * problem.
782:          *
783:          * @param ioex The exception to handle.
784:          */
785:         private void internalHandleException(IOException ioex) {
786:             if (!isRunning()) {
787:                 // discard any exception that occurs when after the thread is killed.
788:                 return;
789:             }
790:             if (this.exceptionHandler != null) {
791:                 try {
792:                     this.exceptionHandler.handleException(ioex);
793:                 } catch (Throwable ignored) {
794:                 }
795:             }
796:         }
797: 
798:         @Override
799:         public void uncaughtException(Thread t, Throwable e) {
800:             internalHandleException(
801:                     new IOException(
802:                             "Thread '"
803:                                     + t.getName()
804:                                     + "' terminated due to an uncaught exception: "
805:                                     + e.getMessage(),
806:                             e));
807:         }
808:     }
809: 
810:     /** The thread that sorts filled buffers. */
811:     private static class SortingThread extends ThreadBase {
812: 
813:         private final IndexedSorter sorter;
814: 
815:         /**
816:          * Creates a new sorting thread.
817:          *
818:          * @param exceptionHandler The exception handler to call for all exceptions.
819:          * @param queues The circularQueues used to pass buffers between the threads.
820:          */
821:         public SortingThread(
822:                 ExceptionHandler<IOException> exceptionHandler, CircularQueues queues) {
823:             super(exceptionHandler, "SortMerger sorting thread", queues);
824: 
825:             // members
826:             this.sorter = new QuickSort();
827:         }
828: 
829:         /** Entry point of the thread. */
830:         public void go() throws IOException {
831:             boolean alive = true;
832: 
833:             // loop as long as the thread is marked alive
834:             while (isRunning() && alive) {
835:                 CircularElement element;
836:                 try {
837:                     element = this.queues.sort.take();
838:                 } catch (InterruptedException iex) {
839:                     if (isRunning()) {
840:                         if (LOG.isErrorEnabled()) {
841:                             LOG.error(
842:                                     "Sorting thread was interrupted (without being shut down) while grabbing a buffer. "
843:                                             + "Retrying to grab buffer...");
844:                         }
845:                         continue;
846:                     } else {
847:                         return;
848:                     }
849:                 }
850: 
851:                 if (element != EOF_MARKER && element != SPILLING_MARKER) {
852: 
853:                     if (element.buffer.size() == 0) {
854:                         element.buffer.reset();
855:                         this.queues.empty.add(element);
856:                         continue;
857:                     }
858: 
859:                     if (LOG.isDebugEnabled()) {
860:                         LOG.debug("Sorting buffer " + element.id + ".");
861:                     }
862: 
863:                     this.sorter.sort(element.buffer);
864: 
865:                     if (LOG.isDebugEnabled()) {
866:                         LOG.debug("Sorted buffer " + element.id + ".");
867:                     }
868:                 } else if (element == EOF_MARKER) {
869:                     if (LOG.isDebugEnabled()) {
870:                         LOG.debug("Sorting thread done.");
871:                     }
872:                     alive = false;
873:                 }
874:                 this.queues.spill.add(element);
875:             }
876:         }
877:     }
