879:     /** The thread that handles the spilling of intermediate results. */
880:     private class SpillingThread extends ThreadBase {
881: 
882:         private final IOManager ioManager; // I/O manager to create channels
883: 
884:         private final BinaryRowDataSerializer serializer; // The serializer for the data type
885: 
886:         private final RecordComparator comparator;
887: 
888:         /**
889:          * Creates the spilling thread.
890:          *
891:          * @param exceptionHandler The exception handler to call for all exceptions.
892:          * @param queues The circularQueues used to pass buffers between the threads.
893:          * @param ioManager The I/O manager used to instantiate readers and writers from.
894:          * @param serializer
895:          * @param comparator
