394:     /**
395:      * Writes the records in this buffer in their logical order to the given output.
396:      *
397:      * @param output The output view to write the records to.
398:      * @throws IOException Thrown, if an I/O exception occurred writing to the output view.
399:      */
400:     @Override
401:     public void writeToOutput(final ChannelWriterOutputView output) throws IOException {
402:         final TypeComparator<T> comparator = this.comparator;
403:         final TypeSerializer<T> serializer = this.serializer;
404:         T record = this.recordInstance;
405: 
406:         final SingleSegmentInputView inView = this.inView;
407: 
408:         final int recordsPerSegment = this.recordsPerSegment;
409:         int recordsLeft = this.numRecords;
410:         int currentMemSeg = 0;
411: 
412:         while (recordsLeft > 0) {
413:             final MemorySegment currentIndexSegment = this.sortBuffer.get(currentMemSeg++);
414:             inView.set(currentIndexSegment, 0);
415: 
416:             // check whether we have a full or partially full segment
417:             if (recordsLeft >= recordsPerSegment) {
418:                 // full segment
419:                 for (int numInMemSeg = 0; numInMemSeg < recordsPerSegment; numInMemSeg++) {
420:                     record = comparator.readWithKeyDenormalization(record, inView);
421:                     serializer.serialize(record, output);
422:                 }
423:                 recordsLeft -= recordsPerSegment;
424:             } else {
425:                 // partially filled segment
426:                 for (; recordsLeft > 0; recordsLeft--) {
427:                     record = comparator.readWithKeyDenormalization(record, inView);
428:                     serializer.serialize(record, output);
429:                 }
430:             }
431:         }
432:     }
