451:             throws IOException {
452:         final TypeComparator<T> comparator = this.comparator;
453:         final TypeSerializer<T> serializer = this.serializer;
454:         T record = this.recordInstance;
455: 
456:         final SingleSegmentInputView inView = this.inView;
457: 
458:         final int recordsPerSegment = this.recordsPerSegment;
459:         int currentMemSeg = start / recordsPerSegment;
460:         int offset = (start % recordsPerSegment) * this.recordSize;
461: 
462:         while (num > 0) {
463:             final MemorySegment currentIndexSegment = this.sortBuffer.get(currentMemSeg++);
464:             inView.set(currentIndexSegment, offset);
465: 
466:             // check whether we have a full or partially full segment
467:             if (num >= recordsPerSegment && offset == 0) {
468:                 // full segment
469:                 for (int numInMemSeg = 0; numInMemSeg < recordsPerSegment; numInMemSeg++) {
470:                     record = comparator.readWithKeyDenormalization(record, inView);
471:                     serializer.serialize(record, output);
472:                 }
473:                 num -= recordsPerSegment;
474:             } else {
475:                 // partially filled segment
476:                 for (;
477:                         num > 0 && offset <= this.lastEntryOffset;
478:                         num--, offset += this.recordSize) {
479:                     record = comparator.readWithKeyDenormalization(record, inView);
480:                     serializer.serialize(record, output);
481:                 }
482:             }
483: 
484:             offset = 0;
485:         }
486:     }
