272: 
273:         numElements = 0;
274:         holes = 0;
275:     }
276: 
277:     @Override
278:     public void abort() {
279:         LOG.debug("Aborting InPlaceMutableHashTable.");
280:         close();
281:     }
282: 
283:     @Override
284:     public List<MemorySegment> getFreeMemory() {
285:         if (!this.closed) {
286:             throw new IllegalStateException(
287:                     "Cannot return memory while InPlaceMutableHashTable is open.");
288:         }
289: 
290:         return freeMemorySegments;
291:     }
292: 
293:     private int calcInitialNumBucketSegments() {
294:         int recordLength = buildSideSerializer.getLength();
295:         double fraction; // fraction of memory to use for the buckets
296:         if (recordLength == -1) {
297:             // We don't know the record length, so we start with a small number of buckets, and do
298:             // resizes if
299:             // necessary.
300:             // It seems that resizing is quite efficient, so we can err here on the too few bucket
301:             // segments side.
302:             // Even with small records, we lose only ~15% speed.
303:             fraction = 0.1;
304:         } else {
305:             // We know the record length, so we can find a good value for the number of buckets
306:             // right away, and
307:             // won't need any resizes later. (enableResize is false in this case, so no resizing
308:             // will happen.)
309:             // Reasoning behind the formula:
310:             // We are aiming for one bucket per record, and one bucket contains one 8 byte pointer.
311:             // The total
312:             // memory overhead of an element will be approximately 8+8 bytes, as the record in the
313:             // record area
314:             // is preceded by a pointer (for the linked list).
315:             fraction = 8.0 / (16 + recordLength);
316:         }
317: 
318:         // We make the number of buckets a power of 2 so that taking modulo is efficient.
319:         int ret =
320:                 Math.max(1, MathUtils.roundDownToPowerOf2((int) (numAllMemorySegments * fraction)));
321: 
322:         // We can't handle more than Integer.MAX_VALUE buckets (eg. because hash functions return
323:         // int)
324:         if ((long) ret * numBucketsPerSegment > Integer.MAX_VALUE) {
325:             ret = MathUtils.roundDownToPowerOf2(Integer.MAX_VALUE / numBucketsPerSegment);
326:         }
327:         return ret;
328:     }
329: 
330:     private void allocateBucketSegments(int numBucketSegments) {
331:         if (numBucketSegments < 1) {
332:             throw new RuntimeException("Bug in InPlaceMutableHashTable");
333:         }
334: 
335:         bucketSegments = new MemorySegment[numBucketSegments];
336:         for (int i = 0; i < bucketSegments.length; i++) {
337:             bucketSegments[i] = forcedAllocateSegment();
338:             // Init all pointers in all buckets to END_OF_LIST
339:             for (int j = 0; j < numBucketsPerSegment; j++) {
340:                 bucketSegments[i].putLong(j << bucketSizeBits, END_OF_LIST);
341:             }
342:         }
343:         numBuckets = numBucketSegments * numBucketsPerSegment;
344:         numBucketsMask = (1 << MathUtils.log2strict(numBuckets)) - 1;
345:     }
346: 
347:     private void releaseBucketSegments() {
348:         freeMemorySegments.addAll(Arrays.asList(bucketSegments));
349:         bucketSegments = null;
350:     }
351: 
352:     private MemorySegment allocateSegment() {
353:         int s = freeMemorySegments.size();
354:         if (s > 0) {
355:             return freeMemorySegments.remove(s - 1);
356:         } else {
357:             return null;
358:         }
359:     }
360: 
361:     private MemorySegment forcedAllocateSegment() {
362:         MemorySegment segment = allocateSegment();
363:         if (segment == null) {
364:             throw new RuntimeException(
365:                     "Bug in InPlaceMutableHashTable: A free segment should have been available.");
366:         }
367:         return segment;
368:     }
369: 
370:     /**
371:      * Searches the hash table for a record with the given key. If it is found, then it is
372:      * overridden with the specified record. Otherwise, the specified record is inserted.
373:      *
374:      * @param record The record to insert or to replace with.
375:      * @throws IOException (EOFException specifically, if memory ran out)
376:      */
377:     @Override
378:     public void insertOrReplaceRecord(T record) throws IOException {
379:         if (closed) {
380:             return;
381:         }
382: 
383:         T match = prober.getMatchFor(record, reuse);
384:         if (match == null) {
385:             prober.insertAfterNoMatch(record);
386:         } else {
387:             prober.updateMatch(record);
388:         }
389:     }
390: 
391:     /**
392:      * Inserts the given record into the hash table. Note: this method doesn't care about whether a
393:      * record with the same key is already present.
394:      *
395:      * @param record The record to insert.
396:      * @throws IOException (EOFException specifically, if memory ran out)
397:      */
398:     @Override
399:     public void insert(T record) throws IOException {
400:         if (closed) {
401:             return;
402:         }
403: 
404:         final int hashCode = MathUtils.jenkinsHash(buildSideComparator.hash(record));
405:         final int bucket = hashCode & numBucketsMask;
406:         final int bucketSegmentIndex =
407:                 bucket >>> numBucketsPerSegmentBits; // which segment contains the bucket
408:         final MemorySegment bucketSegment = bucketSegments[bucketSegmentIndex];
409:         final int bucketOffset =
410:                 (bucket & numBucketsPerSegmentMask)
411:                         << bucketSizeBits; // offset of the bucket in the segment
412:         final long firstPointer = bucketSegment.getLong(bucketOffset);
413: 
414:         try {
415:             final long newFirstPointer = recordArea.appendPointerAndRecord(firstPointer, record);
416:             bucketSegment.putLong(bucketOffset, newFirstPointer);
417:         } catch (EOFException ex) {
418:             compactOrThrow();
419:             insert(record);
420:             return;
421:         }
422: 
423:         numElements++;
424:         resizeTableIfNecessary();
425:     }
426: 
427:     private void resizeTableIfNecessary() throws IOException {
428:         if (enableResize && numElements > numBuckets) {
429:             final long newNumBucketSegments = 2L * bucketSegments.length;
430:             // Checks:
431:             // - we can't handle more than Integer.MAX_VALUE buckets
432:             // - don't take more memory than the free memory we have left
433:             // - the buckets shouldn't occupy more than half of all our memory
434:             if (newNumBucketSegments * numBucketsPerSegment < Integer.MAX_VALUE
435:                     && newNumBucketSegments - bucketSegments.length < freeMemorySegments.size()
436:                     && newNumBucketSegments < numAllMemorySegments / 2) {
437:                 // do the resize
438:                 rebuild(newNumBucketSegments);
439:             }
440:         }
441:     }
442: 
443:     /**
444:      * Returns an iterator that can be used to iterate over all the elements in the table. WARNING:
445:      * Doing any other operation on the table invalidates the iterator! (Even using getMatchFor of a
446:      * prober!)
447:      *
448:      * @return the iterator
449:      */
450:     @Override
451:     public EntryIterator getEntryIterator() {
452:         return new EntryIterator();
453:     }
454: 
455:     public <PT> HashTableProber<PT> getProber(
456:             TypeComparator<PT> probeTypeComparator, TypePairComparator<PT, T> pairComparator) {
457:         return new HashTableProber<>(probeTypeComparator, pairComparator);
458:     }
459: 
460:     /**
461:      * This function reinitializes the bucket segments, reads all records from the record segments
462:      * (sequentially, without using the pointers or the buckets), and rebuilds the hash table.
463:      */
464:     private void rebuild() throws IOException {
465:         rebuild(bucketSegments.length);
466:     }
467: 
468:     /** Same as above, but the number of bucket segments of the new table can be specified. */
469:     private void rebuild(long newNumBucketSegments) throws IOException {
470:         // Get new bucket segments
471:         releaseBucketSegments();
472:         allocateBucketSegments((int) newNumBucketSegments);
473: 
474:         T record = buildSideSerializer.createInstance();
475:         try {
476:             EntryIterator iter = getEntryIterator();
477:             recordArea.resetAppendPosition();
478:             recordArea.setWritePosition(0);
479:             while ((record = iter.next(record)) != null && !closed) {
480:                 final int hashCode = MathUtils.jenkinsHash(buildSideComparator.hash(record));
481:                 final int bucket = hashCode & numBucketsMask;
482:                 final int bucketSegmentIndex =
483:                         bucket >>> numBucketsPerSegmentBits; // which segment contains the bucket
484:                 final MemorySegment bucketSegment = bucketSegments[bucketSegmentIndex];
485:                 final int bucketOffset =
486:                         (bucket & numBucketsPerSegmentMask)
487:                                 << bucketSizeBits; // offset of the bucket in the segment
488:                 final long firstPointer = bucketSegment.getLong(bucketOffset);
489: 
490:                 long ptrToAppended = recordArea.noSeekAppendPointerAndRecord(firstPointer, record);
491:                 bucketSegment.putLong(bucketOffset, ptrToAppended);
492:             }
493:             recordArea.freeSegmentsAfterAppendPosition();
494:             holes = 0;
495: 
496:         } catch (EOFException ex) {
497:             throw new RuntimeException(
498:                     "Bug in InPlaceMutableHashTable: we shouldn't get out of memory during a rebuild, "
499:                             + "because we aren't allocating any new memory.");
500:         }
501:     }
502: 
503:     /**
504:      * If there is wasted space (due to updated records not fitting in their old places), then do a
505:      * compaction. Else, throw EOFException to indicate that memory ran out.
506:      *
507:      * @throws IOException
508:      */
509:     private void compactOrThrow() throws IOException {
510:         if (holes > (double) recordArea.getTotalSize() * 0.05) {
511:             rebuild();
512:         } else {
513:             throw new EOFException(
514:                     "InPlaceMutableHashTable memory ran out. " + getMemoryConsumptionString());
515:         }
516:     }
517: 
518:     /** @return String containing a summary of the memory consumption for error messages */
519:     private String getMemoryConsumptionString() {
520:         return "InPlaceMutableHashTable memory stats:\n"
521:                 + "Total memory:     "
522:                 + numAllMemorySegments * segmentSize
523:                 + "\n"
524:                 + "Free memory:      "
525:                 + freeMemorySegments.size() * segmentSize
526:                 + "\n"
527:                 + "Bucket area:      "
528:                 + numBuckets * 8
529:                 + "\n"
530:                 + "Record area:      "
531:                 + recordArea.getTotalSize()
532:                 + "\n"
533:                 + "Staging area:     "
534:                 + stagingSegments.size() * segmentSize
535:                 + "\n"
536:                 + "Num of elements:  "
537:                 + numElements
538:                 + "\n"
539:                 + "Holes total size: "
540:                 + holes;
541:     }
542: 
543:     /**
544:      * This class encapsulates the memory segments that belong to the record area. It - can append a
545:      * record - can overwrite a record at an arbitrary position (WARNING: the new record must have
546:      * the same size as the old one) - can be rewritten by calling resetAppendPosition - takes
547:      * memory from InPlaceMutableHashTable.freeMemorySegments on append
548:      */
549:     private final class RecordArea {
550:         private final ArrayList<MemorySegment> segments = new ArrayList<>();
551: 
552:         private final RecordAreaOutputView outView;
553:         private final RandomAccessInputView inView;
554: 
555:         private final int segmentSizeBits;
556:         private final int segmentSizeMask;
557: 
558:         private long appendPosition = 0;
559: 
560:         public RecordArea(int segmentSize) {
561:             int segmentSizeBits = MathUtils.log2strict(segmentSize);
562: 
563:             if ((segmentSize & (segmentSize - 1)) != 0) {
564:                 throw new IllegalArgumentException("Segment size must be a power of 2!");
565:             }
566: 
567:             this.segmentSizeBits = segmentSizeBits;
568:             this.segmentSizeMask = segmentSize - 1;
569: 
570:             outView = new RecordAreaOutputView(segmentSize);
571:             try {
572:                 addSegment();
573:             } catch (EOFException ex) {
574:                 throw new RuntimeException(
575:                         "Bug in InPlaceMutableHashTable: we should have caught it earlier "
576:                                 + "that we don't have enough segments.");
577:             }
578:             inView = new RandomAccessInputView(segments, segmentSize);
579:         }
580: 
581:         private void addSegment() throws EOFException {
582:             MemorySegment m = allocateSegment();
583:             if (m == null) {
584:                 throw new EOFException();
585:             }
586:             segments.add(m);
587:         }
588: 
589:         /**
590:          * Moves all its memory segments to freeMemorySegments. Warning: this will leave the
591:          * RecordArea in an unwritable state: you have to call setWritePosition before writing
592:          * again.
593:          */
594:         public void giveBackSegments() {
595:             freeMemorySegments.addAll(segments);
596:             segments.clear();
597: 
598:             resetAppendPosition();
599:         }
600: 
601:         public long getTotalSize() {
602:             return segments.size() * (long) segmentSize;
603:         }
604: 
605:         // ----------------------- Output -----------------------
606: 
607:         private void setWritePosition(long position) throws EOFException {
608:             if (position > appendPosition) {
609:                 throw new IndexOutOfBoundsException();
610:             }
611: 
612:             final int segmentIndex = (int) (position >>> segmentSizeBits);
613:             final int offset = (int) (position & segmentSizeMask);
614: 
615:             // If position == appendPosition and the last buffer is full,
616:             // then we will be seeking to the beginning of a new segment
617:             if (segmentIndex == segments.size()) {
618:                 addSegment();
619:             }
620: 
621:             outView.currentSegmentIndex = segmentIndex;
622:             outView.seekOutput(segments.get(segmentIndex), offset);
623:         }
624: 
625:         /**
626:          * Sets appendPosition and the write position to 0, so that appending starts overwriting
627:          * elements from the beginning. (This is used in rebuild.)
628:          *
629:          * <p>Note: if data was written to the area after the current appendPosition before a call
630:          * to resetAppendPosition, it should still be readable. To release the segments after the
631:          * current append position, call freeSegmentsAfterAppendPosition()
632:          */
633:         public void resetAppendPosition() {
634:             appendPosition = 0;
635: 
636:             // this is just for safety (making sure that we fail immediately
637:             // if a write happens without calling setWritePosition)
638:             outView.currentSegmentIndex = -1;
639:             outView.seekOutput(null, -1);
640:         }
641: 
642:         /**
643:          * Releases the memory segments that are after the current append position. Note: The
644:          * situation that there are segments after the current append position can arise from a call
645:          * to resetAppendPosition().
646:          */
647:         public void freeSegmentsAfterAppendPosition() {
648:             final int appendSegmentIndex = (int) (appendPosition >>> segmentSizeBits);
649:             while (segments.size() > appendSegmentIndex + 1 && !closed) {
650:                 freeMemorySegments.add(segments.get(segments.size() - 1));
651:                 segments.remove(segments.size() - 1);
652:             }
653:         }
654: 
655:         /**
656:          * Overwrites the long value at the specified position.
657:          *
658:          * @param pointer Points to the position to overwrite.
659:          * @param value The value to write.
660:          * @throws IOException
661:          */
662:         public void overwritePointerAt(long pointer, long value) throws IOException {
663:             setWritePosition(pointer);
664:             outView.writeLong(value);
665:         }
666: 
667:         /**
668:          * Overwrites a record at the specified position. The record is read from a DataInputView
669:          * (this will be the staging area). WARNING: The record must not be larger than the original
670:          * record.
671:          *
672:          * @param pointer Points to the position to overwrite.
673:          * @param input The DataInputView to read the record from
674:          * @param size The size of the record
675:          * @throws IOException
676:          */
677:         public void overwriteRecordAt(long pointer, DataInputView input, int size)
678:                 throws IOException {
679:             setWritePosition(pointer);
680:             outView.write(input, size);
681:         }
682: 
683:         /**
684:          * Appends a pointer and a record. The record is read from a DataInputView (this will be the
685:          * staging area).
686:          *
687:          * @param pointer The pointer to write (Note: this is NOT the position to write to!)
688:          * @param input The DataInputView to read the record from
689:          * @param recordSize The size of the record
690:          * @return A pointer to the written data
691:          * @throws IOException (EOFException specifically, if memory ran out)
692:          */
693:         public long appendPointerAndCopyRecord(long pointer, DataInputView input, int recordSize)
694:                 throws IOException {
695:             setWritePosition(appendPosition);
696:             final long oldLastPosition = appendPosition;
697:             outView.writeLong(pointer);
698:             outView.write(input, recordSize);
699:             appendPosition += 8 + recordSize;
700:             return oldLastPosition;
701:         }
702: 
703:         /**
704:          * Appends a pointer and a record.
705:          *
706:          * @param pointer The pointer to write (Note: this is NOT the position to write to!)
707:          * @param record The record to write
708:          * @return A pointer to the written data
709:          * @throws IOException (EOFException specifically, if memory ran out)
710:          */
711:         public long appendPointerAndRecord(long pointer, T record) throws IOException {
712:             setWritePosition(appendPosition);
713:             return noSeekAppendPointerAndRecord(pointer, record);
714:         }
715: 
716:         /**
717:          * Appends a pointer and a record. Call this function only if the write position is at the
718:          * end!
719:          *
720:          * @param pointer The pointer to write (Note: this is NOT the position to write to!)
721:          * @param record The record to write
722:          * @return A pointer to the written data
723:          * @throws IOException (EOFException specifically, if memory ran out)
724:          */
725:         public long noSeekAppendPointerAndRecord(long pointer, T record) throws IOException {
726:             final long oldLastPosition = appendPosition;
727:             final long oldPositionInSegment = outView.getCurrentPositionInSegment();
728:             final long oldSegmentIndex = outView.currentSegmentIndex;
729:             outView.writeLong(pointer);
730:             buildSideSerializer.serialize(record, outView);
731:             appendPosition +=
732:                     outView.getCurrentPositionInSegment()
733:                             - oldPositionInSegment
734:                             + outView.getSegmentSize()
735:                                     * (outView.currentSegmentIndex - oldSegmentIndex);
736:             return oldLastPosition;
737:         }
738: 
739:         public long getAppendPosition() {
740:             return appendPosition;
741:         }
742: 
743:         // ----------------------- Input -----------------------
744: 
745:         public void setReadPosition(long position) {
746:             inView.setReadPosition(position);
747:         }
748: 
749:         public long getReadPosition() {
750:             return inView.getReadPosition();
751:         }
752: 
753:         /**
754:          * Note: this is sometimes a negated length instead of a pointer (see
755:          * HashTableProber.updateMatch).
756:          */
757:         public long readPointer() throws IOException {
758:             return inView.readLong();
759:         }
760: 
761:         public T readRecord(T reuse) throws IOException {
762:             return buildSideSerializer.deserialize(reuse, inView);
763:         }
764: 
765:         public void skipBytesToRead(int numBytes) throws IOException {
766:             inView.skipBytesToRead(numBytes);
767:         }
768: 
769:         // -----------------------------------------------------
770: 
771:         private final class RecordAreaOutputView extends AbstractPagedOutputView {
772: 
773:             public int currentSegmentIndex;
774: 
775:             public RecordAreaOutputView(int segmentSize) {
776:                 super(segmentSize, 0);
777:             }
778: 
779:             @Override
780:             protected MemorySegment nextSegment(MemorySegment current, int positionInCurrent)
781:                     throws EOFException {
782:                 currentSegmentIndex++;
783:                 if (currentSegmentIndex == segments.size()) {
784:                     addSegment();
785:                 }
786:                 return segments.get(currentSegmentIndex);
787:             }
788: 
789:             @Override
790:             public void seekOutput(MemorySegment seg, int position) {
791:                 super.seekOutput(seg, position);
792:             }
793:         }
794:     }
795: 
796:     private final class StagingOutputView extends AbstractPagedOutputView {
797: 
798:         private final ArrayList<MemorySegment> segments;
799: 
800:         private final int segmentSizeBits;
801: 
802:         private int currentSegmentIndex;
803: 
804:         public StagingOutputView(ArrayList<MemorySegment> segments, int segmentSize) {
805:             super(segmentSize, 0);
806:             this.segmentSizeBits = MathUtils.log2strict(segmentSize);
807:             this.segments = segments;
808:         }
809: 
810:         /** Seeks to the beginning. */
811:         public void reset() {
812:             seekOutput(segments.get(0), 0);
813:             currentSegmentIndex = 0;
814:         }
815: 
816:         @Override
817:         protected MemorySegment nextSegment(MemorySegment current, int positionInCurrent)
818:                 throws EOFException {
819:             currentSegmentIndex++;
820:             if (currentSegmentIndex == segments.size()) {
821:                 MemorySegment m = allocateSegment();
822:                 if (m == null) {
823:                     throw new EOFException();
824:                 }
825:                 segments.add(m);
826:             }
827:             return segments.get(currentSegmentIndex);
828:         }
829: 
830:         public long getWritePosition() {
831:             return (((long) currentSegmentIndex) << segmentSizeBits)
832:                     + getCurrentPositionInSegment();
833:         }
834:     }
835: 
836:     /**
837:      * A prober for accessing the table. In addition to getMatchFor and updateMatch, it also has
838:      * insertAfterNoMatch. Warning: Don't modify the table between calling getMatchFor and the other
839:      * methods!
840:      *
841:      * @param <PT> The type of the records that we are probing with
842:      */
843:     public final class HashTableProber<PT> extends AbstractHashTableProber<PT, T> {
844: 
845:         public HashTableProber(
846:                 TypeComparator<PT> probeTypeComparator, TypePairComparator<PT, T> pairComparator) {
847:             super(probeTypeComparator, pairComparator);
848:         }
849: 
850:         private int bucketSegmentIndex;
851:         private int bucketOffset;
852:         private long curElemPtr;
853:         private long prevElemPtr;
854:         private long nextPtr;
855:         private long recordEnd;
856: 
857:         /**
858:          * Searches the hash table for the record with the given key. (If there would be multiple
859:          * matches, only one is returned.)
860:          *
861:          * @param record The record whose key we are searching for
862:          * @param targetForMatch If a match is found, it will be written here
863:          * @return targetForMatch if a match is found, otherwise null.
864:          */
865:         @Override
866:         public T getMatchFor(PT record, T targetForMatch) {
867:             if (closed) {
868:                 return null;
869:             }
870: 
871:             final int hashCode = MathUtils.jenkinsHash(probeTypeComparator.hash(record));
872:             final int bucket = hashCode & numBucketsMask;
873:             bucketSegmentIndex =
874:                     bucket >>> numBucketsPerSegmentBits; // which segment contains the bucket
875:             final MemorySegment bucketSegment = bucketSegments[bucketSegmentIndex];
876:             bucketOffset =
877:                     (bucket & numBucketsPerSegmentMask)
878:                             << bucketSizeBits; // offset of the bucket in the segment
879: 
880:             curElemPtr = bucketSegment.getLong(bucketOffset);
881: 
882:             pairComparator.setReference(record);
883: 
884:             T currentRecordInList = targetForMatch;
885: 
886:             prevElemPtr = INVALID_PREV_POINTER;
887:             try {
888:                 while (curElemPtr != END_OF_LIST && !closed) {
889:                     recordArea.setReadPosition(curElemPtr);
890:                     nextPtr = recordArea.readPointer();
891: 
892:                     currentRecordInList = recordArea.readRecord(currentRecordInList);
893:                     recordEnd = recordArea.getReadPosition();
894:                     if (pairComparator.equalToReference(currentRecordInList)) {
895:                         // we found an element with a matching key, and not just a hash collision
896:                         return currentRecordInList;
897:                     }
898: 
899:                     prevElemPtr = curElemPtr;
900:                     curElemPtr = nextPtr;
901:                 }
902:             } catch (IOException ex) {
903:                 throw new RuntimeException(
904:                         "Error deserializing record from the hashtable: " + ex.getMessage(), ex);
905:             }
906:             return null;
907:         }
908: 
909:         @Override
910:         public T getMatchFor(PT probeSideRecord) {
911:             return getMatchFor(probeSideRecord, buildSideSerializer.createInstance());
912:         }
913: 
914:         /**
915:          * This method can be called after getMatchFor returned a match. It will overwrite the
916:          * record that was found by getMatchFor. Warning: The new record should have the same key as
917:          * the old! WARNING; Don't do any modifications to the table between getMatchFor and
918:          * updateMatch!
919:          *
920:          * @param newRecord The record to override the old record with.
921:          * @throws IOException (EOFException specifically, if memory ran out)
922:          */
923:         @Override
924:         public void updateMatch(T newRecord) throws IOException {
925:             if (closed) {
926:                 return;
927:             }
928:             if (curElemPtr == END_OF_LIST) {
929:                 throw new RuntimeException(
930:                         "updateMatch was called after getMatchFor returned no match");
931:             }
932: 
933:             try {
934:                 // determine the new size
935:                 stagingSegmentsOutView.reset();
936:                 buildSideSerializer.serialize(newRecord, stagingSegmentsOutView);
937:                 final int newRecordSize = (int) stagingSegmentsOutView.getWritePosition();
938:                 stagingSegmentsInView.setReadPosition(0);
