322:         // We can't handle more than Integer.MAX_VALUE buckets (eg. because hash functions return
323:         // int)
324:         if ((long) ret * numBucketsPerSegment > Integer.MAX_VALUE) {
325:             ret = MathUtils.roundDownToPowerOf2(Integer.MAX_VALUE / numBucketsPerSegment);
326:         }
327:         return ret;
