406:         final int bucketSegmentIndex =
407:                 bucket >>> numBucketsPerSegmentBits; // which segment contains the bucket
408:         final MemorySegment bucketSegment = bucketSegments[bucketSegmentIndex];
409:         final int bucketOffset =
410:                 (bucket & numBucketsPerSegmentMask)
411:                         << bucketSizeBits; // offset of the bucket in the segment
412:         final long firstPointer = bucketSegment.getLong(bucketOffset);
413: 
414:         try {
415:             final long newFirstPointer = recordArea.appendPointerAndRecord(firstPointer, record);
416:             bucketSegment.putLong(bucketOffset, newFirstPointer);
417:         } catch (EOFException ex) {
418:             compactOrThrow();
419:             insert(record);
420:             return;
421:         }
422: 
423:         numElements++;
424:         resizeTableIfNecessary();
425:     }
426: 
427:     private void resizeTableIfNecessary() throws IOException {
428:         if (enableResize && numElements > numBuckets) {
429:             final long newNumBucketSegments = 2L * bucketSegments.length;
430:             // Checks:
431:             // - we can't handle more than Integer.MAX_VALUE buckets
432:             // - don't take more memory than the free memory we have left
433:             // - the buckets shouldn't occupy more than half of all our memory
434:             if (newNumBucketSegments * numBucketsPerSegment < Integer.MAX_VALUE
435:                     && newNumBucketSegments - bucketSegments.length < freeMemorySegments.size()
436:                     && newNumBucketSegments < numAllMemorySegments / 2) {
437:                 // do the resize
438:                 rebuild(newNumBucketSegments);
439:             }
440:         }
441:     }
442: 
443:     /**
444:      * Returns an iterator that can be used to iterate over all the elements in the table. WARNING:
445:      * Doing any other operation on the table invalidates the iterator! (Even using getMatchFor of a
446:      * prober!)
447:      *
448:      * @return the iterator
449:      */
450:     @Override
451:     public EntryIterator getEntryIterator() {
452:         return new EntryIterator();
453:     }
454: 
455:     public <PT> HashTableProber<PT> getProber(
456:             TypeComparator<PT> probeTypeComparator, TypePairComparator<PT, T> pairComparator) {
457:         return new HashTableProber<>(probeTypeComparator, pairComparator);
458:     }
459: 
460:     /**
461:      * This function reinitializes the bucket segments, reads all records from the record segments
462:      * (sequentially, without using the pointers or the buckets), and rebuilds the hash table.
463:      */
464:     private void rebuild() throws IOException {
465:         rebuild(bucketSegments.length);
466:     }
467: 
468:     /** Same as above, but the number of bucket segments of the new table can be specified. */
469:     private void rebuild(long newNumBucketSegments) throws IOException {
470:         // Get new bucket segments
471:         releaseBucketSegments();
472:         allocateBucketSegments((int) newNumBucketSegments);
473: 
474:         T record = buildSideSerializer.createInstance();
475:         try {
476:             EntryIterator iter = getEntryIterator();
477:             recordArea.resetAppendPosition();
478:             recordArea.setWritePosition(0);
479:             while ((record = iter.next(record)) != null && !closed) {
480:                 final int hashCode = MathUtils.jenkinsHash(buildSideComparator.hash(record));
481:                 final int bucket = hashCode & numBucketsMask;
482:                 final int bucketSegmentIndex =
483:                         bucket >>> numBucketsPerSegmentBits; // which segment contains the bucket
484:                 final MemorySegment bucketSegment = bucketSegments[bucketSegmentIndex];
485:                 final int bucketOffset =
486:                         (bucket & numBucketsPerSegmentMask)
487:                                 << bucketSizeBits; // offset of the bucket in the segment
488:                 final long firstPointer = bucketSegment.getLong(bucketOffset);
489: 
490:                 long ptrToAppended = recordArea.noSeekAppendPointerAndRecord(firstPointer, record);
491:                 bucketSegment.putLong(bucketOffset, ptrToAppended);
492:             }
493:             recordArea.freeSegmentsAfterAppendPosition();
494:             holes = 0;
495: 
496:         } catch (EOFException ex) {
497:             throw new RuntimeException(
498:                     "Bug in InPlaceMutableHashTable: we shouldn't get out of memory during a rebuild, "
499:                             + "because we aren't allocating any new memory.");
500:         }
501:     }
502: 
503:     /**
504:      * If there is wasted space (due to updated records not fitting in their old places), then do a
505:      * compaction. Else, throw EOFException to indicate that memory ran out.
506:      *
507:      * @throws IOException
508:      */
509:     private void compactOrThrow() throws IOException {
510:         if (holes > (double) recordArea.getTotalSize() * 0.05) {
511:             rebuild();
512:         } else {
513:             throw new EOFException(
514:                     "InPlaceMutableHashTable memory ran out. " + getMemoryConsumptionString());
515:         }
516:     }
517: 
518:     /** @return String containing a summary of the memory consumption for error messages */
519:     private String getMemoryConsumptionString() {
520:         return "InPlaceMutableHashTable memory stats:\n"
521:                 + "Total memory:     "
522:                 + numAllMemorySegments * segmentSize
523:                 + "\n"
524:                 + "Free memory:      "
525:                 + freeMemorySegments.size() * segmentSize
526:                 + "\n"
527:                 + "Bucket area:      "
528:                 + numBuckets * 8
529:                 + "\n"
530:                 + "Record area:      "
531:                 + recordArea.getTotalSize()
532:                 + "\n"
533:                 + "Staging area:     "
534:                 + stagingSegments.size() * segmentSize
535:                 + "\n"
536:                 + "Num of elements:  "
537:                 + numElements
538:                 + "\n"
539:                 + "Holes total size: "
540:                 + holes;
541:     }
