543:     /**
544:      * This class encapsulates the memory segments that belong to the record area. It - can append a
545:      * record - can overwrite a record at an arbitrary position (WARNING: the new record must have
546:      * the same size as the old one) - can be rewritten by calling resetAppendPosition - takes
547:      * memory from InPlaceMutableHashTable.freeMemorySegments on append
548:      */
549:     private final class RecordArea {
550:         private final ArrayList<MemorySegment> segments = new ArrayList<>();
551: 
552:         private final RecordAreaOutputView outView;
553:         private final RandomAccessInputView inView;
554: 
555:         private final int segmentSizeBits;
556:         private final int segmentSizeMask;
557: 
558:         private long appendPosition = 0;
559: 
560:         public RecordArea(int segmentSize) {
561:             int segmentSizeBits = MathUtils.log2strict(segmentSize);
562: 
563:             if ((segmentSize & (segmentSize - 1)) != 0) {
564:                 throw new IllegalArgumentException("Segment size must be a power of 2!");
565:             }
566: 
567:             this.segmentSizeBits = segmentSizeBits;
568:             this.segmentSizeMask = segmentSize - 1;
569: 
570:             outView = new RecordAreaOutputView(segmentSize);
571:             try {
572:                 addSegment();
573:             } catch (EOFException ex) {
574:                 throw new RuntimeException(
575:                         "Bug in InPlaceMutableHashTable: we should have caught it earlier "
576:                                 + "that we don't have enough segments.");
577:             }
578:             inView = new RandomAccessInputView(segments, segmentSize);
579:         }
580: 
581:         private void addSegment() throws EOFException {
582:             MemorySegment m = allocateSegment();
583:             if (m == null) {
584:                 throw new EOFException();
585:             }
586:             segments.add(m);
587:         }
588: 
589:         /**
590:          * Moves all its memory segments to freeMemorySegments. Warning: this will leave the
591:          * RecordArea in an unwritable state: you have to call setWritePosition before writing
592:          * again.
593:          */
594:         public void giveBackSegments() {
595:             freeMemorySegments.addAll(segments);
596:             segments.clear();
597: 
598:             resetAppendPosition();
599:         }
600: 
601:         public long getTotalSize() {
602:             return segments.size() * (long) segmentSize;
603:         }
604: 
605:         // ----------------------- Output -----------------------
606: 
607:         private void setWritePosition(long position) throws EOFException {
608:             if (position > appendPosition) {
609:                 throw new IndexOutOfBoundsException();
610:             }
611: 
612:             final int segmentIndex = (int) (position >>> segmentSizeBits);
613:             final int offset = (int) (position & segmentSizeMask);
614: 
615:             // If position == appendPosition and the last buffer is full,
616:             // then we will be seeking to the beginning of a new segment
617:             if (segmentIndex == segments.size()) {
618:                 addSegment();
619:             }
620: 
621:             outView.currentSegmentIndex = segmentIndex;
622:             outView.seekOutput(segments.get(segmentIndex), offset);
623:         }
624: 
625:         /**
626:          * Sets appendPosition and the write position to 0, so that appending starts overwriting
627:          * elements from the beginning. (This is used in rebuild.)
628:          *
629:          * <p>Note: if data was written to the area after the current appendPosition before a call
630:          * to resetAppendPosition, it should still be readable. To release the segments after the
631:          * current append position, call freeSegmentsAfterAppendPosition()
632:          */
633:         public void resetAppendPosition() {
634:             appendPosition = 0;
635: 
636:             // this is just for safety (making sure that we fail immediately
637:             // if a write happens without calling setWritePosition)
638:             outView.currentSegmentIndex = -1;
639:             outView.seekOutput(null, -1);
640:         }
641: 
642:         /**
643:          * Releases the memory segments that are after the current append position. Note: The
644:          * situation that there are segments after the current append position can arise from a call
645:          * to resetAppendPosition().
646:          */
647:         public void freeSegmentsAfterAppendPosition() {
648:             final int appendSegmentIndex = (int) (appendPosition >>> segmentSizeBits);
649:             while (segments.size() > appendSegmentIndex + 1 && !closed) {
650:                 freeMemorySegments.add(segments.get(segments.size() - 1));
651:                 segments.remove(segments.size() - 1);
652:             }
653:         }
654: 
655:         /**
656:          * Overwrites the long value at the specified position.
657:          *
658:          * @param pointer Points to the position to overwrite.
659:          * @param value The value to write.
660:          * @throws IOException
661:          */
662:         public void overwritePointerAt(long pointer, long value) throws IOException {
663:             setWritePosition(pointer);
664:             outView.writeLong(value);
665:         }
666: 
667:         /**
668:          * Overwrites a record at the specified position. The record is read from a DataInputView
669:          * (this will be the staging area). WARNING: The record must not be larger than the original
670:          * record.
671:          *
672:          * @param pointer Points to the position to overwrite.
673:          * @param input The DataInputView to read the record from
674:          * @param size The size of the record
675:          * @throws IOException
676:          */
677:         public void overwriteRecordAt(long pointer, DataInputView input, int size)
678:                 throws IOException {
679:             setWritePosition(pointer);
680:             outView.write(input, size);
681:         }
682: 
683:         /**
684:          * Appends a pointer and a record. The record is read from a DataInputView (this will be the
685:          * staging area).
686:          *
687:          * @param pointer The pointer to write (Note: this is NOT the position to write to!)
688:          * @param input The DataInputView to read the record from
689:          * @param recordSize The size of the record
690:          * @return A pointer to the written data
691:          * @throws IOException (EOFException specifically, if memory ran out)
692:          */
693:         public long appendPointerAndCopyRecord(long pointer, DataInputView input, int recordSize)
694:                 throws IOException {
695:             setWritePosition(appendPosition);
696:             final long oldLastPosition = appendPosition;
697:             outView.writeLong(pointer);
698:             outView.write(input, recordSize);
699:             appendPosition += 8 + recordSize;
700:             return oldLastPosition;
701:         }
702: 
703:         /**
704:          * Appends a pointer and a record.
705:          *
706:          * @param pointer The pointer to write (Note: this is NOT the position to write to!)
707:          * @param record The record to write
708:          * @return A pointer to the written data
709:          * @throws IOException (EOFException specifically, if memory ran out)
710:          */
711:         public long appendPointerAndRecord(long pointer, T record) throws IOException {
712:             setWritePosition(appendPosition);
713:             return noSeekAppendPointerAndRecord(pointer, record);
714:         }
715: 
716:         /**
717:          * Appends a pointer and a record. Call this function only if the write position is at the
718:          * end!
719:          *
720:          * @param pointer The pointer to write (Note: this is NOT the position to write to!)
721:          * @param record The record to write
722:          * @return A pointer to the written data
723:          * @throws IOException (EOFException specifically, if memory ran out)
724:          */
725:         public long noSeekAppendPointerAndRecord(long pointer, T record) throws IOException {
726:             final long oldLastPosition = appendPosition;
727:             final long oldPositionInSegment = outView.getCurrentPositionInSegment();
728:             final long oldSegmentIndex = outView.currentSegmentIndex;
729:             outView.writeLong(pointer);
730:             buildSideSerializer.serialize(record, outView);
731:             appendPosition +=
732:                     outView.getCurrentPositionInSegment()
733:                             - oldPositionInSegment
734:                             + outView.getSegmentSize()
735:                                     * (outView.currentSegmentIndex - oldSegmentIndex);
736:             return oldLastPosition;
737:         }
738: 
739:         public long getAppendPosition() {
740:             return appendPosition;
741:         }
742: 
743:         // ----------------------- Input -----------------------
744: 
745:         public void setReadPosition(long position) {
746:             inView.setReadPosition(position);
747:         }
748: 
749:         public long getReadPosition() {
750:             return inView.getReadPosition();
751:         }
752: 
753:         /**
754:          * Note: this is sometimes a negated length instead of a pointer (see
755:          * HashTableProber.updateMatch).
756:          */
757:         public long readPointer() throws IOException {
758:             return inView.readLong();
759:         }
760: 
761:         public T readRecord(T reuse) throws IOException {
762:             return buildSideSerializer.deserialize(reuse, inView);
763:         }
764: 
765:         public void skipBytesToRead(int numBytes) throws IOException {
766:             inView.skipBytesToRead(numBytes);
767:         }
768: 
769:         // -----------------------------------------------------
770: 
771:         private final class RecordAreaOutputView extends AbstractPagedOutputView {
772: 
773:             public int currentSegmentIndex;
774: 
775:             public RecordAreaOutputView(int segmentSize) {
776:                 super(segmentSize, 0);
777:             }
778: 
779:             @Override
780:             protected MemorySegment nextSegment(MemorySegment current, int positionInCurrent)
781:                     throws EOFException {
782:                 currentSegmentIndex++;
783:                 if (currentSegmentIndex == segments.size()) {
784:                     addSegment();
785:                 }
786:                 return segments.get(currentSegmentIndex);
787:             }
788: 
789:             @Override
790:             public void seekOutput(MemorySegment seg, int position) {
791:                 super.seekOutput(seg, position);
792:             }
793:         }
794:     }
795: 
796:     private final class StagingOutputView extends AbstractPagedOutputView {
797: 
798:         private final ArrayList<MemorySegment> segments;
799: 
800:         private final int segmentSizeBits;
801: 
802:         private int currentSegmentIndex;
803: 
804:         public StagingOutputView(ArrayList<MemorySegment> segments, int segmentSize) {
805:             super(segmentSize, 0);
806:             this.segmentSizeBits = MathUtils.log2strict(segmentSize);
807:             this.segments = segments;
808:         }
809: 
810:         /** Seeks to the beginning. */
811:         public void reset() {
812:             seekOutput(segments.get(0), 0);
813:             currentSegmentIndex = 0;
814:         }
815: 
816:         @Override
817:         protected MemorySegment nextSegment(MemorySegment current, int positionInCurrent)
818:                 throws EOFException {
819:             currentSegmentIndex++;
820:             if (currentSegmentIndex == segments.size()) {
821:                 MemorySegment m = allocateSegment();
822:                 if (m == null) {
823:                     throw new EOFException();
824:                 }
825:                 segments.add(m);
826:             }
827:             return segments.get(currentSegmentIndex);
828:         }
829: 
830:         public long getWritePosition() {
831:             return (((long) currentSegmentIndex) << segmentSizeBits)
832:                     + getCurrentPositionInSegment();
833:         }
834:     }
