836:     /**
837:      * A prober for accessing the table. In addition to getMatchFor and updateMatch, it also has
838:      * insertAfterNoMatch. Warning: Don't modify the table between calling getMatchFor and the other
839:      * methods!
840:      *
841:      * @param <PT> The type of the records that we are probing with
842:      */
843:     public final class HashTableProber<PT> extends AbstractHashTableProber<PT, T> {
844: 
845:         public HashTableProber(
846:                 TypeComparator<PT> probeTypeComparator, TypePairComparator<PT, T> pairComparator) {
847:             super(probeTypeComparator, pairComparator);
848:         }
849: 
850:         private int bucketSegmentIndex;
851:         private int bucketOffset;
852:         private long curElemPtr;
853:         private long prevElemPtr;
854:         private long nextPtr;
855:         private long recordEnd;
856: 
857:         /**
858:          * Searches the hash table for the record with the given key. (If there would be multiple
859:          * matches, only one is returned.)
860:          *
861:          * @param record The record whose key we are searching for
862:          * @param targetForMatch If a match is found, it will be written here
863:          * @return targetForMatch if a match is found, otherwise null.
864:          */
865:         @Override
866:         public T getMatchFor(PT record, T targetForMatch) {
867:             if (closed) {
868:                 return null;
869:             }
870: 
871:             final int hashCode = MathUtils.jenkinsHash(probeTypeComparator.hash(record));
872:             final int bucket = hashCode & numBucketsMask;
873:             bucketSegmentIndex =
874:                     bucket >>> numBucketsPerSegmentBits; // which segment contains the bucket
875:             final MemorySegment bucketSegment = bucketSegments[bucketSegmentIndex];
876:             bucketOffset =
877:                     (bucket & numBucketsPerSegmentMask)
878:                             << bucketSizeBits; // offset of the bucket in the segment
879: 
880:             curElemPtr = bucketSegment.getLong(bucketOffset);
881: 
882:             pairComparator.setReference(record);
883: 
884:             T currentRecordInList = targetForMatch;
885: 
886:             prevElemPtr = INVALID_PREV_POINTER;
887:             try {
888:                 while (curElemPtr != END_OF_LIST && !closed) {
889:                     recordArea.setReadPosition(curElemPtr);
890:                     nextPtr = recordArea.readPointer();
891: 
892:                     currentRecordInList = recordArea.readRecord(currentRecordInList);
893:                     recordEnd = recordArea.getReadPosition();
894:                     if (pairComparator.equalToReference(currentRecordInList)) {
895:                         // we found an element with a matching key, and not just a hash collision
896:                         return currentRecordInList;
897:                     }
898: 
899:                     prevElemPtr = curElemPtr;
900:                     curElemPtr = nextPtr;
901:                 }
902:             } catch (IOException ex) {
903:                 throw new RuntimeException(
904:                         "Error deserializing record from the hashtable: " + ex.getMessage(), ex);
905:             }
906:             return null;
907:         }
908: 
909:         @Override
910:         public T getMatchFor(PT probeSideRecord) {
911:             return getMatchFor(probeSideRecord, buildSideSerializer.createInstance());
912:         }
913: 
914:         /**
915:          * This method can be called after getMatchFor returned a match. It will overwrite the
916:          * record that was found by getMatchFor. Warning: The new record should have the same key as
917:          * the old! WARNING; Don't do any modifications to the table between getMatchFor and
918:          * updateMatch!
919:          *
920:          * @param newRecord The record to override the old record with.
921:          * @throws IOException (EOFException specifically, if memory ran out)
922:          */
923:         @Override
924:         public void updateMatch(T newRecord) throws IOException {
925:             if (closed) {
926:                 return;
927:             }
928:             if (curElemPtr == END_OF_LIST) {
929:                 throw new RuntimeException(
930:                         "updateMatch was called after getMatchFor returned no match");
931:             }
932: 
933:             try {
934:                 // determine the new size
935:                 stagingSegmentsOutView.reset();
936:                 buildSideSerializer.serialize(newRecord, stagingSegmentsOutView);
937:                 final int newRecordSize = (int) stagingSegmentsOutView.getWritePosition();
938:                 stagingSegmentsInView.setReadPosition(0);
939: 
940:                 // Determine the size of the place of the old record.
941:                 final int oldRecordSize = (int) (recordEnd - (curElemPtr + RECORD_OFFSET_IN_LINK));
942: 
943:                 if (newRecordSize == oldRecordSize) {
944:                     // overwrite record at its original place
945:                     recordArea.overwriteRecordAt(
946:                             curElemPtr + RECORD_OFFSET_IN_LINK,
947:                             stagingSegmentsInView,
948:                             newRecordSize);
949:                 } else {
950:                     // new record has a different size than the old one, append new at the end of
951:                     // the record area.
952:                     // Note: we have to do this, even if the new record is smaller, because
953:                     // otherwise EntryIterator
954:                     // wouldn't know the size of this place, and wouldn't know where does the next
955:                     // record start.
956: 
957:                     final long pointerToAppended =
958:                             recordArea.appendPointerAndCopyRecord(
959:                                     nextPtr, stagingSegmentsInView, newRecordSize);
960: 
961:                     // modify the pointer in the previous link
962:                     if (prevElemPtr == INVALID_PREV_POINTER) {
963:                         // list had only one element, so prev is in the bucketSegments
964:                         bucketSegments[bucketSegmentIndex].putLong(bucketOffset, pointerToAppended);
965:                     } else {
966:                         recordArea.overwritePointerAt(prevElemPtr, pointerToAppended);
967:                     }
968: 
969:                     // write the negated size of the hole to the place where the next pointer was,
970:                     // so that EntryIterator
971:                     // will know the size of the place without reading the old record.
972:                     // The negative sign will mean that the record is abandoned, and the
973:                     // the -1 is for avoiding trouble in case of a record having 0 size. (though I
974:                     // think this should
975:                     // never actually happen)
976:                     // Note: the last record in the record area can't be abandoned. (EntryIterator
977:                     // makes use of this fact.)
978:                     recordArea.overwritePointerAt(curElemPtr, -oldRecordSize - 1);
979: 
980:                     holes += oldRecordSize;
981:                 }
982:             } catch (EOFException ex) {
983:                 compactOrThrow();
984:                 insertOrReplaceRecord(newRecord);
985:             }
986:         }
987: 
988:         /**
989:          * This method can be called after getMatchFor returned null. It inserts the given record to
990:          * the hash table. Important: The given record should have the same key as the record that
991:          * was given to getMatchFor! WARNING; Don't do any modifications to the table between
992:          * getMatchFor and insertAfterNoMatch!
993:          *
994:          * @throws IOException (EOFException specifically, if memory ran out)
995:          */
996:         public void insertAfterNoMatch(T record) throws IOException {
997:             if (closed) {
998:                 return;
999:             }
1000: 
1001:             // create new link
1002:             long pointerToAppended;
1003:             try {
1004:                 pointerToAppended = recordArea.appendPointerAndRecord(END_OF_LIST, record);
1005:             } catch (EOFException ex) {
1006:                 compactOrThrow();
1007:                 insert(record);
1008:                 return;
1009:             }
1010: 
1011:             // add new link to the end of the list
1012:             if (prevElemPtr == INVALID_PREV_POINTER) {
1013:                 // list was empty
1014:                 bucketSegments[bucketSegmentIndex].putLong(bucketOffset, pointerToAppended);
1015:             } else {
1016:                 // update the pointer of the last element of the list.
1017:                 recordArea.overwritePointerAt(prevElemPtr, pointerToAppended);
1018:             }
1019: 
1020:             numElements++;
1021:             resizeTableIfNecessary();
1022:         }
1023:     }
1024: 
1025:     /**
1026:      * WARNING: Doing any other operation on the table invalidates the iterator! (Even using
1027:      * getMatchFor of a prober!)
1028:      */
1029:     public final class EntryIterator implements MutableObjectIterator<T> {
1030: 
1031:         private final long endPosition;
1032: 
1033:         public EntryIterator() {
1034:             endPosition = recordArea.getAppendPosition();
1035:             if (endPosition == 0) {
1036:                 return;
1037:             }
1038:             recordArea.setReadPosition(0);
1039:         }
1040: 
1041:         @Override
1042:         public T next(T reuse) throws IOException {
1043:             if (endPosition != 0 && recordArea.getReadPosition() < endPosition) {
1044:                 // Loop until we find a non-abandoned record.
1045:                 // Note: the last record in the record area can't be abandoned.
1046:                 while (!closed) {
1047:                     final long pointerOrNegatedLength = recordArea.readPointer();
1048:                     final boolean isAbandoned = pointerOrNegatedLength < 0;
1049:                     if (!isAbandoned) {
1050:                         reuse = recordArea.readRecord(reuse);
1051:                         return reuse;
1052:                     } else {
1053:                         // pointerOrNegatedLength is storing a length, because the record was
1054:                         // abandoned.
1055:                         recordArea.skipBytesToRead((int) -(pointerOrNegatedLength + 1));
1056:                     }
1057:                 }
1058:                 return null; // (we were closed)
1059:             } else {
1060:                 return null;
1061:             }
1062:         }
1063: 
1064:         @Override
1065:         public T next() throws IOException {
1066:             return next(buildSideSerializer.createInstance());
1067:         }
