38: /** */
39: public final class NormalizedKeySorter<T> implements InMemorySorter<T> {
40: 
41:     private static final Logger LOG = LoggerFactory.getLogger(NormalizedKeySorter.class);
42: 
43:     private static final int OFFSET_LEN = 8;
44: 
45:     private static final int DEFAULT_MAX_NORMALIZED_KEY_LEN = 16;
46: 
47:     private static final int MAX_NORMALIZED_KEY_LEN_PER_ELEMENT = 8;
48: 
49:     private static final int MIN_REQUIRED_BUFFERS = 3;
50: 
51:     private static final int LARGE_RECORD_THRESHOLD = 10 * 1024 * 1024;
52: 
53:     private static final long LARGE_RECORD_TAG = 1L << 63;
54: 
55:     private static final long POINTER_MASK = LARGE_RECORD_TAG - 1;
56: 
57:     // ------------------------------------------------------------------------
58:     //                               Members
59:     // ------------------------------------------------------------------------
60: 
61:     private final byte[] swapBuffer;
62: 
63:     private final TypeSerializer<T> serializer;
64: 
65:     private final TypeComparator<T> comparator;
66: 
67:     private final SimpleCollectingOutputView recordCollector;
68: 
69:     private final RandomAccessInputView recordBuffer;
70: 
71:     private final RandomAccessInputView recordBufferForComparison;
72: 
73:     private MemorySegment currentSortIndexSegment;
74: 
75:     private final ArrayList<MemorySegment> freeMemory;
76: 
77:     private final ArrayList<MemorySegment> sortIndex;
78: 
79:     private final ArrayList<MemorySegment> recordBufferSegments;
80: 
81:     private long currentDataBufferOffset;
82: 
83:     private long sortIndexBytes;
84: 
85:     private int currentSortIndexOffset;
86: 
87:     private int numRecords;
88: 
89:     private final int numKeyBytes;
90: 
91:     private final int indexEntrySize;
92: 
93:     private final int indexEntriesPerSegment;
94: 
95:     private final int lastIndexEntryOffset;
96: 
97:     private final int segmentSize;
98: 
99:     private final int totalNumBuffers;
100: 
101:     private final boolean normalizedKeyFullyDetermines;
102: 
103:     private final boolean useNormKeyUninverted;
104: 
105:     // -------------------------------------------------------------------------
106:     // Constructors / Destructors
107:     // -------------------------------------------------------------------------
108: 
109:     public NormalizedKeySorter(
110:             TypeSerializer<T> serializer,
111:             TypeComparator<T> comparator,
112:             List<MemorySegment> memory) {
113:         this(serializer, comparator, memory, DEFAULT_MAX_NORMALIZED_KEY_LEN);
114:     }
115: 
116:     public NormalizedKeySorter(
117:             TypeSerializer<T> serializer,
118:             TypeComparator<T> comparator,
119:             List<MemorySegment> memory,
120:             int maxNormalizedKeyBytes) {
121:         if (serializer == null || comparator == null || memory == null) {
122:             throw new NullPointerException();
123:         }
124:         if (maxNormalizedKeyBytes < 0) {
125:             throw new IllegalArgumentException(
126:                     "Maximal number of normalized key bytes must not be negative.");
127:         }
128: 
129:         this.serializer = serializer;
130:         this.comparator = comparator;
131:         this.useNormKeyUninverted = !comparator.invertNormalizedKey();
132: 
133:         // check the size of the first buffer and record it. all further buffers must have the same
134:         // size.
135:         // the size must also be a power of 2
136:         this.totalNumBuffers = memory.size();
137:         if (this.totalNumBuffers < MIN_REQUIRED_BUFFERS) {
138:             throw new IllegalArgumentException(
139:                     "Normalized-Key sorter requires at least "
140:                             + MIN_REQUIRED_BUFFERS
141:                             + " memory buffers.");
142:         }
143:         this.segmentSize = memory.get(0).size();
144:         this.freeMemory = new ArrayList<MemorySegment>(memory);
145: 
146:         // create the buffer collections
147:         this.sortIndex = new ArrayList<MemorySegment>(16);
148:         this.recordBufferSegments = new ArrayList<MemorySegment>(16);
149: 
150:         // the views for the record collections
151:         this.recordCollector =
152:                 new SimpleCollectingOutputView(
153:                         this.recordBufferSegments,
154:                         new ListMemorySegmentSource(this.freeMemory),
155:                         this.segmentSize);
156:         this.recordBuffer = new RandomAccessInputView(this.recordBufferSegments, this.segmentSize);
157:         this.recordBufferForComparison =
158:                 new RandomAccessInputView(this.recordBufferSegments, this.segmentSize);
159: 
160:         // set up normalized key characteristics
161:         if (this.comparator.supportsNormalizedKey()) {
162:             // compute the max normalized key length
163:             int numPartialKeys;
164:             try {
165:                 numPartialKeys = this.comparator.getFlatComparators().length;
166:             } catch (Throwable t) {
167:                 numPartialKeys = 1;
168:             }
169: 
170:             int maxLen =
171:                     Math.min(
172:                             maxNormalizedKeyBytes,
173:                             MAX_NORMALIZED_KEY_LEN_PER_ELEMENT * numPartialKeys);
174: 
175:             this.numKeyBytes = Math.min(this.comparator.getNormalizeKeyLen(), maxLen);
176:             this.normalizedKeyFullyDetermines =
177:                     !this.comparator.isNormalizedKeyPrefixOnly(this.numKeyBytes);
178:         } else {
179:             this.numKeyBytes = 0;
180:             this.normalizedKeyFullyDetermines = false;
181:         }
182: 
183:         // compute the index entry size and limits
184:         this.indexEntrySize = this.numKeyBytes + OFFSET_LEN;
185:         this.indexEntriesPerSegment = this.segmentSize / this.indexEntrySize;
186:         this.lastIndexEntryOffset = (this.indexEntriesPerSegment - 1) * this.indexEntrySize;
187:         this.swapBuffer = new byte[this.indexEntrySize];
188: 
189:         // set to initial state
190:         this.currentSortIndexSegment = nextMemorySegment();
191:         this.sortIndex.add(this.currentSortIndexSegment);
192:     }
193: 
194:     @Override
195:     public int recordSize() {
196:         return indexEntrySize;
197:     }
198: 
199:     @Override
200:     public int recordsPerSegment() {
201:         return indexEntriesPerSegment;
202:     }
