204:     // -------------------------------------------------------------------------
205:     // Memory Segment
206:     // -------------------------------------------------------------------------
207: 
208:     /**
209:      * Resets the sort buffer back to the state where it is empty. All contained data is discarded.
210:      */
211:     @Override
212:     public void reset() {
213:         // reset all offsets
214:         this.numRecords = 0;
215:         this.currentSortIndexOffset = 0;
216:         this.currentDataBufferOffset = 0;
217:         this.sortIndexBytes = 0;
218: 
219:         // return all memory
220:         this.freeMemory.addAll(this.sortIndex);
221:         this.freeMemory.addAll(this.recordBufferSegments);
222:         this.sortIndex.clear();
223:         this.recordBufferSegments.clear();
224: 
225:         // grab first buffers
226:         this.currentSortIndexSegment = nextMemorySegment();
227:         this.sortIndex.add(this.currentSortIndexSegment);
228:         this.recordCollector.reset();
229:     }
230: 
231:     /**
232:      * Checks whether the buffer is empty.
233:      *
234:      * @return True, if no record is contained, false otherwise.
235:      */
236:     @Override
237:     public boolean isEmpty() {
238:         return this.numRecords == 0;
239:     }
240: 
241:     @Override
242:     public void dispose() {
243:         this.freeMemory.clear();
244:         this.recordBufferSegments.clear();
245:         this.sortIndex.clear();
246:     }
247: 
248:     @Override
249:     public long getCapacity() {
250:         return ((long) this.totalNumBuffers) * this.segmentSize;
251:     }
252: 
253:     @Override
254:     public long getOccupancy() {
255:         return this.currentDataBufferOffset + this.sortIndexBytes;
256:     }
257: 
258:     // -------------------------------------------------------------------------
259:     // Retrieving and Writing
260:     // -------------------------------------------------------------------------
261: 
262:     @Override
263:     public T getRecord(int logicalPosition) throws IOException {
264:         return getRecordFromBuffer(readPointer(logicalPosition));
265:     }
266: 
267:     @Override
268:     public T getRecord(T reuse, int logicalPosition) throws IOException {
269:         return getRecordFromBuffer(reuse, readPointer(logicalPosition));
270:     }
271: 
272:     /**
273:      * Writes a given record to this sort buffer. The written record will be appended and take the
274:      * last logical position.
275:      *
276:      * @param record The record to be written.
277:      * @return True, if the record was successfully written, false, if the sort buffer was full.
278:      * @throws IOException Thrown, if an error occurred while serializing the record into the
279:      *     buffers.
280:      */
281:     @Override
282:     public boolean write(T record) throws IOException {
283:         // check whether we need a new memory segment for the sort index
284:         if (this.currentSortIndexOffset > this.lastIndexEntryOffset) {
285:             if (memoryAvailable()) {
286:                 this.currentSortIndexSegment = nextMemorySegment();
287:                 this.sortIndex.add(this.currentSortIndexSegment);
288:                 this.currentSortIndexOffset = 0;
289:                 this.sortIndexBytes += this.segmentSize;
290:             } else {
291:                 return false;
292:             }
293:         }
294: 
295:         // serialize the record into the data buffers
296:         try {
297:             this.serializer.serialize(record, this.recordCollector);
298:         } catch (EOFException e) {
299:             return false;
300:         }
301: 
302:         final long newOffset = this.recordCollector.getCurrentOffset();
303:         final boolean shortRecord =
304:                 newOffset - this.currentDataBufferOffset < LARGE_RECORD_THRESHOLD;
305: 
306:         if (!shortRecord && LOG.isDebugEnabled()) {
307:             LOG.debug("Put a large record ( >" + LARGE_RECORD_THRESHOLD + " into the sort buffer");
308:         }
309: 
310:         // add the pointer and the normalized key
311:         this.currentSortIndexSegment.putLong(
312:                 this.currentSortIndexOffset,
313:                 shortRecord
314:                         ? this.currentDataBufferOffset
315:                         : (this.currentDataBufferOffset | LARGE_RECORD_TAG));
316: 
317:         if (this.numKeyBytes != 0) {
318:             this.comparator.putNormalizedKey(
319:                     record,
320:                     this.currentSortIndexSegment,
321:                     this.currentSortIndexOffset + OFFSET_LEN,
322:                     this.numKeyBytes);
323:         }
324: 
325:         this.currentSortIndexOffset += this.indexEntrySize;
326:         this.currentDataBufferOffset = newOffset;
327:         this.numRecords++;
328:         return true;
329:     }
