331:     // ------------------------------------------------------------------------
332:     //                           Access Utilities
333:     // ------------------------------------------------------------------------
334: 
335:     private long readPointer(int logicalPosition) {
336:         if (logicalPosition < 0 || logicalPosition >= this.numRecords) {
337:             throw new IndexOutOfBoundsException();
338:         }
339: 
340:         final int bufferNum = logicalPosition / this.indexEntriesPerSegment;
341:         final int segmentOffset = logicalPosition % this.indexEntriesPerSegment;
342: 
343:         return (this.sortIndex.get(bufferNum).getLong(segmentOffset * this.indexEntrySize))
344:                 & POINTER_MASK;
345:     }
346: 
347:     private T getRecordFromBuffer(T reuse, long pointer) throws IOException {
348:         this.recordBuffer.setReadPosition(pointer);
349:         return this.serializer.deserialize(reuse, this.recordBuffer);
350:     }
351: 
352:     private T getRecordFromBuffer(long pointer) throws IOException {
353:         this.recordBuffer.setReadPosition(pointer);
354:         return this.serializer.deserialize(this.recordBuffer);
355:     }
356: 
357:     private int compareRecords(long pointer1, long pointer2) {
358:         this.recordBuffer.setReadPosition(pointer1);
359:         this.recordBufferForComparison.setReadPosition(pointer2);
360: 
361:         try {
362:             return this.comparator.compareSerialized(
363:                     this.recordBuffer, this.recordBufferForComparison);
364:         } catch (IOException ioex) {
365:             throw new RuntimeException("Error comparing two records.", ioex);
366:         }
367:     }
368: 
369:     private boolean memoryAvailable() {
370:         return !this.freeMemory.isEmpty();
371:     }
372: 
373:     private MemorySegment nextMemorySegment() {
374:         return this.freeMemory.remove(this.freeMemory.size() - 1);
375:     }
