377:     // -------------------------------------------------------------------------
378:     // Indexed Sorting
379:     // -------------------------------------------------------------------------
380: 
381:     @Override
382:     public int compare(int i, int j) {
383:         final int segmentNumberI = i / this.indexEntriesPerSegment;
384:         final int segmentOffsetI = (i % this.indexEntriesPerSegment) * this.indexEntrySize;
385: 
386:         final int segmentNumberJ = j / this.indexEntriesPerSegment;
387:         final int segmentOffsetJ = (j % this.indexEntriesPerSegment) * this.indexEntrySize;
388: 
389:         return compare(segmentNumberI, segmentOffsetI, segmentNumberJ, segmentOffsetJ);
390:     }
391: 
392:     @Override
393:     public int compare(
394:             int segmentNumberI, int segmentOffsetI, int segmentNumberJ, int segmentOffsetJ) {
395:         final MemorySegment segI = this.sortIndex.get(segmentNumberI);
396:         final MemorySegment segJ = this.sortIndex.get(segmentNumberJ);
397: 
398:         int val =
399:                 segI.compare(
400:                         segJ,
401:                         segmentOffsetI + OFFSET_LEN,
402:                         segmentOffsetJ + OFFSET_LEN,
403:                         this.numKeyBytes);
404: 
405:         if (val != 0 || this.normalizedKeyFullyDetermines) {
406:             return this.useNormKeyUninverted ? val : -val;
407:         }
408: 
409:         final long pointerI = segI.getLong(segmentOffsetI) & POINTER_MASK;
410:         final long pointerJ = segJ.getLong(segmentOffsetJ) & POINTER_MASK;
411: 
412:         return compareRecords(pointerI, pointerJ);
413:     }
414: 
415:     @Override
416:     public void swap(int i, int j) {
417:         final int segmentNumberI = i / this.indexEntriesPerSegment;
418:         final int segmentOffsetI = (i % this.indexEntriesPerSegment) * this.indexEntrySize;
419: 
420:         final int segmentNumberJ = j / this.indexEntriesPerSegment;
421:         final int segmentOffsetJ = (j % this.indexEntriesPerSegment) * this.indexEntrySize;
422: 
423:         swap(segmentNumberI, segmentOffsetI, segmentNumberJ, segmentOffsetJ);
424:     }
425: 
426:     @Override
427:     public void swap(
428:             int segmentNumberI, int segmentOffsetI, int segmentNumberJ, int segmentOffsetJ) {
429:         final MemorySegment segI = this.sortIndex.get(segmentNumberI);
430:         final MemorySegment segJ = this.sortIndex.get(segmentNumberJ);
431: 
432:         segI.swapBytes(this.swapBuffer, segJ, segmentOffsetI, segmentOffsetJ, this.indexEntrySize);
433:     }
434: 
435:     @Override
436:     public int size() {
437:         return this.numRecords;
438:     }
