442:     /**
443:      * Gets an iterator over all records in this buffer in their logical order.
444:      *
445:      * @return An iterator returning the records in their logical order.
446:      */
447:     @Override
448:     public final MutableObjectIterator<T> getIterator() {
449:         return new MutableObjectIterator<T>() {
450:             private final int size = size();
451:             private int current = 0;
452: 
453:             private int currentSegment = 0;
454:             private int currentOffset = 0;
455: 
456:             private MemorySegment currentIndexSegment = sortIndex.get(0);
457: 
458:             @Override
459:             public T next(T target) {
460:                 if (this.current < this.size) {
461:                     this.current++;
462:                     if (this.currentOffset > lastIndexEntryOffset) {
463:                         this.currentOffset = 0;
464:                         this.currentIndexSegment = sortIndex.get(++this.currentSegment);
465:                     }
466: 
467:                     long pointer =
468:                             this.currentIndexSegment.getLong(this.currentOffset) & POINTER_MASK;
469:                     this.currentOffset += indexEntrySize;
470: 
471:                     try {
472:                         return getRecordFromBuffer(target, pointer);
473:                     } catch (IOException ioe) {
474:                         throw new RuntimeException(ioe);
475:                     }
476:                 } else {
477:                     return null;
478:                 }
479:             }
480: 
481:             @Override
482:             public T next() {
483:                 if (this.current < this.size) {
484:                     this.current++;
485:                     if (this.currentOffset > lastIndexEntryOffset) {
486:                         this.currentOffset = 0;
487:                         this.currentIndexSegment = sortIndex.get(++this.currentSegment);
488:                     }
489: 
490:                     long pointer = this.currentIndexSegment.getLong(this.currentOffset);
491:                     this.currentOffset += indexEntrySize;
492: 
493:                     try {
494:                         return getRecordFromBuffer(pointer);
495:                     } catch (IOException ioe) {
496:                         throw new RuntimeException(ioe);
497:                     }
498:                 } else {
499:                     return null;
500:                 }
501:             }
502:         };
503:     }
