505:     // ------------------------------------------------------------------------
506:     //                Writing to a DataOutputView
507:     // ------------------------------------------------------------------------
508: 
509:     /**
510:      * Writes the records in this buffer in their logical order to the given output.
511:      *
512:      * @param output The output view to write the records to.
513:      * @throws IOException Thrown, if an I/O exception occurred writing to the output view.
514:      */
515:     @Override
516:     public void writeToOutput(ChannelWriterOutputView output) throws IOException {
517:         writeToOutput(output, null);
518:     }
519: 
520:     @Override
521:     public void writeToOutput(
522:             ChannelWriterOutputView output, LargeRecordHandler<T> largeRecordsOutput)
523:             throws IOException {
524:         if (LOG.isDebugEnabled()) {
525:             if (largeRecordsOutput == null) {
526:                 LOG.debug("Spilling sort buffer without large record handling.");
527:             } else {
528:                 LOG.debug("Spilling sort buffer with large record handling.");
529:             }
530:         }
531: 
532:         final int numRecords = this.numRecords;
533:         int currentMemSeg = 0;
534:         int currentRecord = 0;
535: 
536:         while (currentRecord < numRecords) {
537:             final MemorySegment currentIndexSegment = this.sortIndex.get(currentMemSeg++);
538: 
539:             // go through all records in the memory segment
540:             for (int offset = 0;
541:                     currentRecord < numRecords && offset <= this.lastIndexEntryOffset;
542:                     currentRecord++, offset += this.indexEntrySize) {
543:                 final long pointer = currentIndexSegment.getLong(offset);
544: 
545:                 // small records go into the regular spill file, large records into the special code
546:                 // path
547:                 if (pointer >= 0 || largeRecordsOutput == null) {
548:                     this.recordBuffer.setReadPosition(pointer);
549:                     this.serializer.copy(this.recordBuffer, output);
550:                 } else {
551: 
552:                     if (LOG.isDebugEnabled()) {
553:                         LOG.debug("Spilling large record to large record fetch file.");
554:                     }
555: 
556:                     this.recordBuffer.setReadPosition(pointer & POINTER_MASK);
557:                     T record = this.serializer.deserialize(this.recordBuffer);
558:                     largeRecordsOutput.addRecord(record);
559:                 }
560:             }
561:         }
562:     }
563: 
564:     /**
565:      * Writes a subset of the records in this buffer in their logical order to the given output.
566:      *
567:      * @param output The output view to write the records to.
568:      * @param start The logical start position of the subset.
569:      * @param num The number of elements to write.
570:      * @throws IOException Thrown, if an I/O exception occurred writing to the output view.
571:      */
572:     @Override
573:     public void writeToOutput(final ChannelWriterOutputView output, final int start, int num)
574:             throws IOException {
575:         int currentMemSeg = start / this.indexEntriesPerSegment;
576:         int offset = (start % this.indexEntriesPerSegment) * this.indexEntrySize;
577: 
578:         while (num > 0) {
579:             final MemorySegment currentIndexSegment = this.sortIndex.get(currentMemSeg++);
580:             // check whether we have a full or partially full segment
581:             if (num >= this.indexEntriesPerSegment && offset == 0) {
582:                 // full segment
583:                 for (; offset <= this.lastIndexEntryOffset; offset += this.indexEntrySize) {
584:                     final long pointer = currentIndexSegment.getLong(offset) & POINTER_MASK;
585:                     this.recordBuffer.setReadPosition(pointer);
586:                     this.serializer.copy(this.recordBuffer, output);
587:                 }
588:                 num -= this.indexEntriesPerSegment;
589:             } else {
590:                 // partially filled segment
591:                 for (;
592:                         num > 0 && offset <= this.lastIndexEntryOffset;
593:                         num--, offset += this.indexEntrySize) {
594:                     final long pointer = currentIndexSegment.getLong(offset) & POINTER_MASK;
595:                     this.recordBuffer.setReadPosition(pointer);
596:                     this.serializer.copy(this.recordBuffer, output);
597:                 }
598:             }
599:             offset = 0;
600:         }
601:     }
602: }
