73:     public BufferManager(
74:             MemorySegmentProvider globalPool, InputChannel inputChannel, int numRequiredBuffers) {
75: 
76:         this.globalPool = checkNotNull(globalPool);
77:         this.inputChannel = checkNotNull(inputChannel);
78:         checkArgument(numRequiredBuffers >= 0);
79:         this.numberOfRequiredMemorySegments = numRequiredBuffers;
80:     }
