82:     // ------------------------------------------------------------------------
83:     // Buffer request
84:     // ------------------------------------------------------------------------
85: 
86:     @Nullable
87:     Buffer requestBuffer() {
88:         synchronized (bufferQueue) {
89:             // decrease the number of buffers require to avoid the possibility of
90:             // allocating more than required buffers after the buffer is taken
91:             --numberOfRequiredMemorySegments;
92:             return bufferQueue.takeBuffer();
93:         }
94:     }
