96:     Buffer requestBufferBlocking() throws InterruptedException {
97:         synchronized (bufferQueue) {
98:             Buffer buffer;
99:             while ((buffer = bufferQueue.takeBuffer()) == null) {
100:                 if (inputChannel.isReleased()) {
101:                     throw new CancelTaskException(
102:                             "Input channel ["
103:                                     + inputChannel.channelInfo
104:                                     + "] has already been released.");
105:                 }
106:                 if (!isWaitingForFloatingBuffers) {
107:                     BufferPool bufferPool = inputChannel.inputGate.getBufferPool();
108:                     buffer = bufferPool.requestBuffer();
109:                     if (buffer == null && shouldContinueRequest(bufferPool)) {
110:                         continue;
111:                     }
112:                 }
113: 
114:                 if (buffer != null) {
115:                     return buffer;
116:                 }
117:                 bufferQueue.wait();
118:             }
119:             return buffer;
120:         }
121:     }
122: 
123:     private boolean shouldContinueRequest(BufferPool bufferPool) {
124:         if (bufferPool.addBufferListener(this)) {
125:             isWaitingForFloatingBuffers = true;
126:             numberOfRequiredMemorySegments = 1;
127:             return false;
128:         } else if (bufferPool.isDestroyed()) {
129:             throw new CancelTaskException("Local buffer pool has already been released.");
130:         } else {
