135:     /** Requests exclusive buffers from the provider. */
136:     void requestExclusiveBuffers(int numExclusiveBuffers) throws IOException {
137:         checkArgument(numExclusiveBuffers >= 0, "Num exclusive buffers must be non-negative.");
138:         if (numExclusiveBuffers == 0) {
139:             return;
140:         }
141: 
142:         Collection<MemorySegment> segments =
143:                 globalPool.requestUnpooledMemorySegments(numExclusiveBuffers);
144:         synchronized (bufferQueue) {
145:             // AvailableBufferQueue::addExclusiveBuffer may release the previously allocated
146:             // floating buffer, which requires the caller to recycle these released floating
147:             // buffers. There should be no floating buffers that have been allocated before the
148:             // exclusive buffers are initialized, so here only a simple assertion is required
149:             checkState(
