154:                         new NetworkBuffer(segment, this), numberOfRequiredMemorySegments);
155:             }
156:         }
157:     }
158: 
159:     /**
160:      * Requests floating buffers from the buffer pool based on the given required amount, and
161:      * returns the actual requested amount. If the required amount is not fully satisfied, it will
162:      * register as a listener.
163:      */
