165:         int numRequestedBuffers = 0;
166:         synchronized (bufferQueue) {
167:             // Similar to notifyBufferAvailable(), make sure that we never add a buffer after
168:             // channel
169:             // released all buffers via releaseAllResources().
170:             if (inputChannel.isReleased()) {
171:                 return numRequestedBuffers;
172:             }
