256:     /** Recycles all the exclusive and floating buffers from the given buffer queue. */
257:     void releaseAllBuffers(ArrayDeque<Buffer> buffers) throws IOException {
258:         // Gather all exclusive buffers and recycle them to global pool in batch, because
259:         // we do not want to trigger redistribution of buffers after each recycle.
260:         final List<MemorySegment> exclusiveRecyclingSegments = new ArrayList<>();
