273:             }
274:         }
275:         try {
276:             synchronized (bufferQueue) {
277:                 bufferQueue.releaseAll(exclusiveRecyclingSegments);
278:                 bufferQueue.notifyAll();
279:             }
280:         } catch (Exception e) {
