41: /**
42:  * Implementation of a resettable iterator. While iterating the first time over the data, the
43:  * iterator writes the records to a spillable buffer. Any subsequent iteration re-reads the data
44:  * from that buffer.
45:  *
46:  * @param <T> The type of record that the iterator handles.
47:  */
48: public class SpillingResettableIterator<T> implements ResettableIterator<T> {
49: 
50:     private static final Logger LOG = LoggerFactory.getLogger(SpillingResettableIterator.class);
51: 
52:     // ------------------------------------------------------------------------
53: 
54:     private T next;
55: 
56:     private T instance;
57: 
58:     protected DataInputView inView;
59: 
60:     protected final TypeSerializer<T> serializer;
61: 
62:     private long elementCount;
63: 
64:     private long currentElementNum;
65: 
66:     protected final SpillingBuffer buffer;
67: 
68:     protected final Iterator<T> input;
69: 
70:     protected final MemoryManager memoryManager;
71: 
72:     private final List<MemorySegment> memorySegments;
73: 
74:     private final boolean releaseMemoryOnClose;
75: 
76:     // ------------------------------------------------------------------------
77: 
78:     public SpillingResettableIterator(
79:             Iterator<T> input,
80:             TypeSerializer<T> serializer,
81:             MemoryManager memoryManager,
82:             IOManager ioManager,
83:             int numPages,
84:             AbstractInvokable parentTask)
85:             throws MemoryAllocationException {
86:         this(
87:                 input,
88:                 serializer,
89:                 memoryManager,
90:                 ioManager,
91:                 memoryManager.allocatePages(parentTask, numPages),
92:                 true);
93:     }
94: 
95:     public SpillingResettableIterator(
96:             Iterator<T> input,
97:             TypeSerializer<T> serializer,
98:             MemoryManager memoryManager,
99:             IOManager ioManager,
100:             List<MemorySegment> memory) {
101:         this(input, serializer, memoryManager, ioManager, memory, false);
102:     }
103: 
104:     private SpillingResettableIterator(
105:             Iterator<T> input,
106:             TypeSerializer<T> serializer,
107:             MemoryManager memoryManager,
108:             IOManager ioManager,
109:             List<MemorySegment> memory,
110:             boolean releaseMemOnClose) {
111:         this.memoryManager = memoryManager;
112:         this.input = input;
113:         this.instance = serializer.createInstance();
114:         this.serializer = serializer;
115:         this.memorySegments = memory;
116:         this.releaseMemoryOnClose = releaseMemOnClose;
117: 
118:         if (LOG.isDebugEnabled()) {
119:             LOG.debug(
120:                     "Creating spilling resettable iterator with "
121:                             + memory.size()
122:                             + " pages of memory.");
123:         }
124: 
125:         this.buffer =
126:                 new SpillingBuffer(
127:                         ioManager,
128:                         new ListMemorySegmentSource(memory),
129:                         memoryManager.getPageSize());
130:     }
131: 
132:     public void open() {
133:         if (LOG.isDebugEnabled()) {
134:             LOG.debug("Spilling Resettable Iterator opened.");
135:         }
136:     }
137: 
138:     public void reset() throws IOException {
139:         this.inView = this.buffer.flip();
140:         this.currentElementNum = 0;
141:     }
142: 
143:     @Override
144:     public boolean hasNext() {
145:         if (this.next == null) {
146:             if (this.inView != null) {
147:                 if (this.currentElementNum < this.elementCount) {
148:                     try {
149:                         this.instance = this.serializer.deserialize(this.instance, this.inView);
150:                     } catch (IOException e) {
151:                         throw new RuntimeException(
152:                                 "SpillingIterator: Error reading element from buffer.", e);
153:                     }
154:                     this.next = this.instance;
155:                     this.currentElementNum++;
156:                     return true;
157:                 } else {
158:                     return false;
159:                 }
160:             } else {
161:                 // writing pass (first)
162:                 if (this.input.hasNext()) {
163:                     this.next = this.input.next();
164:                     try {
165:                         this.serializer.serialize(this.next, this.buffer);
166:                     } catch (IOException e) {
167:                         throw new RuntimeException(
168:                                 "SpillingIterator: Error writing element to buffer.", e);
169:                     }
170:                     this.elementCount++;
171:                     return true;
172:                 } else {
173:                     return false;
174:                 }
175:             }
176:         } else {
177:             return true;
178:         }
179:     }
180: 
181:     @Override
182:     public T next() {
183:         if (this.next != null || hasNext()) {
184:             final T out = this.next;
185:             this.next = null;
186:             return out;
187:         } else {
188:             throw new NoSuchElementException();
189:         }
190:     }
191: 
192:     @Override
193:     public void remove() {
194:         throw new UnsupportedOperationException();
195:     }
196: 
197:     public List<MemorySegment> close() throws IOException {
198:         if (LOG.isDebugEnabled()) {
199:             LOG.debug(
200:                     "Spilling Resettable Iterator closing. Stored "
201:                             + this.elementCount
202:                             + " records.");
203:         }
204: 
205:         this.inView = null;
206: 
207:         final List<MemorySegment> memory = this.buffer.close();
208:         memory.addAll(this.memorySegments);
209:         this.memorySegments.clear();
210: 
211:         if (this.releaseMemoryOnClose) {
212:             this.memoryManager.release(memory);
213:             return Collections.emptyList();
214:         } else {
215:             return memory;
216:         }
217:     }
218: }
