462:             final int overflowSegNum = (int) (newForwardPointer >>> 32);
463:             bucket = overflowSegments[overflowSegNum];
464:             bucketInSegmentOffset = (int) newForwardPointer;
465:             countInSegment = bucket.getInt(bucketInSegmentOffset + HEADER_COUNT_OFFSET);
466:             posInSegment = bucketInSegmentOffset + BUCKET_HEADER_LENGTH;
467:             numInSegment = 0;
468:         }
469:     }
470: 
471:     private long insertRecordIntoPartition(
472:             T record, InMemoryPartition<T> partition, boolean fragments) throws IOException {
473:         try {
474:             long pointer = partition.appendRecord(record);
475:             if (fragments) {
476:                 partition.setIsCompacted(false);
477:             }
478:             if ((pointer >> this.pageSizeInBits) > this.compactionMemory.getBlockCount()) {
479:                 this.compactionMemory.allocateSegments((int) (pointer >> this.pageSizeInBits));
480:             }
481:             return pointer;
482:         } catch (Exception e) {
483:             if (e instanceof EOFException || e instanceof IndexOutOfBoundsException) {
484:                 // this indicates an out of memory situation
485:                 try {
486:                     final int partitionNumber = partition.getPartitionNumber();
487:                     compactPartition(partitionNumber);
488: 
489:                     // retry append
490:                     partition =
491:                             this.partitions.get(
492:                                     partitionNumber); // compaction invalidates reference
493:                     long newPointer = partition.appendRecord(record);
494:                     if ((newPointer >> this.pageSizeInBits)
495:                             > this.compactionMemory.getBlockCount()) {
496:                         this.compactionMemory.allocateSegments(
497:                                 (int) (newPointer >> this.pageSizeInBits));
498:                     }
499:                     return newPointer;
500:                 } catch (EOFException | IndexOutOfBoundsException ex) {
501:                     throw new RuntimeException(
502:                             "Memory ran out. Compaction failed. "
503:                                     + getMemoryConsumptionString()
504:                                     + " Message: "
505:                                     + ex.getMessage());
506:                 }
507:             } else if (e instanceof IOException) {
508:                 throw (IOException) e;
509:             } else //noinspection ConstantConditions
510:             if (e instanceof RuntimeException) {
511:                 throw (RuntimeException) e;
512:             } else {
513:                 throw new RuntimeException("Writing record to compacting hash table failed", e);
514:             }
515:         }
516:     }
517: 
518:     /**
519:      * IMPORTANT!!! We pass only the partition number, because we must make sure we get a fresh
520:      * partition reference. The partition reference used during search for the key may have become
521:      * invalid during the compaction.
522:      */
523:     private void insertBucketEntryFromStart(
524:             MemorySegment bucket,
525:             int bucketInSegmentPos,
526:             int hashCode,
527:             long pointer,
528:             int partitionNumber)
529:             throws IOException {
530:         boolean checkForResize = false;
531:         // find the position to put the hash code and pointer
532:         final int count = bucket.getInt(bucketInSegmentPos + HEADER_COUNT_OFFSET);
533:         if (count < NUM_ENTRIES_PER_BUCKET) {
534:             // we are good in our current bucket, put the values
535:             bucket.putInt(
536:                     bucketInSegmentPos + BUCKET_HEADER_LENGTH + (count * HASH_CODE_LEN),
537:                     hashCode); // hash code
538:             bucket.putLong(
539:                     bucketInSegmentPos + BUCKET_POINTER_START_OFFSET + (count * POINTER_LEN),
540:                     pointer); // pointer
541:             bucket.putInt(bucketInSegmentPos + HEADER_COUNT_OFFSET, count + 1); // update count
542:         } else {
543:             // we need to go to the overflow buckets
544:             final InMemoryPartition<T> p = this.partitions.get(partitionNumber);
545: 
546:             final long originalForwardPointer =
547:                     bucket.getLong(bucketInSegmentPos + HEADER_FORWARD_OFFSET);
548:             final long forwardForNewBucket;
549: 
550:             if (originalForwardPointer != BUCKET_FORWARD_POINTER_NOT_SET) {
551: 
552:                 // forward pointer set
553:                 final int overflowSegNum = (int) (originalForwardPointer >>> 32);
554:                 final int segOffset = (int) originalForwardPointer;
555:                 final MemorySegment seg = p.overflowSegments[overflowSegNum];
556: 
557:                 final int obCount = seg.getInt(segOffset + HEADER_COUNT_OFFSET);
558: 
559:                 // check if there is space in this overflow bucket
560:                 if (obCount < NUM_ENTRIES_PER_BUCKET) {
561:                     // space in this bucket and we are done
562:                     seg.putInt(
563:                             segOffset + BUCKET_HEADER_LENGTH + (obCount * HASH_CODE_LEN),
564:                             hashCode); // hash code
565:                     seg.putLong(
566:                             segOffset + BUCKET_POINTER_START_OFFSET + (obCount * POINTER_LEN),
567:                             pointer); // pointer
568:                     seg.putInt(segOffset + HEADER_COUNT_OFFSET, obCount + 1); // update count
569:                     return;
570:                 } else {
571:                     // no space here, we need a new bucket. this current overflow bucket will be the
572:                     // target of the new overflow bucket
573:                     forwardForNewBucket = originalForwardPointer;
574:                 }
575:             } else {
576:                 // no overflow bucket yet, so we need a first one
577:                 forwardForNewBucket = BUCKET_FORWARD_POINTER_NOT_SET;
578:             }
579: 
580:             // we need a new overflow bucket
581:             MemorySegment overflowSeg;
582:             final int overflowBucketNum;
583:             final int overflowBucketOffset;
584: 
585:             // first, see if there is space for an overflow bucket remaining in the last overflow
586:             // segment
587:             if (p.nextOverflowBucket == 0) {
588:                 // no space left in last bucket, or no bucket yet, so create an overflow segment
589:                 overflowSeg = getNextBuffer();
590:                 overflowBucketOffset = 0;
591:                 overflowBucketNum = p.numOverflowSegments;
592: 
593:                 // add the new overflow segment
594:                 if (p.overflowSegments.length <= p.numOverflowSegments) {
595:                     MemorySegment[] newSegsArray = new MemorySegment[p.overflowSegments.length * 2];
596:                     System.arraycopy(
597:                             p.overflowSegments, 0, newSegsArray, 0, p.overflowSegments.length);
598:                     p.overflowSegments = newSegsArray;
599:                 }
600:                 p.overflowSegments[p.numOverflowSegments] = overflowSeg;
601:                 p.numOverflowSegments++;
602:                 checkForResize = true;
603:             } else {
604:                 // there is space in the last overflow bucket
605:                 overflowBucketNum = p.numOverflowSegments - 1;
606:                 overflowSeg = p.overflowSegments[overflowBucketNum];
607:                 overflowBucketOffset = p.nextOverflowBucket << NUM_INTRA_BUCKET_BITS;
608:             }
609: 
610:             // next overflow bucket is one ahead. if the segment is full, the next will be at the
611:             // beginning
612:             // of a new segment
613:             p.nextOverflowBucket =
614:                     (p.nextOverflowBucket == this.bucketsPerSegmentMask
615:                             ? 0
616:                             : p.nextOverflowBucket + 1);
617: 
618:             // insert the new overflow bucket in the chain of buckets
619:             // 1) set the old forward pointer
620:             // 2) let the bucket in the main table point to this one
621:             overflowSeg.putLong(overflowBucketOffset + HEADER_FORWARD_OFFSET, forwardForNewBucket);
622:             final long pointerToNewBucket =
623:                     (((long) overflowBucketNum) << 32) | ((long) overflowBucketOffset);
624:             bucket.putLong(bucketInSegmentPos + HEADER_FORWARD_OFFSET, pointerToNewBucket);
625: 
626:             // finally, insert the values into the overflow buckets
627:             overflowSeg.putInt(overflowBucketOffset + BUCKET_HEADER_LENGTH, hashCode); // hash code
628:             overflowSeg.putLong(
629:                     overflowBucketOffset + BUCKET_POINTER_START_OFFSET, pointer); // pointer
630: 
631:             // set the count to one
632:             overflowSeg.putInt(overflowBucketOffset + HEADER_COUNT_OFFSET, 1);
633: 
634:             if (checkForResize && !this.isResizing) {
635:                 // check if we should resize buckets
636:                 if (this.buckets.length <= getOverflowSegmentCount()) {
637:                     resizeHashTable();
638:                 }
639:             }
640:         }
641:     }
