665:     private void createPartitions(int numPartitions) {
666:         this.partitions.clear();
667: 
668:         ListMemorySegmentSource memSource = new ListMemorySegmentSource(this.availableMemory);
669: 
670:         for (int i = 0; i < numPartitions; i++) {
671:             this.partitions.add(
672:                     new InMemoryPartition<T>(
673:                             this.buildSideSerializer,
674:                             i,
675:                             memSource,
676:                             this.segmentSize,
677:                             pageSizeInBits));
678:         }
679:         this.compactionMemory =
680:                 new InMemoryPartition<T>(
681:                         this.buildSideSerializer, -1, memSource, this.segmentSize, pageSizeInBits);
682:     }
683: 
684:     private void clearPartitions() {
685:         for (InMemoryPartition<T> p : this.partitions) {
686:             p.clearAllMemory(this.availableMemory);
687:         }
688:         this.partitions.clear();
689:         this.compactionMemory.clearAllMemory(availableMemory);
690:     }
691: 
692:     private void initTable(int numBuckets, byte numPartitions) {
693:         final int bucketsPerSegment = this.bucketsPerSegmentMask + 1;
694:         final int numSegs =
695:                 (numBuckets >>> this.bucketsPerSegmentBits)
696:                         + ((numBuckets & this.bucketsPerSegmentMask) == 0 ? 0 : 1);
697:         final MemorySegment[] table = new MemorySegment[numSegs];
698: 
699:         // go over all segments that are part of the table
700:         for (int i = 0, bucket = 0; i < numSegs && bucket < numBuckets; i++) {
701:             final MemorySegment seg = getNextBuffer();
702: 
703:             // go over all buckets in the segment
704:             for (int k = 0; k < bucketsPerSegment && bucket < numBuckets; k++, bucket++) {
705:                 final int bucketOffset = k * HASH_BUCKET_SIZE;
706: 
707:                 // compute the partition that the bucket corresponds to
708:                 final byte partition = assignPartition(bucket, numPartitions);
709: 
710:                 // initialize the header fields
711:                 seg.put(bucketOffset + HEADER_PARTITION_OFFSET, partition);
712:                 seg.putInt(bucketOffset + HEADER_COUNT_OFFSET, 0);
713:                 seg.putLong(bucketOffset + HEADER_FORWARD_OFFSET, BUCKET_FORWARD_POINTER_NOT_SET);
714:             }
715: 
716:             table[i] = seg;
717:         }
718:         this.buckets = table;
719:         this.numBuckets = numBuckets;
720:     }
721: 
722:     private void releaseTable() {
723:         // set the counters back
724:         this.numBuckets = 0;
725:         if (this.buckets != null) {
726:             for (MemorySegment bucket : this.buckets) {
727:                 this.availableMemory.add(bucket);
728:             }
729:             this.buckets = null;
730:         }
731:     }
732: 
733:     private MemorySegment getNextBuffer() {
734:         // check if the list directly offers memory
735:         int s = this.availableMemory.size();
736:         if (s > 0) {
737:             return this.availableMemory.remove(s - 1);
738:         } else {
739:             throw new RuntimeException("Memory ran out. " + getMemoryConsumptionString());
740:         }
741:     }
