743:     // --------------------------------------------------------------------------------------------
744:     //                             Utility Computational Functions
745:     // --------------------------------------------------------------------------------------------
746: 
747:     /**
748:      * Gets the number of partitions to be used for an initial hash-table, when no estimates are
749:      * available.
750:      *
751:      * <p>The current logic makes sure that there are always between 10 and 32 partitions, and close
752:      * to 0.1 of the number of buffers.
753:      *
754:      * @param numBuffers The number of buffers available.
755:      * @return The number of partitions to use.
756:      */
757:     private static int getPartitioningFanOutNoEstimates(int numBuffers) {
758:         return Math.max(10, Math.min(numBuffers / 10, MAX_NUM_PARTITIONS));
759:     }
760: 
761:     /** @return String containing a summary of the memory consumption for error messages */
762:     private String getMemoryConsumptionString() {
763:         return "numPartitions: "
764:                 + this.partitions.size()
765:                 + " minPartition: "
766:                 + getMinPartition()
767:                 + " maxPartition: "
768:                 + getMaxPartition()
769:                 + " number of overflow segments: "
770:                 + getOverflowSegmentCount()
771:                 + " bucketSize: "
772:                 + this.buckets.length
773:                 + " Overall memory: "
774:                 + getSize()
775:                 + " Partition memory: "
776:                 + getPartitionSize();
777:     }
778: 
779:     /**
780:      * Size of all memory segments owned by this hash table
781:      *
782:      * @return size in bytes
783:      */
784:     private long getSize() {
785:         long numSegments = 0;
786:         numSegments += this.availableMemory.size();
787:         numSegments += this.buckets.length;
788:         for (InMemoryPartition<T> p : this.partitions) {
789:             numSegments += p.getBlockCount();
790:             numSegments += p.numOverflowSegments;
791:         }
792:         numSegments += this.compactionMemory.getBlockCount();
793:         return numSegments * this.segmentSize;
794:     }
795: 
796:     /**
797:      * Size of all memory segments owned by the partitions of this hash table excluding the
798:      * compaction partition
799:      *
800:      * @return size in bytes
801:      */
802:     private long getPartitionSize() {
803:         long numSegments = 0;
804:         for (InMemoryPartition<T> p : this.partitions) {
805:             numSegments += p.getBlockCount();
806:         }
807:         return numSegments * this.segmentSize;
808:     }
809: 
810:     /** @return number of memory segments in the largest partition */
811:     private int getMaxPartition() {
812:         int maxPartition = 0;
813:         for (InMemoryPartition<T> p1 : this.partitions) {
814:             if (p1.getBlockCount() > maxPartition) {
815:                 maxPartition = p1.getBlockCount();
816:             }
817:         }
818:         return maxPartition;
819:     }
820: 
821:     /** @return number of memory segments in the smallest partition */
822:     private int getMinPartition() {
823:         int minPartition = Integer.MAX_VALUE;
824:         for (InMemoryPartition<T> p1 : this.partitions) {
825:             if (p1.getBlockCount() < minPartition) {
826:                 minPartition = p1.getBlockCount();
827:             }
828:         }
829:         return minPartition;
830:     }
831: 
832:     /** @return number of memory segments used in overflow buckets */
833:     private int getOverflowSegmentCount() {
834:         int result = 0;
835:         for (InMemoryPartition<T> p : this.partitions) {
836:             result += p.numOverflowSegments;
837:         }
838:         return result;
839:     }
840: 
841:     /**
842:      * tries to find a good value for the number of buckets will ensure that the number of buckets
843:      * is a multiple of numPartitions
844:      *
845:      * @return number of buckets
846:      */
847:     private static int getInitialTableSize(
848:             int numBuffers, int bufferSize, int numPartitions, int recordLenBytes) {
849:         final long totalSize = ((long) bufferSize) * numBuffers;
850:         final long numRecordsStorable = totalSize / (recordLenBytes + RECORD_OVERHEAD_BYTES);
851:         final long bucketBytes = numRecordsStorable * RECORD_OVERHEAD_BYTES;
852:         long numBuckets = bucketBytes / (2 * HASH_BUCKET_SIZE) + 1;
853:         numBuckets += numPartitions - numBuckets % numPartitions;
854:         return numBuckets > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) numBuckets;
855:     }
856: 
857:     /**
858:      * Assigns a partition to a bucket.
859:      *
860:      * @param bucket bucket index
861:      * @param numPartitions number of partitions
862:      * @return The hash code for the integer.
863:      */
864:     private static byte assignPartition(int bucket, byte numPartitions) {
865:         return (byte) (bucket % numPartitions);
866:     }
867: 
868:     /**
869:      * Attempts to double the number of buckets
870:      *
871:      * @return true on success
872:      * @throws IOException
873:      */
874:     @VisibleForTesting
875:     boolean resizeHashTable() throws IOException {
876:         final int newNumBuckets = 2 * this.numBuckets;
877:         final int bucketsPerSegment = this.bucketsPerSegmentMask + 1;
878:         final int newNumSegments = (newNumBuckets + (bucketsPerSegment - 1)) / bucketsPerSegment;
879:         final int additionalSegments = newNumSegments - this.buckets.length;
880:         final int numPartitions = this.partitions.size();
881: 
882:         if (this.availableMemory.size() < additionalSegments) {
883:             for (int i = 0; i < numPartitions; i++) {
884:                 compactPartition(i);
885:                 if (this.availableMemory.size() >= additionalSegments) {
886:                     break;
887:                 }
888:             }
889:         }
890: 
891:         if (this.availableMemory.size() < additionalSegments || this.closed) {
892:             return false;
893:         } else {
894:             this.isResizing = true;
895:             // allocate new buckets
896:             final int startOffset = (this.numBuckets * HASH_BUCKET_SIZE) % this.segmentSize;
897:             final int oldNumBuckets = this.numBuckets;
898:             final int oldNumSegments = this.buckets.length;
899:             MemorySegment[] mergedBuckets = new MemorySegment[newNumSegments];
900:             System.arraycopy(this.buckets, 0, mergedBuckets, 0, this.buckets.length);
901:             this.buckets = mergedBuckets;
902:             this.numBuckets = newNumBuckets;
903:             // initialize all new buckets
904:             boolean oldSegment = (startOffset != 0);
905:             final int startSegment = oldSegment ? (oldNumSegments - 1) : oldNumSegments;
906:             for (int i = startSegment, bucket = oldNumBuckets;
907:                     i < newNumSegments && bucket < this.numBuckets;
908:                     i++) {
909:                 MemorySegment seg;
910:                 int bucketOffset;
911:                 if (oldSegment) { // the first couple of new buckets may be located on an old
912:                     // segment
913:                     seg = this.buckets[i];
914:                     for (int k = (oldNumBuckets % bucketsPerSegment);
915:                             k < bucketsPerSegment && bucket < this.numBuckets;
916:                             k++, bucket++) {
917:                         bucketOffset = k * HASH_BUCKET_SIZE;
918:                         // initialize the header fields
919:                         seg.put(
920:                                 bucketOffset + HEADER_PARTITION_OFFSET,
921:                                 assignPartition(bucket, (byte) numPartitions));
922:                         seg.putInt(bucketOffset + HEADER_COUNT_OFFSET, 0);
923:                         seg.putLong(
924:                                 bucketOffset + HEADER_FORWARD_OFFSET,
925:                                 BUCKET_FORWARD_POINTER_NOT_SET);
926:                     }
927:                 } else {
928:                     seg = getNextBuffer();
929:                     // go over all buckets in the segment
930:                     for (int k = 0;
931:                             k < bucketsPerSegment && bucket < this.numBuckets;
932:                             k++, bucket++) {
933:                         bucketOffset = k * HASH_BUCKET_SIZE;
934:                         // initialize the header fields
935:                         seg.put(
936:                                 bucketOffset + HEADER_PARTITION_OFFSET,
937:                                 assignPartition(bucket, (byte) numPartitions));
938:                         seg.putInt(bucketOffset + HEADER_COUNT_OFFSET, 0);
939:                         seg.putLong(
940:                                 bucketOffset + HEADER_FORWARD_OFFSET,
941:                                 BUCKET_FORWARD_POINTER_NOT_SET);
942:                     }
943:                 }
944:                 this.buckets[i] = seg;
945:                 oldSegment = false; // we write on at most one old segment
946:             }
947:             int hashOffset;
948:             int hash;
949:             int pointerOffset;
950:             long pointer;
951:             IntArrayList hashList = new IntArrayList(NUM_ENTRIES_PER_BUCKET);
952:             LongArrayList pointerList = new LongArrayList(NUM_ENTRIES_PER_BUCKET);
953:             IntArrayList overflowHashes = new IntArrayList(64);
954:             LongArrayList overflowPointers = new LongArrayList(64);
955: 
956:             // go over all buckets and split them between old and new buckets
957:             for (int i = 0; i < numPartitions; i++) {
958:                 InMemoryPartition<T> partition = this.partitions.get(i);
959:                 final MemorySegment[] overflowSegments = partition.overflowSegments;
960: 
961:                 int posHashCode;
962:                 for (int j = 0, bucket = i;
963:                         j < this.buckets.length && bucket < oldNumBuckets;
964:                         j++) {
965:                     MemorySegment segment = this.buckets[j];
966:                     // go over all buckets in the segment belonging to the partition
967:                     for (int k = bucket % bucketsPerSegment;
968:                             k < bucketsPerSegment && bucket < oldNumBuckets;
969:                             k += numPartitions, bucket += numPartitions) {
970:                         int bucketOffset = k * HASH_BUCKET_SIZE;
971:                         if ((int) segment.get(bucketOffset + HEADER_PARTITION_OFFSET) != i) {
972:                             throw new IOException(
973:                                     "Accessed wrong bucket! wanted: "
974:                                             + i
975:                                             + " got: "
976:                                             + segment.get(bucketOffset + HEADER_PARTITION_OFFSET));
977:                         }
978:                         // loop over all segments that are involved in the bucket (original bucket
979:                         // plus overflow buckets)
980:                         int countInSegment = segment.getInt(bucketOffset + HEADER_COUNT_OFFSET);
981:                         int numInSegment = 0;
982:                         pointerOffset = bucketOffset + BUCKET_POINTER_START_OFFSET;
983:                         hashOffset = bucketOffset + BUCKET_HEADER_LENGTH;
984:                         while (true) {
985:                             while (numInSegment < countInSegment) {
986:                                 hash = segment.getInt(hashOffset);
987:                                 if ((hash % this.numBuckets) != bucket
988:                                         && (hash % this.numBuckets) != (bucket + oldNumBuckets)) {
989:                                     throw new IOException(
990:                                             "wanted: "
991:                                                     + bucket
992:                                                     + " or "
993:                                                     + (bucket + oldNumBuckets)
994:                                                     + " got: "
995:                                                     + hash % this.numBuckets);
996:                                 }
997:                                 pointer = segment.getLong(pointerOffset);
998:                                 hashList.add(hash);
999:                                 pointerList.add(pointer);
1000:                                 pointerOffset += POINTER_LEN;
1001:                                 hashOffset += HASH_CODE_LEN;
1002:                                 numInSegment++;
1003:                             }
1004:                             // this segment is done. check if there is another chained bucket
1005:                             final long forwardPointer =
1006:                                     segment.getLong(bucketOffset + HEADER_FORWARD_OFFSET);
1007:                             if (forwardPointer == BUCKET_FORWARD_POINTER_NOT_SET) {
1008:                                 break;
1009:                             }
1010:                             final int overflowSegNum = (int) (forwardPointer >>> 32);
1011:                             segment = overflowSegments[overflowSegNum];
1012:                             bucketOffset = (int) forwardPointer;
1013:                             countInSegment = segment.getInt(bucketOffset + HEADER_COUNT_OFFSET);
1014:                             pointerOffset = bucketOffset + BUCKET_POINTER_START_OFFSET;
1015:                             hashOffset = bucketOffset + BUCKET_HEADER_LENGTH;
1016:                             numInSegment = 0;
1017:                         }
1018:                         segment = this.buckets[j];
1019:                         bucketOffset = k * HASH_BUCKET_SIZE;
1020:                         // reset bucket for re-insertion
1021:                         segment.putInt(bucketOffset + HEADER_COUNT_OFFSET, 0);
1022:                         segment.putLong(
1023:                                 bucketOffset + HEADER_FORWARD_OFFSET,
1024:                                 BUCKET_FORWARD_POINTER_NOT_SET);
1025:                         // refill table
1026:                         if (hashList.size() != pointerList.size()) {
1027:                             throw new IOException(
1028:                                     "Pointer and hash counts do not match. hashes: "
1029:                                             + hashList.size()
1030:                                             + " pointer: "
1031:                                             + pointerList.size());
1032:                         }
1033:                         int newSegmentIndex = (bucket + oldNumBuckets) / bucketsPerSegment;
1034:                         MemorySegment newSegment = this.buckets[newSegmentIndex];
1035: 
1036:                         // we need to avoid overflows in the first run
1037:                         int oldBucketCount = 0;
1038:                         int newBucketCount = 0;
1039:                         while (!hashList.isEmpty()) {
1040:                             hash = hashList.removeLast();
1041:                             pointer = pointerList.removeLong(pointerList.size() - 1);
1042:                             posHashCode = hash % this.numBuckets;
1043:                             if (posHashCode == bucket && oldBucketCount < NUM_ENTRIES_PER_BUCKET) {
1044:                                 bucketOffset = (bucket % bucketsPerSegment) * HASH_BUCKET_SIZE;
1045:                                 insertBucketEntryFromStart(
1046:                                         segment,
1047:                                         bucketOffset,
1048:                                         hash,
1049:                                         pointer,
1050:                                         partition.getPartitionNumber());
1051:                                 oldBucketCount++;
1052:                             } else if (posHashCode == (bucket + oldNumBuckets)
1053:                                     && newBucketCount < NUM_ENTRIES_PER_BUCKET) {
1054:                                 bucketOffset =
1055:                                         ((bucket + oldNumBuckets) % bucketsPerSegment)
1056:                                                 * HASH_BUCKET_SIZE;
1057:                                 insertBucketEntryFromStart(
1058:                                         newSegment,
