140:      */
141:     private final int segmentSize;
142: 
143:     /**
144:      * The number of hash table buckets in a single memory segment - 1. Because memory segments can
145:      * be comparatively large, we fit multiple buckets into one memory segment. This variable is a
146:      * mask that is 1 in the lower bits that define the number of a bucket in a segment.
147:      */
148:     private final int bucketsPerSegmentMask;
149: 
150:     /**
151:      * The number of bits that describe the position of a bucket in a memory segment. Computed as
152:      * log2(bucketsPerSegment).
153:      */
154:     private final int bucketsPerSegmentBits;
155: 
156:     /** An estimate for the average record length. */
157:     private final int avgRecordLen;
158: 
159:     private final int pageSizeInBits;
160: 
161:     // ------------------------------------------------------------------------
162: 
163:     /** The partitions of the hash table. */
164:     private final ArrayList<InMemoryPartition<T>> partitions;
165: 
166:     /**
167:      * The array of memory segments that contain the buckets which form the actual hash-table of
168:      * hash-codes and pointers to the elements.
169:      */
170:     private MemorySegment[] buckets;
171: 
172:     /**
173:      * Temporary storage for partition compaction (always attempts to allocate as many segments as
174:      * the largest partition)
175:      */
176:     private InMemoryPartition<T> compactionMemory;
177: 
178:     /**
179:      * The number of buckets in the current table. The bucket array is not necessarily fully used,
180:      * when not all buckets that would fit into the last segment are actually used.
181:      */
182:     private int numBuckets;
183: 
184:     /** Flag to interrupt closed loops */
185:     private boolean running = true;
186: 
187:     /**
188:      * Flag necessary so a resize is never triggered during a resize since the code paths are
189:      * interleaved
190:      */
191:     private boolean isResizing;
192: 
193:     // ------------------------------------------------------------------------
194:     //                         Construction and Teardown
195:     // ------------------------------------------------------------------------
196: 
197:     public CompactingHashTable(
198:             TypeSerializer<T> buildSideSerializer,
199:             TypeComparator<T> buildSideComparator,
200:             List<MemorySegment> memorySegments) {
201:         this(buildSideSerializer, buildSideComparator, memorySegments, DEFAULT_RECORD_LEN);
202:     }
203: 
204:     public CompactingHashTable(
205:             TypeSerializer<T> buildSideSerializer,
206:             TypeComparator<T> buildSideComparator,
207:             List<MemorySegment> memorySegments,
208:             int avgRecordLen) {
209: 
210:         super(buildSideSerializer, buildSideComparator);
211: 
212:         // some sanity checks first
213:         if (memorySegments == null) {
214:             throw new NullPointerException();
215:         }
216:         if (memorySegments.size() < NUMBER_OF_REQUIRED_MEMORY_SEGMENTS) {
217:             throw new IllegalArgumentException(
218:                     "Too few memory segments provided. Hash Table needs at least "
219:                             + NUMBER_OF_REQUIRED_MEMORY_SEGMENTS
220:                             + " memory segments.");
221:         }
222: 
223:         this.availableMemory =
224:                 (memorySegments instanceof ArrayList)
225:                         ? (ArrayList<MemorySegment>) memorySegments
226:                         : new ArrayList<MemorySegment>(memorySegments);
227: 
228:         this.avgRecordLen =
229:                 buildSideSerializer.getLength() > 0
230:                         ? buildSideSerializer.getLength()
231:                         : avgRecordLen;
232: 
233:         // check the size of the first buffer and record it. all further buffers must have the same
234:         // size.
235:         // the size must also be a power of 2
236:         this.segmentSize = memorySegments.get(0).size();
237:         if ((this.segmentSize & this.segmentSize - 1) != 0) {
238:             throw new IllegalArgumentException(
239:                     "Hash Table requires buffers whose size is a power of 2.");
240:         }
241: 
242:         this.pageSizeInBits = MathUtils.log2strict(this.segmentSize);
243: 
244:         int bucketsPerSegment = this.segmentSize >> NUM_INTRA_BUCKET_BITS;
245:         if (bucketsPerSegment == 0) {
246:             throw new IllegalArgumentException(
247:                     "Hash Table requires buffers of at least " + HASH_BUCKET_SIZE + " bytes.");
248:         }
249:         this.bucketsPerSegmentMask = bucketsPerSegment - 1;
250:         this.bucketsPerSegmentBits = MathUtils.log2strict(bucketsPerSegment);
251: 
252:         this.partitions = new ArrayList<InMemoryPartition<T>>();
253: 
254:         // so far no partition has any MemorySegments
255:     }
256: 
257:     // ------------------------------------------------------------------------
258:     //  life cycle
259:     // ------------------------------------------------------------------------
260: 
261:     /** Initialize the hash table */
262:     @Override
263:     public void open() {
264:         synchronized (stateLock) {
265:             if (!closed) {
266:                 throw new IllegalStateException("currently not closed.");
267:             }
268:             closed = false;
269:         }
270: 
271:         // create the partitions
272:         final int partitionFanOut = getPartitioningFanOutNoEstimates(this.availableMemory.size());
273:         createPartitions(partitionFanOut);
274: 
275:         // set up the table structure. the write behind buffers are taken away, as are one buffer
276:         // per partition
277:         final int numBuckets =
278:                 getInitialTableSize(
279:                         this.availableMemory.size(),
280:                         this.segmentSize,
281:                         partitionFanOut,
282:                         this.avgRecordLen);
283: 
284:         initTable(numBuckets, (byte) partitionFanOut);
285:     }
286: 
287:     /**
288:      * Closes the hash table. This effectively releases all internal structures and closes all open
289:      * files and removes them. The call to this method is valid both as a cleanup after the complete
290:      * inputs were properly processed, and as an cancellation call, which cleans up all resources
291:      * that are currently held by the hash join. If another process still access the hash table
292:      * after close has been called no operations will be performed.
293:      */
294:     @Override
295:     public void close() {
296:         // make sure that we close only once
297:         synchronized (this.stateLock) {
298:             if (this.closed) {
299:                 return;
300:             }
301:             this.closed = true;
302:         }
303: 
304:         LOG.debug("Closing hash table and releasing resources.");
305: 
306:         // release the table structure
307:         releaseTable();
308: 
309:         // clear the memory in the partitions
310:         clearPartitions();
311:     }
312: 
313:     @Override
314:     public void abort() {
315:         this.running = false;
316:         LOG.debug("Cancelling hash table operations.");
317:     }
318: 
319:     @Override
320:     public List<MemorySegment> getFreeMemory() {
321:         if (!this.closed) {
322:             throw new IllegalStateException("Cannot return memory while join is open.");
323:         }
324: 
325:         return this.availableMemory;
326:     }
327: 
328:     // ------------------------------------------------------------------------
329:     //  adding data to the hash table
330:     // ------------------------------------------------------------------------
331: 
332:     public void buildTableWithUniqueKey(final MutableObjectIterator<T> input) throws IOException {
333:         // go over the complete input and insert every element into the hash table
334: 
335:         T value;
336:         while (this.running && (value = input.next()) != null) {
337:             insertOrReplaceRecord(value);
338:         }
339:     }
340: 
341:     @Override
342:     public final void insert(T record) throws IOException {
343:         if (this.closed) {
344:             return;
345:         }
346: 
347:         final int hashCode = MathUtils.jenkinsHash(this.buildSideComparator.hash(record));
348:         final int posHashCode = hashCode % this.numBuckets;
349: 
350:         // get the bucket for the given hash code
351:         final int bucketArrayPos = posHashCode >>> this.bucketsPerSegmentBits;
352:         final int bucketInSegmentPos =
353:                 (posHashCode & this.bucketsPerSegmentMask) << NUM_INTRA_BUCKET_BITS;
354:         final MemorySegment bucket = this.buckets[bucketArrayPos];
355: 
356:         // get the basic characteristics of the bucket
357:         final int partitionNumber = bucket.get(bucketInSegmentPos + HEADER_PARTITION_OFFSET);
358:         InMemoryPartition<T> partition = this.partitions.get(partitionNumber);
359: 
360:         long pointer = insertRecordIntoPartition(record, partition, false);
361:         insertBucketEntryFromStart(bucket, bucketInSegmentPos, hashCode, pointer, partitionNumber);
362:     }
363: 
364:     /**
365:      * Replaces record in hash table if record already present or append record if not. May trigger
366:      * expensive compaction.
367:      *
368:      * @param record record to insert or replace
369:      * @throws IOException
370:      */
371:     public void insertOrReplaceRecord(T record) throws IOException {
372:         if (this.closed) {
373:             return;
374:         }
375: 
376:         final int searchHashCode = MathUtils.jenkinsHash(this.buildSideComparator.hash(record));
377:         final int posHashCode = searchHashCode % this.numBuckets;
378: 
379:         // get the bucket for the given hash code
380:         final MemorySegment originalBucket =
381:                 this.buckets[posHashCode >> this.bucketsPerSegmentBits];
382:         final int originalBucketOffset =
383:                 (posHashCode & this.bucketsPerSegmentMask) << NUM_INTRA_BUCKET_BITS;
384: 
385:         MemorySegment bucket = originalBucket;
386:         int bucketInSegmentOffset = originalBucketOffset;
387: 
388:         // get the basic characteristics of the bucket
389:         final int partitionNumber = bucket.get(bucketInSegmentOffset + HEADER_PARTITION_OFFSET);
390:         final InMemoryPartition<T> partition = this.partitions.get(partitionNumber);
391:         final MemorySegment[] overflowSegments = partition.overflowSegments;
392: 
393:         this.buildSideComparator.setReference(record);
394: 
395:         int countInSegment = bucket.getInt(bucketInSegmentOffset + HEADER_COUNT_OFFSET);
396:         int numInSegment = 0;
397:         int posInSegment = bucketInSegmentOffset + BUCKET_HEADER_LENGTH;
398: 
399:         // loop over all segments that are involved in the bucket (original bucket plus overflow
400:         // buckets)
401:         while (true) {
402: 
403:             while (numInSegment < countInSegment) {
404: 
405:                 final int thisCode = bucket.getInt(posInSegment);
406:                 posInSegment += HASH_CODE_LEN;
407: 
408:                 // check if the hash code matches
409:                 if (thisCode == searchHashCode) {
410:                     // get the pointer to the pair
411:                     final int pointerOffset =
412:                             bucketInSegmentOffset
413:                                     + BUCKET_POINTER_START_OFFSET
414:                                     + (numInSegment * POINTER_LEN);
415:                     final long pointer = bucket.getLong(pointerOffset);
416: 
417:                     // deserialize the key to check whether it is really equal, or whether we had
418:                     // only a hash collision
419:                     T valueAtPosition = partition.readRecordAt(pointer);
420:                     if (this.buildSideComparator.equalToReference(valueAtPosition)) {
421:                         long newPointer = insertRecordIntoPartition(record, partition, true);
422:                         bucket.putLong(pointerOffset, newPointer);
423:                         return;
424:                     }
425:                 }
426:                 numInSegment++;
427:             }
428: 
429:             // this segment is done. check if there is another chained bucket
430:             long newForwardPointer = bucket.getLong(bucketInSegmentOffset + HEADER_FORWARD_OFFSET);
431:             if (newForwardPointer == BUCKET_FORWARD_POINTER_NOT_SET) {
432: 
433:                 // nothing found. append and insert
434:                 long pointer = insertRecordIntoPartition(record, partition, false);
435: 
436:                 if (countInSegment < NUM_ENTRIES_PER_BUCKET) {
437:                     // we are good in our current bucket, put the values
438:                     bucket.putInt(
439:                             bucketInSegmentOffset
440:                                     + BUCKET_HEADER_LENGTH
441:                                     + (countInSegment * HASH_CODE_LEN),
442:                             searchHashCode); // hash code
443:                     bucket.putLong(
444:                             bucketInSegmentOffset
445:                                     + BUCKET_POINTER_START_OFFSET
446:                                     + (countInSegment * POINTER_LEN),
447:                             pointer); // pointer
448:                     bucket.putInt(
449:                             bucketInSegmentOffset + HEADER_COUNT_OFFSET,
450:                             countInSegment + 1); // update count
451:                 } else {
452:                     insertBucketEntryFromStart(
453:                             originalBucket,
454:                             originalBucketOffset,
455:                             searchHashCode,
456:                             pointer,
457:                             partitionNumber);
458:                 }
459:                 return;
460:             }
461: 
462:             final int overflowSegNum = (int) (newForwardPointer >>> 32);
463:             bucket = overflowSegments[overflowSegNum];
464:             bucketInSegmentOffset = (int) newForwardPointer;
465:             countInSegment = bucket.getInt(bucketInSegmentOffset + HEADER_COUNT_OFFSET);
466:             posInSegment = bucketInSegmentOffset + BUCKET_HEADER_LENGTH;
467:             numInSegment = 0;
468:         }
469:     }
470: 
471:     private long insertRecordIntoPartition(
472:             T record, InMemoryPartition<T> partition, boolean fragments) throws IOException {
473:         try {
474:             long pointer = partition.appendRecord(record);
475:             if (fragments) {
476:                 partition.setIsCompacted(false);
477:             }
478:             if ((pointer >> this.pageSizeInBits) > this.compactionMemory.getBlockCount()) {
479:                 this.compactionMemory.allocateSegments((int) (pointer >> this.pageSizeInBits));
480:             }
481:             return pointer;
482:         } catch (Exception e) {
483:             if (e instanceof EOFException || e instanceof IndexOutOfBoundsException) {
484:                 // this indicates an out of memory situation
485:                 try {
486:                     final int partitionNumber = partition.getPartitionNumber();
487:                     compactPartition(partitionNumber);
488: 
489:                     // retry append
490:                     partition =
491:                             this.partitions.get(
492:                                     partitionNumber); // compaction invalidates reference
493:                     long newPointer = partition.appendRecord(record);
494:                     if ((newPointer >> this.pageSizeInBits)
495:                             > this.compactionMemory.getBlockCount()) {
496:                         this.compactionMemory.allocateSegments(
497:                                 (int) (newPointer >> this.pageSizeInBits));
498:                     }
499:                     return newPointer;
500:                 } catch (EOFException | IndexOutOfBoundsException ex) {
501:                     throw new RuntimeException(
502:                             "Memory ran out. Compaction failed. "
503:                                     + getMemoryConsumptionString()
504:                                     + " Message: "
505:                                     + ex.getMessage());
506:                 }
507:             } else if (e instanceof IOException) {
508:                 throw (IOException) e;
509:             } else //noinspection ConstantConditions
510:             if (e instanceof RuntimeException) {
511:                 throw (RuntimeException) e;
512:             } else {
513:                 throw new RuntimeException("Writing record to compacting hash table failed", e);
514:             }
515:         }
516:     }
517: 
518:     /**
519:      * IMPORTANT!!! We pass only the partition number, because we must make sure we get a fresh
520:      * partition reference. The partition reference used during search for the key may have become
521:      * invalid during the compaction.
522:      */
523:     private void insertBucketEntryFromStart(
524:             MemorySegment bucket,
525:             int bucketInSegmentPos,
526:             int hashCode,
527:             long pointer,
528:             int partitionNumber)
529:             throws IOException {
530:         boolean checkForResize = false;
531:         // find the position to put the hash code and pointer
532:         final int count = bucket.getInt(bucketInSegmentPos + HEADER_COUNT_OFFSET);
533:         if (count < NUM_ENTRIES_PER_BUCKET) {
534:             // we are good in our current bucket, put the values
535:             bucket.putInt(
536:                     bucketInSegmentPos + BUCKET_HEADER_LENGTH + (count * HASH_CODE_LEN),
537:                     hashCode); // hash code
538:             bucket.putLong(
539:                     bucketInSegmentPos + BUCKET_POINTER_START_OFFSET + (count * POINTER_LEN),
540:                     pointer); // pointer
541:             bucket.putInt(bucketInSegmentPos + HEADER_COUNT_OFFSET, count + 1); // update count
542:         } else {
543:             // we need to go to the overflow buckets
544:             final InMemoryPartition<T> p = this.partitions.get(partitionNumber);
545: 
546:             final long originalForwardPointer =
547:                     bucket.getLong(bucketInSegmentPos + HEADER_FORWARD_OFFSET);
548:             final long forwardForNewBucket;
549: 
550:             if (originalForwardPointer != BUCKET_FORWARD_POINTER_NOT_SET) {
551: 
552:                 // forward pointer set
553:                 final int overflowSegNum = (int) (originalForwardPointer >>> 32);
554:                 final int segOffset = (int) originalForwardPointer;
555:                 final MemorySegment seg = p.overflowSegments[overflowSegNum];
556: 
557:                 final int obCount = seg.getInt(segOffset + HEADER_COUNT_OFFSET);
558: 
559:                 // check if there is space in this overflow bucket
560:                 if (obCount < NUM_ENTRIES_PER_BUCKET) {
561:                     // space in this bucket and we are done
562:                     seg.putInt(
563:                             segOffset + BUCKET_HEADER_LENGTH + (obCount * HASH_CODE_LEN),
564:                             hashCode); // hash code
565:                     seg.putLong(
566:                             segOffset + BUCKET_POINTER_START_OFFSET + (obCount * POINTER_LEN),
567:                             pointer); // pointer
568:                     seg.putInt(segOffset + HEADER_COUNT_OFFSET, obCount + 1); // update count
569:                     return;
570:                 } else {
571:                     // no space here, we need a new bucket. this current overflow bucket will be the
572:                     // target of the new overflow bucket
573:                     forwardForNewBucket = originalForwardPointer;
574:                 }
575:             } else {
576:                 // no overflow bucket yet, so we need a first one
577:                 forwardForNewBucket = BUCKET_FORWARD_POINTER_NOT_SET;
578:             }
579: 
580:             // we need a new overflow bucket
581:             MemorySegment overflowSeg;
582:             final int overflowBucketNum;
583:             final int overflowBucketOffset;
584: 
585:             // first, see if there is space for an overflow bucket remaining in the last overflow
586:             // segment
587:             if (p.nextOverflowBucket == 0) {
588:                 // no space left in last bucket, or no bucket yet, so create an overflow segment
589:                 overflowSeg = getNextBuffer();
590:                 overflowBucketOffset = 0;
591:                 overflowBucketNum = p.numOverflowSegments;
592: 
593:                 // add the new overflow segment
594:                 if (p.overflowSegments.length <= p.numOverflowSegments) {
595:                     MemorySegment[] newSegsArray = new MemorySegment[p.overflowSegments.length * 2];
596:                     System.arraycopy(
597:                             p.overflowSegments, 0, newSegsArray, 0, p.overflowSegments.length);
598:                     p.overflowSegments = newSegsArray;
599:                 }
600:                 p.overflowSegments[p.numOverflowSegments] = overflowSeg;
601:                 p.numOverflowSegments++;
602:                 checkForResize = true;
603:             } else {
604:                 // there is space in the last overflow bucket
605:                 overflowBucketNum = p.numOverflowSegments - 1;
606:                 overflowSeg = p.overflowSegments[overflowBucketNum];
607:                 overflowBucketOffset = p.nextOverflowBucket << NUM_INTRA_BUCKET_BITS;
608:             }
609: 
610:             // next overflow bucket is one ahead. if the segment is full, the next will be at the
611:             // beginning
612:             // of a new segment
613:             p.nextOverflowBucket =
614:                     (p.nextOverflowBucket == this.bucketsPerSegmentMask
615:                             ? 0
616:                             : p.nextOverflowBucket + 1);
617: 
618:             // insert the new overflow bucket in the chain of buckets
619:             // 1) set the old forward pointer
620:             // 2) let the bucket in the main table point to this one
621:             overflowSeg.putLong(overflowBucketOffset + HEADER_FORWARD_OFFSET, forwardForNewBucket);
622:             final long pointerToNewBucket =
623:                     (((long) overflowBucketNum) << 32) | ((long) overflowBucketOffset);
624:             bucket.putLong(bucketInSegmentPos + HEADER_FORWARD_OFFSET, pointerToNewBucket);
625: 
626:             // finally, insert the values into the overflow buckets
627:             overflowSeg.putInt(overflowBucketOffset + BUCKET_HEADER_LENGTH, hashCode); // hash code
628:             overflowSeg.putLong(
629:                     overflowBucketOffset + BUCKET_POINTER_START_OFFSET, pointer); // pointer
630: 
631:             // set the count to one
632:             overflowSeg.putInt(overflowBucketOffset + HEADER_COUNT_OFFSET, 1);
633: 
634:             if (checkForResize && !this.isResizing) {
635:                 // check if we should resize buckets
636:                 if (this.buckets.length <= getOverflowSegmentCount()) {
637:                     resizeHashTable();
638:                 }
639:             }
640:         }
641:     }
