810:     /** @return number of memory segments in the largest partition */
811:     private int getMaxPartition() {
812:         int maxPartition = 0;
813:         for (InMemoryPartition<T> p1 : this.partitions) {
814:             if (p1.getBlockCount() > maxPartition) {
815:                 maxPartition = p1.getBlockCount();
816:             }
817:         }
818:         return maxPartition;
819:     }
