821:     /** @return number of memory segments in the smallest partition */
822:     private int getMinPartition() {
823:         int minPartition = Integer.MAX_VALUE;
824:         for (InMemoryPartition<T> p1 : this.partitions) {
825:             if (p1.getBlockCount() < minPartition) {
826:                 minPartition = p1.getBlockCount();
827:             }
828:         }
829:         return minPartition;
830:     }
