841:     /**
842:      * tries to find a good value for the number of buckets will ensure that the number of buckets
843:      * is a multiple of numPartitions
844:      *
845:      * @return number of buckets
846:      */
847:     private static int getInitialTableSize(
848:             int numBuffers, int bufferSize, int numPartitions, int recordLenBytes) {
849:         final long totalSize = ((long) bufferSize) * numBuffers;
850:         final long numRecordsStorable = totalSize / (recordLenBytes + RECORD_OVERHEAD_BYTES);
851:         final long bucketBytes = numRecordsStorable * RECORD_OVERHEAD_BYTES;
852:         long numBuckets = bucketBytes / (2 * HASH_BUCKET_SIZE) + 1;
853:         numBuckets += numPartitions - numBuckets % numPartitions;
854:         return numBuckets > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) numBuckets;
855:     }
