967:                     for (int k = bucket % bucketsPerSegment;
968:                             k < bucketsPerSegment && bucket < oldNumBuckets;
969:                             k += numPartitions, bucket += numPartitions) {
970:                         int bucketOffset = k * HASH_BUCKET_SIZE;
