997:                                 pointer = segment.getLong(pointerOffset);
998:                                 hashList.add(hash);
999:                                 pointerList.add(pointer);
1000:                                 pointerOffset += POINTER_LEN;
1001:                                 hashOffset += HASH_CODE_LEN;
