1009:                             }
1010:                             final int overflowSegNum = (int) (forwardPointer >>> 32);
1011:                             segment = overflowSegments[overflowSegNum];
1012:                             bucketOffset = (int) forwardPointer;
1013:                             countInSegment = segment.getInt(bucketOffset + HEADER_COUNT_OFFSET);
