1015:                             hashOffset = bucketOffset + BUCKET_HEADER_LENGTH;
1016:                             numInSegment = 0;
1017:                         }
1018:                         segment = this.buckets[j];
1019:                         bucketOffset = k * HASH_BUCKET_SIZE;
