1026:                         if (hashList.size() != pointerList.size()) {
1027:                             throw new IOException(
1028:                                     "Pointer and hash counts do not match. hashes: "
1029:                                             + hashList.size()
1030:                                             + " pointer: "
1031:                                             + pointerList.size());
1032:                         }
1033:                         int newSegmentIndex = (bucket + oldNumBuckets) / bucketsPerSegment;
1034:                         MemorySegment newSegment = this.buckets[newSegmentIndex];
1035: 
1036:                         // we need to avoid overflows in the first run
1037:                         int oldBucketCount = 0;
1038:                         int newBucketCount = 0;
1039:                         while (!hashList.isEmpty()) {
1040:                             hash = hashList.removeLast();
1041:                             pointer = pointerList.removeLong(pointerList.size() - 1);
1042:                             posHashCode = hash % this.numBuckets;
1043:                             if (posHashCode == bucket && oldBucketCount < NUM_ENTRIES_PER_BUCKET) {
1044:                                 bucketOffset = (bucket % bucketsPerSegment) * HASH_BUCKET_SIZE;
