1118:     /**
1119:      * Compacts (garbage collects) partition with copy-compact strategy using compaction partition
1120:      *
1121:      * @param partitionNumber partition to compact
1122:      * @throws IOException
1123:      */
1124:     private void compactPartition(final int partitionNumber) throws IOException {
1125:         // do nothing if table was closed, parameter is invalid or no garbage exists
1126:         if (this.closed
1127:                 || partitionNumber >= this.partitions.size()
1128:                 || this.partitions.get(partitionNumber).isCompacted()) {
1129:             return;
1130:         }
1131:         // release all segments owned by compaction partition
1132:         this.compactionMemory.clearAllMemory(availableMemory);
1133:         this.compactionMemory.allocateSegments(1);
1134:         this.compactionMemory.pushDownPages();
1135:         T tempHolder = this.buildSideSerializer.createInstance();
1136:         final int numPartitions = this.partitions.size();
1137:         InMemoryPartition<T> partition = this.partitions.remove(partitionNumber);
1138:         MemorySegment[] overflowSegments = partition.overflowSegments;
1139:         long pointer;
1140:         int pointerOffset;
1141:         int bucketOffset;
1142:         final int bucketsPerSegment = this.bucketsPerSegmentMask + 1;
1143:         for (int i = 0, bucket = partitionNumber;
1144:                 i < this.buckets.length && bucket < this.numBuckets;
1145:                 i++) {
1146:             MemorySegment segment = this.buckets[i];
1147:             // go over all buckets in the segment belonging to the partition
1148:             for (int k = bucket % bucketsPerSegment;
1149:                     k < bucketsPerSegment && bucket < this.numBuckets;
1150:                     k += numPartitions, bucket += numPartitions) {
1151:                 bucketOffset = k * HASH_BUCKET_SIZE;
1152:                 if ((int) segment.get(bucketOffset + HEADER_PARTITION_OFFSET) != partitionNumber) {
1153:                     throw new IOException(
1154:                             "Accessed wrong bucket! wanted: "
1155:                                     + partitionNumber
1156:                                     + " got: "
1157:                                     + segment.get(bucketOffset + HEADER_PARTITION_OFFSET));
1158:                 }
1159:                 // loop over all segments that are involved in the bucket (original bucket plus
1160:                 // overflow buckets)
1161:                 int countInSegment = segment.getInt(bucketOffset + HEADER_COUNT_OFFSET);
1162:                 int numInSegment = 0;
1163:                 pointerOffset = bucketOffset + BUCKET_POINTER_START_OFFSET;
1164:                 while (true) {
1165:                     while (numInSegment < countInSegment) {
1166:                         pointer = segment.getLong(pointerOffset);
1167:                         tempHolder = partition.readRecordAt(pointer, tempHolder);
1168:                         pointer = this.compactionMemory.appendRecord(tempHolder);
1169:                         segment.putLong(pointerOffset, pointer);
1170:                         pointerOffset += POINTER_LEN;
1171:                         numInSegment++;
1172:                     }
1173:                     // this segment is done. check if there is another chained bucket
1174:                     final long forwardPointer =
1175:                             segment.getLong(bucketOffset + HEADER_FORWARD_OFFSET);
1176:                     if (forwardPointer == BUCKET_FORWARD_POINTER_NOT_SET) {
1177:                         break;
1178:                     }
1179:                     final int overflowSegNum = (int) (forwardPointer >>> 32);
1180:                     segment = overflowSegments[overflowSegNum];
1181:                     bucketOffset = (int) forwardPointer;
1182:                     countInSegment = segment.getInt(bucketOffset + HEADER_COUNT_OFFSET);
1183:                     pointerOffset = bucketOffset + BUCKET_POINTER_START_OFFSET;
1184:                     numInSegment = 0;
1185:                 }
1186:                 segment = this.buckets[i];
1187:             }
1188:         }
1189:         // swap partition with compaction partition
1190:         this.compactionMemory.setPartitionNumber(partitionNumber);
1191:         this.partitions.add(partitionNumber, compactionMemory);
1192:         this.partitions.get(partitionNumber).overflowSegments = partition.overflowSegments;
1193:         this.partitions.get(partitionNumber).numOverflowSegments = partition.numOverflowSegments;
1194:         this.partitions.get(partitionNumber).nextOverflowBucket = partition.nextOverflowBucket;
1195:         this.partitions.get(partitionNumber).setIsCompacted(true);
1196:         // this.partitions.get(partitionNumber).pushDownPages();
1197:         this.compactionMemory = partition;
1198:         this.compactionMemory.resetRecordCounter();
1199:         this.compactionMemory.setPartitionNumber(-1);
1200:         this.compactionMemory.overflowSegments = null;
1201:         this.compactionMemory.numOverflowSegments = 0;
1202:         this.compactionMemory.nextOverflowBucket = 0;
1203:         // try to allocate maximum segment count
1204:         this.compactionMemory.clearAllMemory(this.availableMemory);
1205:         int maxSegmentNumber = this.getMaxPartition();
1206:         this.compactionMemory.allocateSegments(maxSegmentNumber);
1207:         this.compactionMemory.resetRWViews();
1208:         this.compactionMemory.pushDownPages();
1209:     }
