1211:     /**
1212:      * Iterator that traverses the whole hash table once
1213:      *
1214:      * <p>If entries are inserted during iteration they may be overlooked by the iterator
1215:      */
1216:     public class EntryIterator implements MutableObjectIterator<T> {
1217: 
1218:         private CompactingHashTable<T> table;
1219: 
1220:         private ArrayList<T> cache; // holds full bucket including its overflow buckets
1221: 
1222:         private int currentBucketIndex = 0;
1223:         private int currentSegmentIndex = 0;
1224:         private int currentBucketOffset = 0;
1225:         private int bucketsPerSegment;
1226: 
1227:         private boolean done;
1228: 
1229:         private EntryIterator(CompactingHashTable<T> compactingHashTable) {
1230:             this.table = compactingHashTable;
1231:             this.cache = new ArrayList<T>(64);
1232:             this.done = false;
1233:             this.bucketsPerSegment = table.bucketsPerSegmentMask + 1;
1234:         }
1235: 
1236:         @Override
1237:         public T next(T reuse) throws IOException {
1238:             return next();
1239:         }
1240: 
1241:         @Override
1242:         public T next() throws IOException {
1243:             if (done || this.table.closed) {
1244:                 return null;
1245:             } else if (!cache.isEmpty()) {
1246:                 return cache.remove(cache.size() - 1);
1247:             } else {
1248:                 while (!done && cache.isEmpty()) {
1249:                     done = !fillCache();
1250:                 }
1251:                 if (!done) {
1252:                     return cache.remove(cache.size() - 1);
1253:                 } else {
1254:                     return null;
1255:                 }
1256:             }
1257:         }
1258: 
1259:         /**
1260:          * utility function that inserts all entries from a bucket and its overflow buckets into the
1261:          * cache
1262:          *
1263:          * @return true if last bucket was not reached yet
1264:          * @throws IOException
1265:          */
1266:         private boolean fillCache() throws IOException {
1267:             if (currentBucketIndex >= table.numBuckets) {
1268:                 return false;
1269:             }
1270:             MemorySegment bucket = table.buckets[currentSegmentIndex];
1271:             // get the basic characteristics of the bucket
1272:             final int partitionNumber = bucket.get(currentBucketOffset + HEADER_PARTITION_OFFSET);
1273:             final InMemoryPartition<T> partition = table.partitions.get(partitionNumber);
1274:             final MemorySegment[] overflowSegments = partition.overflowSegments;
1275: 
1276:             int countInSegment = bucket.getInt(currentBucketOffset + HEADER_COUNT_OFFSET);
1277:             int numInSegment = 0;
1278:             int posInSegment = currentBucketOffset + BUCKET_POINTER_START_OFFSET;
1279:             int bucketOffset = currentBucketOffset;
1280: 
1281:             // loop over all segments that are involved in the bucket (original bucket plus overflow
1282:             // buckets)
1283:             while (true) {
1284:                 while (numInSegment < countInSegment) {
1285:                     long pointer = bucket.getLong(posInSegment);
1286:                     posInSegment += POINTER_LEN;
1287:                     numInSegment++;
1288:                     T target = table.buildSideSerializer.createInstance();
1289:                     try {
1290:                         target = partition.readRecordAt(pointer, target);
1291:                         cache.add(target);
1292:                     } catch (IOException e) {
1293:                         throw new RuntimeException(
1294:                                 "Error deserializing record from the Hash Table: " + e.getMessage(),
1295:                                 e);
1296:                     }
1297:                 }
1298:                 // this segment is done. check if there is another chained bucket
1299:                 final long forwardPointer = bucket.getLong(bucketOffset + HEADER_FORWARD_OFFSET);
1300:                 if (forwardPointer == BUCKET_FORWARD_POINTER_NOT_SET) {
1301:                     break;
1302:                 }
1303:                 final int overflowSegNum = (int) (forwardPointer >>> 32);
1304:                 bucket = overflowSegments[overflowSegNum];
1305:                 bucketOffset = (int) forwardPointer;
1306:                 countInSegment = bucket.getInt(bucketOffset + HEADER_COUNT_OFFSET);
1307:                 posInSegment = bucketOffset + BUCKET_POINTER_START_OFFSET;
1308:                 numInSegment = 0;
1309:             }
1310:             currentBucketIndex++;
1311:             if (currentBucketIndex % bucketsPerSegment == 0) {
1312:                 currentSegmentIndex++;
1313:                 currentBucketOffset = 0;
1314:             } else {
1315:                 currentBucketOffset += HASH_BUCKET_SIZE;
1316:             }
1317:             return true;
1318:         }
1319:     }
