1321:     public final class HashTableProber<PT> extends AbstractHashTableProber<PT, T> {
1322: 
1323:         private InMemoryPartition<T> partition;
1324: 
1325:         private MemorySegment bucket;
1326: 
1327:         private int pointerOffsetInBucket;
