1334:         public T getMatchFor(PT probeSideRecord, T reuse) {
1335:             if (closed) {
1336:                 return null;
1337:             }
1338:             final int searchHashCode =
1339:                     MathUtils.jenkinsHash(this.probeTypeComparator.hash(probeSideRecord));
1340: 
1341:             final int posHashCode = searchHashCode % numBuckets;
1342: 
1343:             // get the bucket for the given hash code
1344:             MemorySegment bucket = buckets[posHashCode >> bucketsPerSegmentBits];
1345:             int bucketInSegmentOffset =
1346:                     (posHashCode & bucketsPerSegmentMask) << NUM_INTRA_BUCKET_BITS;
1347: 
1348:             // get the basic characteristics of the bucket
1349:             final int partitionNumber = bucket.get(bucketInSegmentOffset + HEADER_PARTITION_OFFSET);
1350:             final InMemoryPartition<T> p = partitions.get(partitionNumber);
1351:             final MemorySegment[] overflowSegments = p.overflowSegments;
1352: 
1353:             this.pairComparator.setReference(probeSideRecord);
1354: 
1355:             int countInSegment = bucket.getInt(bucketInSegmentOffset + HEADER_COUNT_OFFSET);
1356:             int numInSegment = 0;
1357:             int posInSegment = bucketInSegmentOffset + BUCKET_HEADER_LENGTH;
1358: 
1359:             // loop over all segments that are involved in the bucket (original bucket plus overflow
1360:             // buckets)
1361:             while (true) {
1362: 
1363:                 while (numInSegment < countInSegment) {
1364: 
1365:                     final int thisCode = bucket.getInt(posInSegment);
1366:                     posInSegment += HASH_CODE_LEN;
