481:     private BufferPool internalCreateBufferPool(
482:             int numExpectedBuffers,
483:             int minUsedBuffers,
484:             int maxUsedBuffers,
485:             int numSubpartitions,
486:             int maxBuffersPerChannel,
487:             int maxOverdraftBuffersPerGate)
488:             throws IOException {
489: 
490:         // It is necessary to use a separate lock from the one used for buffer
491:         // requests to ensure deadlock freedom for failure cases.
492:         synchronized (factoryLock) {
493:             if (isDestroyed) {
494:                 throw new IllegalStateException("Network buffer pool has already been destroyed.");
495:             }
496: 
497:             // Ensure that the number of required buffers can be satisfied.
498:             // With dynamic memory management this should become obsolete.
499:             if (numTotalRequiredBuffers + minUsedBuffers > totalNumberOfMemorySegments) {
500:                 throw new IOException(
501:                         String.format(
502:                                 "Insufficient number of network buffers: "
503:                                         + "required %d, but only %d available. %s.",
504:                                 minUsedBuffers,
505:                                 totalNumberOfMemorySegments - numTotalRequiredBuffers,
506:                                 getConfigDescription()));
507:             }
508: 
509:             this.numTotalRequiredBuffers += minUsedBuffers;
510: 
511:             // We are good to go, create a new buffer pool and redistribute
512:             // non-fixed size buffers.
513:             LocalBufferPool localBufferPool =
514:                     new LocalBufferPool(
515:                             this,
516:                             numExpectedBuffers,
517:                             minUsedBuffers,
518:                             maxUsedBuffers,
519:                             numSubpartitions,
520:                             maxBuffersPerChannel,
521:                             maxOverdraftBuffersPerGate);
522: 
523:             allBufferPools.add(localBufferPool);
524: 
525:             if (minUsedBuffers < maxUsedBuffers) {
526:                 resizableBufferPools.add(localBufferPool);
527:             }
528: 
529:             redistributeBuffers();
530: 
531:             return localBufferPool;
532:         }
533:     }
