575:     // Must be called from synchronized block
576:     private void tryRedistributeBuffers(int numberOfSegmentsToRequest) throws IOException {
577:         assert Thread.holdsLock(factoryLock);
578: 
579:         if (numTotalRequiredBuffers + numberOfSegmentsToRequest > totalNumberOfMemorySegments) {
580:             throw new IOException(
581:                     String.format(
582:                             "Insufficient number of network buffers: "
583:                                     + "required %d, but only %d available. %s.",
584:                             numberOfSegmentsToRequest,
585:                             totalNumberOfMemorySegments - numTotalRequiredBuffers,
586:                             getConfigDescription()));
587:         }
588: 
589:         this.numTotalRequiredBuffers += numberOfSegmentsToRequest;
590: 
591:         try {
592:             redistributeBuffers();
593:         } catch (Throwable t) {
594:             this.numTotalRequiredBuffers -= numberOfSegmentsToRequest;
595: 
596:             redistributeBuffers();
597:             ExceptionUtils.rethrow(t);
598:         }
599:     }
