601:     // Must be called from synchronized block
602:     private void redistributeBuffers() {
603:         assert Thread.holdsLock(factoryLock);
604: 
605:         if (resizableBufferPools.isEmpty()) {
606:             return;
607:         }
608: 
609:         // All buffers, which are not among the required ones
610:         int numAvailableMemorySegment = totalNumberOfMemorySegments - numTotalRequiredBuffers;
611: 
612:         if (numAvailableMemorySegment == 0) {
613:             // in this case, we need to redistribute buffers so that every pool gets its minimum
614:             for (LocalBufferPool bufferPool : resizableBufferPools) {
615:                 bufferPool.setNumBuffers(bufferPool.getNumberOfRequiredMemorySegments());
616:             }
617:             return;
618:         }
619: 
620:         // Calculates the number of buffers that can be redistributed and the total weight of buffer
621:         // pools that are resizable
622:         int totalWeight = 0;
623:         int numBuffersToBeRedistributed = numAvailableMemorySegment;
624:         for (LocalBufferPool bufferPool : resizableBufferPools) {
625:             numBuffersToBeRedistributed += bufferPool.getNumberOfRequiredMemorySegments();
626:             totalWeight += bufferPool.getExpectedNumberOfMemorySegments();
627:         }
628: 
629:         // First, all buffers are allocated proportionally according to the expected values of each
630:         // pool as weights. However, due to the constraints of minimum and maximum values, the
631:         // actual number of buffers distributed may be more or less than the total number of
632:         // buffers.
633:         int totalAllocated = 0;
634:         Map<LocalBufferPool, Integer> cachedPoolSize = new HashMap<>(resizableBufferPools.size());
635:         for (LocalBufferPool bufferPool : resizableBufferPools) {
636:             int expectedNumBuffers =
637:                     bufferPool.getExpectedNumberOfMemorySegments()
638:                             * numBuffersToBeRedistributed
639:                             / totalWeight;
640:             int actualAllocated =
641:                     Math.min(
642:                             bufferPool.getMaxNumberOfMemorySegments(),
643:                             Math.max(
644:                                     bufferPool.getNumberOfRequiredMemorySegments(), expectedNumBuffers));
645:             cachedPoolSize.put(bufferPool, actualAllocated);
646:             totalAllocated += actualAllocated;
647:         }
648: 
649:         // Now we need to deal with this difference, which may be greater than zero or less than
650:         // zero.
651:         int delta = numBuffersToBeRedistributed - totalAllocated;
652: 
653:         int remaining = Integer.MAX_VALUE;
654:         while (remaining != 0) {
655:             remaining = redistributeBuffers(delta, cachedPoolSize);
656: 
657:             // Stop the loop iteration when there is no remaining segments to be redistributed
658:             // or all local buffer pools have reached the max number.
659:             if (remaining == delta) {
660:                 break;
661:             }
662:             delta = remaining;
663:         }
664: 
665:         for (LocalBufferPool bufferPool : resizableBufferPools) {
666:             bufferPool.setNumBuffers(
667:                     cachedPoolSize.getOrDefault(
668:                             bufferPool, bufferPool.getNumberOfRequiredMemorySegments()));
669:         }
670:     }
671: 
672:     /**
673:      * @param delta the buffers to be redistributed.
674:      * @param cachedPoolSize the map to cache the intermediate result.
675:      * @return the remaining buffers that can continue to be redistributed.
676:      */
677:     private int redistributeBuffers(int delta, Map<LocalBufferPool, Integer> cachedPoolSize) {
678:         Set<LocalBufferPool> poolsToBeRedistributed = new HashSet<>();
679: 
680:         if (delta > 0) {
681:             // In this case, we need to allocate the remaining buffers to pools that have
682:             // not yet reached their maximum number.
683: 
684:             int totalWeight = 0;
685:             for (LocalBufferPool bufferPool : resizableBufferPools) {
686:                 if (cachedPoolSize.get(bufferPool) < bufferPool.getMaxNumberOfMemorySegments()) {
687:                     poolsToBeRedistributed.add(bufferPool);
688:                     totalWeight += bufferPool.getExpectedNumberOfMemorySegments();
689:                 }
690:             }
691: 
692:             int totalAllocated = 0;
693:             float pieceOfDelta = ((float) delta) / totalWeight;
694:             for (LocalBufferPool bufferPool : poolsToBeRedistributed) {
695:                 int extraAllocated =
696:                         Math.min(
697:                                 delta - totalAllocated,
698:                                 (int)
699:                                         Math.ceil(
700:                                                 pieceOfDelta
701:                                                         * bufferPool
702:                                                                 .getExpectedNumberOfMemorySegments()));
703:                 int numBuffers =
704:                         Math.min(
705:                                 bufferPool.getMaxNumberOfMemorySegments(),
706:                                 cachedPoolSize.get(bufferPool) + extraAllocated);
707:                 totalAllocated += numBuffers - cachedPoolSize.get(bufferPool);
708:                 cachedPoolSize.put(bufferPool, numBuffers);
709:                 if (totalAllocated == delta) {
710:                     break;
711:                 }
712:             }
713:             return delta - totalAllocated;
714:         } else if (delta < 0) {
715:             // In this case, we need to take back the previously allocated buffers from pools that
716:             // have not yet reached their minimum number.
717: 
718:             int totalWeight = 0;
719:             for (LocalBufferPool bufferPool : resizableBufferPools) {
720:                 if (cachedPoolSize.get(bufferPool) == bufferPool.getNumberOfRequiredMemorySegments()) {
721:                     continue;
722:                 }
723:                 poolsToBeRedistributed.add(bufferPool);
724:                 totalWeight += bufferPool.getExpectedNumberOfMemorySegments();
725:             }
726: 
727:             int totalDeallocated = 0;
728:             int deltaAbs = Math.abs(delta);
729:             float pieceOfDelta = ((float) deltaAbs) / totalWeight;
730:             for (LocalBufferPool bufferPool : poolsToBeRedistributed) {
731:                 int extraDeallocated =
732:                         Math.min(
733:                                 deltaAbs - totalDeallocated,
734:                                 (int)
735:                                         Math.ceil(
736:                                                 pieceOfDelta
737:                                                         * bufferPool
738:                                                                 .getExpectedNumberOfMemorySegments()));
739:                 int numBuffers =
740:                         Math.max(
741:                                 bufferPool.getNumberOfRequiredMemorySegments(),
742:                                 cachedPoolSize.get(bufferPool) - extraDeallocated);
743:                 totalDeallocated += cachedPoolSize.get(bufferPool) - numBuffers;
744:                 cachedPoolSize.put(bufferPool, numBuffers);
745:                 if (totalDeallocated == deltaAbs) {
746:                     break;
747:                 }
748:             }
749:             return delta + totalDeallocated;
750:         } else {
751:             return 0;
752:         }
753:     }
