41: /**
42:  * A buffer pool used to manage a number of {@link Buffer} instances from the {@link
43:  * NetworkBufferPool}.
44:  *
45:  * <p>Buffer requests are mediated to the network buffer pool to ensure deadlock free operation of
46:  * the network stack by limiting the number of buffers per local buffer pool. It also implements the
47:  * default mechanism for buffer recycling, which ensures that every buffer is ultimately returned to
48:  * the network buffer pool.
49:  *
50:  * <p>The size of this pool can be dynamically changed at runtime ({@link #setNumBuffers(int)}. It
51:  * will then lazily return the required number of buffers to the {@link NetworkBufferPool} to match
52:  * its new size.
53:  *
54:  * <p>New buffers can be requested only when {@code numberOfRequestedMemorySegments <
55:  * currentPoolSize + maxOverdraftBuffersPerGate}. In other words, all buffers exceeding the
56:  * currentPoolSize will be dynamically regarded as overdraft buffers.
57:  *
58:  * <p>Availability is defined as returning a non-overdraft segment on a subsequent {@link
59:  * #requestBuffer()}/ {@link #requestBufferBuilder()} and heaving a non-blocking {@link
60:  * #requestBufferBuilderBlocking(int)}. In particular,
61:  *
62:  * <ul>
63:  *   <li>There is at least one {@link #availableMemorySegments}.
64:  *   <li>No subpartitions has reached {@link #maxBuffersPerChannel}.
65:  * </ul>
66:  *
67:  * <p>To ensure this contract, the implementation eagerly fetches additional memory segments from
68:  * {@link NetworkBufferPool} as long as it hasn't reached {@link #maxNumberOfMemorySegments} or one
69:  * subpartition reached the quota.
70:  */
71: public class LocalBufferPool implements BufferPool {
72:     private static final Logger LOG = LoggerFactory.getLogger(LocalBufferPool.class);
73: 
74:     private static final int UNKNOWN_CHANNEL = -1;
75: 
76:     /** Global network buffer pool to get buffers from. */
77:     private final NetworkBufferPool networkBufferPool;
78: 
79:     /**
80:      * The currently available memory segments. These are segments, which have been requested from
81:      * the network buffer pool and are currently not handed out as Buffer instances.
82:      *
83:      * <p><strong>BEWARE:</strong> Take special care with the interactions between this lock and
84:      * locks acquired before entering this class vs. locks being acquired during calls to external
85:      * code inside this class, e.g. with {@code
86:      * org.apache.flink.runtime.io.network.partition.consumer.BufferManager#bufferQueue} via the
87:      * {@link #registeredListeners} callback.
88:      */
89:     private final ArrayDeque<MemorySegment> availableMemorySegments = new ArrayDeque<>();
90: 
91:     /**
92:      * Buffer availability listeners, which need to be notified when a Buffer becomes available.
93:      * Listeners can only be registered at a time/state where no Buffer instance was available.
94:      */
95:     private final ArrayDeque<BufferListener> registeredListeners = new ArrayDeque<>();
96: 
97:     /**
98:      * The number of expected memory segments of this buffer pool.
99:      *
100:      * <p>Usually, the buffers in {@link NetworkBufferPool} do not exactly meet the expectations of
101:      * all {@link LocalBufferPool}s, so typically this value is used as a weight to allocate buffers
102:      * to each {@link LocalBufferPool}.
103:      */
104:     private final int expectedNumberOfMemorySegments;
