107:                         // Ensure that a subpartition's memory tier does not excessively use
108:                         // buffers, which may result in insufficient buffers for other subpartitions
109:                         && subpartitionProducerAgents[subpartitionId.getSubpartitionId()]
110:                                         .numQueuedBuffers()
