373:         private void loadDiskDataToBuffers(Queue<MemorySegment> buffers, BufferRecycler recycler)
374:                 throws IOException {
375: 
376:             if (isFailed) {
377:                 throw new IOException(
378:                         "The scheduled subpartition reader for "
379:                                 + subpartitionId
380:                                 + " has already been failed.");
381:             }
382: 
383:             CompositeBuffer partialBuffer = null;
384:             boolean shouldContinueRead = true;
385:             try {
386:                 while (!buffers.isEmpty() && shouldContinueRead && nextSegmentId >= 0) {
387:                     MemorySegment memorySegment = buffers.poll();
388:                     PartitionFileReader.ReadBufferResult readBufferResult;
389:                     try {
390:                         readBufferResult =
391:                                 partitionFileReader.readBuffer(
392:                                         partitionId,
393:                                         subpartitionId,
394:                                         nextSegmentId,
395:                                         nextBufferIndex,
396:                                         memorySegment,
397:                                         recycler,
398:                                         readProgress,
399:                                         partialBuffer);
400:                         if (readBufferResult == null) {
401:                             buffers.add(memorySegment);
402:                             break;
403:                         }
404:                     } catch (IOException exception) {
405:                         buffers.add(memorySegment);
406:                         throw exception;
407:                     }
408: 
409:                     List<Buffer> readBuffers = readBufferResult.getReadBuffers();
410:                     shouldContinueRead = readBufferResult.continuousReadSuggested();
411:                     readProgress = readBufferResult.getReadProgress();
412:                     if (readBuffers.isEmpty()) {
413:                         buffers.add(memorySegment);
414:                         break;
415:                     }
416: 
417:                     partialBuffer = writeFullBuffersAndGetPartialBuffer(readBuffers);
418:                 }
419:             } finally {
420:                 if (partialBuffer != null) {
421:                     partialBuffer.recycleBuffer();
422:                 }
423:             }
424:         }
