432:         private void prepareForScheduling() throws IOException {
433:             if (nextSegmentId < 0) {
434:                 updateSegmentId();
435:             }
436:             priority =
437:                     nextSegmentId < 0
438:                             ? Long.MAX_VALUE
439:                             : partitionFileReader.getPriority(
440:                                     partitionId,
441:                                     subpartitionId,
442:                                     nextSegmentId,
443:                                     nextBufferIndex,
444:                                     readProgress);
445:         }
446: 
447:         private CompositeBuffer writeFullBuffersAndGetPartialBuffer(List<Buffer> readBuffers) {
448:             CompositeBuffer partialBuffer = null;
449:             for (int i = 0; i < readBuffers.size(); i++) {
450:                 Buffer readBuffer = readBuffers.get(i);
451:                 if (i == readBuffers.size() - 1 && isPartialBuffer(readBuffer)) {
452:                     partialBuffer = (CompositeBuffer) readBuffer;
453:                     continue;
454:                 }
455:                 writeNettyBufferAndUpdateSegmentId(readBuffer);
456:             }
457:             return partialBuffer;
458:         }
