460:         private boolean isPartialBuffer(Buffer readBuffer) {
461:             return readBuffer instanceof CompositeBuffer
462:                     && ((CompositeBuffer) readBuffer).missingLength() > 0;
463:         }
464: 
465:         private void writeNettyBufferAndUpdateSegmentId(Buffer readBuffer) {
466:             writeToNettyConnectionWriter(
467:                     NettyPayload.newBuffer(
468:                             readBuffer, nextBufferIndex++, subpartitionId.getSubpartitionId()));
469:             if (readBuffer.getDataType() == Buffer.DataType.END_OF_SEGMENT) {
470:                 nextSegmentId = -1;
471:                 updateSegmentId();
472:             }
473:         }
474: 
475:         private void writeToNettyConnectionWriter(NettyPayload nettyPayload) {
476:             nettyConnectionWriter.writeNettyPayload(nettyPayload);
477:             if (nettyConnectionWriter.numQueuedPayloads() <= 1
478:                     || nettyConnectionWriter.numQueuedBufferPayloads() <= 1) {
479:                 notifyAvailable();
480:             }
481:         }
482: 
483:         private long getPriority() {
484:             return priority;
485:         }
486: 
487:         private void notifyAvailable() {
488:             nettyConnectionWriter.notifyAvailable();
489:         }
490: 
491:         private void failReader(Throwable failureCause) {
492:             if (isFailed) {
493:                 return;
494:             }
495:             isFailed = true;
496:             nettyConnectionWriter.close(failureCause);
497:             nettyConnectionWriter.notifyAvailable();
498:         }
499: 
500:         private void updateSegmentId() {
501:             Integer segmentId =
502:                     segmentIdGetter.apply(subpartitionId.getSubpartitionId(), nextBufferIndex);
503:             if (segmentId != null) {
504:                 nextSegmentId = segmentId;
505:                 writeToNettyConnectionWriter(NettyPayload.newSegment(segmentId));
506:             }
507:         }
508: 
509:         private NettyConnectionId getId() {
510:             return nettyConnectionWriter.getNettyConnectionId();
511:         }
512:     }
