87: 
88:     /** Total number of records already appended to this sort buffer. */
89:     private long numTotalRecords;
90: 
91:     /** Total number of bytes already read from this sort buffer. */
92:     protected long numTotalBytesRead;
93: 
94:     /** Whether this sort buffer is finished. One can only read a finished sort buffer. */
95:     protected boolean isFinished;
