100:     // ---------------------------------------------------------------------------------------------
101:     // For writing
102:     // ---------------------------------------------------------------------------------------------
103: 
104:     /** Array index in the segment list of the current available buffer for writing. */
105:     private int writeSegmentIndex;
106: 
107:     /** Next position in the current available buffer for writing. */
108:     private int writeSegmentOffset;
109: 
110:     // ---------------------------------------------------------------------------------------------
111:     // For reading
112:     // ---------------------------------------------------------------------------------------------
113: 
114:     /** Data of different subpartitions in this sort buffer will be read in this order. */
115:     protected final int[] subpartitionReadOrder;
116: 
117:     /** Index entry address of the current record or event to be read. */
118:     protected long readIndexEntryAddress;
119: 
120:     /** Record bytes remaining after last copy, which must be read first in next copy. */
121:     protected int recordRemainingBytes;
122: 
123:     /** Used to index the current available subpartition to read data from. */
124:     protected int readOrderIndex = -1;
125: 
126:     protected SortBuffer(
127:             LinkedList<MemorySegment> freeSegments,
128:             BufferRecycler bufferRecycler,
129:             int numSubpartitions,
130:             int bufferSize,
131:             int numGuaranteedBuffers,
132:             @Nullable int[] customReadOrder) {
133:         checkArgument(bufferSize > INDEX_ENTRY_SIZE, "Buffer size is too small.");
134:         checkArgument(numGuaranteedBuffers > 0, "No guaranteed buffers for sort.");
