187:     private void writeIndex(int subpartitionIndex, int numRecordBytes, Buffer.DataType dataType) {
188:         MemorySegment segment = segments.get(writeSegmentIndex);
189: 
190:         // record length takes the high 32 bits and data type takes the low 32 bits
191:         segment.putLong(writeSegmentOffset, ((long) numRecordBytes << 32) | dataType.ordinal());
192: 
193:         // segment index takes the high 32 bits and segment offset takes the low 32 bits
194:         long indexEntryAddress = ((long) writeSegmentIndex << 32) | writeSegmentOffset;
195: 
196:         long lastIndexEntryAddress = lastIndexEntryAddresses[subpartitionIndex];
197:         lastIndexEntryAddresses[subpartitionIndex] = indexEntryAddress;
198: 
199:         if (lastIndexEntryAddress >= 0) {
200:             // link the previous index entry of the given subpartition to the new index entry
201:             segment = segments.get(getSegmentIndexFromPointer(lastIndexEntryAddress));
202:             segment.putLong(
203:                     getSegmentOffsetFromPointer(lastIndexEntryAddress) + 8, indexEntryAddress);
204:         } else {
205:             firstIndexEntryAddresses[subpartitionIndex] = indexEntryAddress;
206:         }
