208:         // move the write position forward so as to write the corresponding record
209:         updateWriteSegmentIndexAndOffset(INDEX_ENTRY_SIZE);
210:     }
211: 
212:     private void writeRecord(ByteBuffer source) {
213:         while (source.hasRemaining()) {
214:             MemorySegment segment = segments.get(writeSegmentIndex);
215:             int toCopy = Math.min(bufferSize - writeSegmentOffset, source.remaining());
216:             segment.put(writeSegmentOffset, source, toCopy);
217: 
218:             // move the write position forward so as to write the remaining bytes or next record
219:             updateWriteSegmentIndexAndOffset(toCopy);
220:         }
221:     }
222: 
223:     private boolean allocateBuffersForRecord(int numRecordBytes) {
224:         int numBytesRequired = INDEX_ENTRY_SIZE + numRecordBytes;
225:         int availableBytes =
226:                 writeSegmentIndex == segments.size() ? 0 : bufferSize - writeSegmentOffset;
227: 
228:         // return directly if current available bytes is adequate
229:         if (availableBytes >= numBytesRequired) {
230:             return true;
231:         }
232: 
233:         // skip the remaining free space if the available bytes is not enough for an index entry
234:         if (availableBytes < INDEX_ENTRY_SIZE) {
235:             updateWriteSegmentIndexAndOffset(availableBytes);
236:             availableBytes = 0;
237:         }
238: 
239:         if (availableBytes + (numGuaranteedBuffers - segments.size()) * (long) bufferSize
240:                 < numBytesRequired) {
241:             return false;
242:         }
243: 
244:         // allocate exactly enough buffers for the appended record
245:         do {
246:             MemorySegment segment = freeSegments.poll();
247:             availableBytes += bufferSize;
248:             addBuffer(checkNotNull(segment));
249:         } while (availableBytes < numBytesRequired);
250: 
251:         return true;
252:     }
253: 
254:     private void addBuffer(MemorySegment segment) {
255:         if (segment.size() != bufferSize) {
256:             bufferRecycler.recycle(segment);
257:             throw new IllegalStateException("Illegal memory segment size.");
258:         }
259: 
260:         if (isReleased) {
261:             bufferRecycler.recycle(segment);
262:             throw new IllegalStateException("Sort buffer is already released.");
263:         }
264: 
265:         segments.add(segment);
266:     }
