268:     private void updateWriteSegmentIndexAndOffset(int numBytes) {
269:         writeSegmentOffset += numBytes;
270: 
271:         // using the next available free buffer if the current is full
272:         if (writeSegmentOffset == bufferSize) {
273:             ++writeSegmentIndex;
274:             writeSegmentOffset = 0;
275:         }
276:     }
277: 
278:     protected int copyRecordOrEvent(
279:             MemorySegment targetSegment,
280:             int targetSegmentOffset,
281:             int sourceSegmentIndex,
282:             int sourceSegmentOffset,
283:             int recordLength) {
284:         if (recordRemainingBytes > 0) {
285:             // skip the data already read if there is remaining partial record after the previous
286:             // copy
287:             long position = (long) sourceSegmentOffset + (recordLength - recordRemainingBytes);
288:             sourceSegmentIndex += (position / bufferSize);
289:             sourceSegmentOffset = (int) (position % bufferSize);
290:         } else {
291:             recordRemainingBytes = recordLength;
292:         }
293: 
294:         int targetSegmentSize = targetSegment.size();
295:         int numBytesToCopy =
296:                 Math.min(targetSegmentSize - targetSegmentOffset, recordRemainingBytes);
297:         do {
298:             // move to next data buffer if all data of the current buffer has been copied
299:             if (sourceSegmentOffset == bufferSize) {
300:                 ++sourceSegmentIndex;
301:                 sourceSegmentOffset = 0;
302:             }
303: 
304:             int sourceRemainingBytes =
305:                     Math.min(bufferSize - sourceSegmentOffset, recordRemainingBytes);
306:             int numBytes = Math.min(targetSegmentSize - targetSegmentOffset, sourceRemainingBytes);
307:             MemorySegment sourceSegment = segments.get(sourceSegmentIndex);
308:             sourceSegment.copyTo(sourceSegmentOffset, targetSegment, targetSegmentOffset, numBytes);
309: 
310:             recordRemainingBytes -= numBytes;
311:             targetSegmentOffset += numBytes;
312:             sourceSegmentOffset += numBytes;
313:         } while ((recordRemainingBytes > 0 && targetSegmentOffset < targetSegmentSize));
314: 
315:         return numBytesToCopy;
316:     }
317: 
318:     protected void updateReadSubpartitionAndIndexEntryAddress() {
319:         // skip the subpartitions without any data
320:         while (++readOrderIndex < firstIndexEntryAddresses.length) {
321:             int subpartitionIndex = subpartitionReadOrder[readOrderIndex];
322:             if ((readIndexEntryAddress = firstIndexEntryAddresses[subpartitionIndex]) >= 0) {
323:                 break;
324:             }
325:         }
326:     }
327: 
328:     protected int getSegmentIndexFromPointer(long value) {
329:         return (int) (value >>> 32);
330:     }
331: 
332:     protected int getSegmentOffsetFromPointer(long value) {
333:         return (int) (value);
334:     }
335: 
336:     @Override
337:     public long numTotalRecords() {
338:         return numTotalRecords;
339:     }
340: 
341:     @Override
342:     public long numTotalBytes() {
343:         return numTotalBytes;
344:     }
345: 
346:     @Override
347:     public boolean hasRemaining() {
348:         return numTotalBytesRead < numTotalBytes;
349:     }
350: 
351:     @Override
352:     public void finish() {
353:         checkState(!isFinished, "DataBuffer is already finished.");
354: 
355:         isFinished = true;
356: 
357:         // prepare for reading
358:         updateReadSubpartitionAndIndexEntryAddress();
359:     }
360: 
361:     @Override
362:     public boolean isFinished() {
363:         return isFinished;
364:     }
365: 
366:     @Override
367:     public void release() {
368:         if (isReleased) {
369:             return;
370:         }
371:         isReleased = true;
372: 
373:         for (MemorySegment segment : segments) {
374:             bufferRecycler.recycle(segment);
375:         }
376:         segments.clear();
377:     }
378: 
379:     @Override
380:     public boolean isReleased() {
381:         return isReleased;
382:     }
383: }
