304:             int sourceRemainingBytes =
305:                     Math.min(bufferSize - sourceSegmentOffset, recordRemainingBytes);
306:             int numBytes = Math.min(targetSegmentSize - targetSegmentOffset, sourceRemainingBytes);
307:             MemorySegment sourceSegment = segments.get(sourceSegmentIndex);
308:             sourceSegment.copyTo(sourceSegmentOffset, targetSegment, targetSegmentOffset, numBytes);
309: 
310:             recordRemainingBytes -= numBytes;
311:             targetSegmentOffset += numBytes;
312:             sourceSegmentOffset += numBytes;
313:         } while ((recordRemainingBytes > 0 && targetSegmentOffset < targetSegmentSize));
314: 
315:         return numBytesToCopy;
316:     }
