375:     private static int calculateNumChannels(
376:             int numShuffleDescriptors,
377:             int numSubpartitions,
378:             boolean isSharedInputChannelSupported) {
379:         if (isSharedInputChannelSupported) {
380:             return numShuffleDescriptors;
381:         } else {
382:             return MathUtils.checkedDownCast(((long) numShuffleDescriptors) * numSubpartitions);
383:         }
384:     }
