386:     @VisibleForTesting
387:     protected InputChannel createKnownInputChannel(
388:             SingleInputGate inputGate,
389:             int index,
390:             int buffersPerChannel,
391:             NettyShuffleDescriptor inputChannelDescriptor,
392:             ResultSubpartitionIndexSet subpartitionIndexSet,
393:             ChannelStatistics channelStatistics,
394:             InputChannelMetrics metrics) {
395:         ResultPartitionID partitionId = inputChannelDescriptor.getResultPartitionID();
396:         if (inputChannelDescriptor.isLocalTo(taskExecutorResourceId)) {
397:             // Consuming task is deployed to the same TaskManager as the partition => local
398:             channelStatistics.numLocalChannels++;
399:             return new LocalRecoveredInputChannel(
400:                     inputGate,
401:                     index,
402:                     partitionId,
403:                     subpartitionIndexSet,
404:                     partitionManager,
405:                     taskEventPublisher,
406:                     partitionRequestInitialBackoff,
407:                     partitionRequestMaxBackoff,
408:                     buffersPerChannel,
409:                     metrics);
410:         } else {
411:             // Different instances => remote
412:             channelStatistics.numRemoteChannels++;
413:             return new RemoteRecoveredInputChannel(
414:                     inputGate,
415:                     index,
416:                     partitionId,
417:                     subpartitionIndexSet,
418:                     inputChannelDescriptor.getConnectionId(),
419:                     connectionManager,
420:                     partitionRequestInitialBackoff,
421:                     partitionRequestMaxBackoff,
422:                     partitionRequestListenerTimeout,
423:                     buffersPerChannel,
424:                     metrics);
425:         }
