428:     private void addTierShuffleDescriptors(
429:             List<List<TierShuffleDescriptor>> tierShuffleDescriptors,
430:             ShuffleDescriptor descriptor) {
431:         if (descriptor instanceof NettyShuffleDescriptor) {
432:             tierShuffleDescriptors.add(
433:                     ((NettyShuffleDescriptor) descriptor).getTierShuffleDescriptors());
434:         } else if (descriptor.isUnknown()) {
435:             List<TierShuffleDescriptor> unknownDescriptors = new ArrayList<>();
436:             int numTiers = checkNotNull(tieredStorageConfiguration).getTierFactories().size();
437:             for (int i = 0; i < numTiers; i++) {
438:                 unknownDescriptors.add(UnknownTierShuffleDescriptor.INSTANCE);
439:             }
440:             tierShuffleDescriptors.add(unknownDescriptors);
441:         } else {
442:             throw new IllegalArgumentException("Unsupported shuffle descriptor type " + descriptor);
443:         }
444:     }
