156:             int subpartitionId,
157:             HsConsumerId consumerId,
158:             HsSubpartitionConsumerInternalOperations operation)
159:             throws IOException {
160:         synchronized (lock) {
161:             checkState(!isReleased, "HsFileDataManager is already released.");
162:             lazyInitialize();
