198:     /** Releases this file data manager and delete shuffle data after all readers is removed. */
199:     public void release() {
200:         synchronized (lock) {
201:             if (isReleased) {
202:                 return;
203:             }
204:             isReleased = true;
205: 
206:             List<HsSubpartitionFileReader> pendingReaders = new ArrayList<>(allReaders);
207:             mayNotifyReleased();
208:             failSubpartitionReaders(
209:                     pendingReaders,
210:                     new IllegalStateException("Result partition has been already released."));
211:             // close data index and delete shuffle file only when no reader is reading now.
212:             releaseFuture.thenRun(this::closeDataIndexAndDeleteShuffleFile);
213:         }
214:     }
