220:     /** @return number of buffers read. */
221:     private int tryRead() {
222:         Queue<HsSubpartitionFileReader> availableReaders = prepareAndGetAvailableReaders();
223:         if (availableReaders.isEmpty()) {
224:             return 0;
225:         }
226: 
227:         Queue<MemorySegment> buffers;
228:         try {
229:             buffers = allocateBuffers();
230:         } catch (Exception exception) {
231:             // fail all pending subpartition readers immediately if any exception occurs
232:             failSubpartitionReaders(availableReaders, exception);
233:             LOG.error("Failed to request buffers for data reading.", exception);
234:             return 0;
235:         }
236: 
237:         int numBuffersAllocated = buffers.size();
238:         if (numBuffersAllocated <= 0) {
239:             return 0;
240:         }
241: 
242:         readData(availableReaders, buffers);
243:         int numBuffersRead = numBuffersAllocated - buffers.size();
244: 
245:         releaseBuffers(buffers);
246: 
247:         return numBuffersRead;
248:     }
