250:     @SuppressWarnings("FieldAccessNotGuarded")
251:     // read-only access to volatile isReleased and numRequestedBuffers
252:     private Queue<MemorySegment> allocateBuffers() throws Exception {
253:         long timeoutTime = getBufferRequestTimeoutTime();
254:         do {
255:             List<MemorySegment> buffers = bufferPool.requestBuffers();
256:             if (!buffers.isEmpty()) {
257:                 return new ArrayDeque<>(buffers);
258:             }
259:             checkState(!isReleased, "Result partition has been already released.");
260:         } while (System.currentTimeMillis() < timeoutTime
261:                 || System.currentTimeMillis() < (timeoutTime = getBufferRequestTimeoutTime()));
262: 
263:         // This is a safe net against potential deadlocks.
264:         //
265:         // A deadlock can happen when the downstream task needs to consume multiple result
266:         // partitions (e.g., A and B) in specific order (cannot consume B before finishing
267:         // consuming A). Since the reading buffer pool is shared across the TM, if B happens to
268:         // take all the buffers, A cannot be consumed due to lack of buffers, which also blocks
269:         // B from being consumed and releasing the buffers.
270:         //
271:         // The imperfect solution here is to fail all the subpartitionReaders (A), which
272:         // consequently fail all the downstream tasks, unregister their other
273:         // subpartitionReaders (B) and release the read buffers.
274:         throw new TimeoutException(
275:                 String.format(
276:                         "Buffer request timeout, this means there is a fierce contention of"
277:                                 + " the batch shuffle read memory, please increase '%s'.",
278:                         TaskManagerOptions.NETWORK_BATCH_SHUFFLE_READ_MEMORY.key()));
279:     }
280: 
281:     private void mayTriggerReading() {
282:         synchronized (lock) {
283:             if (!isRunning
284:                     && !allReaders.isEmpty()
285:                     && numRequestedBuffers + bufferPool.getNumBuffersPerRequest()
286:                             <= maxRequestedBuffers
287:                     && numRequestedBuffers < bufferPool.getAverageBuffersPerRequester()) {
288:                 isRunning = true;
289:                 ioExecutor.execute(
290:                         () -> {
291:                             try {
292:                                 run();
293:                             } catch (Throwable throwable) {
294:                                 // handle un-expected exception as unhandledExceptionHandler is not
295:                                 // worked for ScheduledExecutorService.
296:                                 FatalExitExceptionHandler.INSTANCE.uncaughtException(
297:                                         Thread.currentThread(), throwable);
298:                             }
299:                         });
300:             }
301:         }
302:     }
303: 
304:     @GuardedBy("lock")
305:     private void mayNotifyReleased() {
306:         assert Thread.holdsLock(lock);
307: 
308:         if (isReleased && allReaders.isEmpty()) {
309:             releaseFuture.complete(null);
310:         }
311:     }
312: 
313:     private long getBufferRequestTimeoutTime() {
314:         return bufferPool.getLastBufferOperationTimestamp() + bufferRequestTimeout.toMillis();
315:     }
316: 
317:     private void releaseBuffers(Queue<MemorySegment> buffers) {
318:         if (!buffers.isEmpty()) {
319:             try {
320:                 bufferPool.recycle(buffers);
321:                 buffers.clear();
322:             } catch (Throwable throwable) {
323:                 // this should never happen so just trigger fatal error
324:                 FatalExitExceptionHandler.INSTANCE.uncaughtException(
325:                         Thread.currentThread(), throwable);
326:             }
327:         }
328:     }
329: 
330:     private Queue<HsSubpartitionFileReader> prepareAndGetAvailableReaders() {
331:         synchronized (lock) {
332:             if (isReleased) {
333:                 return new ArrayDeque<>();
334:             }
335: 
336:             for (HsSubpartitionFileReader reader : allReaders) {
337:                 reader.prepareForScheduling();
338:             }
339:             return new PriorityQueue<>(allReaders);
340:         }
341:     }
342: 
343:     private void readData(
344:             Queue<HsSubpartitionFileReader> availableReaders, Queue<MemorySegment> buffers) {
345:         while (!availableReaders.isEmpty() && !buffers.isEmpty()) {
346:             HsSubpartitionFileReader subpartitionReader = availableReaders.poll();
347:             try {
348:                 subpartitionReader.readBuffers(buffers, this);
349:             } catch (IOException throwable) {
350:                 failSubpartitionReaders(Collections.singletonList(subpartitionReader), throwable);
351:                 LOG.debug("Failed to read shuffle data.", throwable);
352:             }
353:         }
354:     }
355: 
356:     private void failSubpartitionReaders(
357:             Collection<HsSubpartitionFileReader> readers, Throwable failureCause) {
358:         synchronized (lock) {
359:             removeSubpartitionReaders(readers);
360:         }
361: 
362:         for (HsSubpartitionFileReader reader : readers) {
363:             reader.fail(failureCause);
364:         }
365:     }
366: 
367:     @GuardedBy("lock")
368:     private void removeSubpartitionReaders(Collection<HsSubpartitionFileReader> readers) {
369:         allReaders.removeAll(readers);
370:         if (allReaders.isEmpty()) {
371:             bufferPool.unregisterRequester(this);
372:             closeFileChannel();
373:         }
374:     }
375: 
376:     private void endCurrentRoundOfReading(int numBuffersRead) {
377:         synchronized (lock) {
378:             numRequestedBuffers += numBuffersRead;
379:             isRunning = false;
380:             mayNotifyReleased();
381:         }
382:         if (numBuffersRead == 0) {
383:             // When fileReader has no data to read, for example, most of the data is
384:             // consumed from memory. HsFileDataManager will encounter busy-loop
385:             // problem, which will lead to a meaningless surge in CPU utilization
386:             // and seriously affect performance.
387:             ioExecutor.schedule(this::mayTriggerReading, 5, TimeUnit.MILLISECONDS);
388:         } else {
389:             mayTriggerReading();
390:         }
391:     }
392: 
393:     @GuardedBy("lock")
394:     private void lazyInitialize() throws IOException {
395:         assert Thread.holdsLock(lock);
396:         try {
397:             if (allReaders.isEmpty()) {
398:                 dataFileChannel = openFileChannel(dataFilePath);
399:                 bufferPool.registerRequester(this);
400:             }
401:         } catch (IOException exception) {
402:             if (allReaders.isEmpty()) {
403:                 bufferPool.unregisterRequester(this);
404:                 closeFileChannel();
405:             }
406:             throw exception;
407:         }
408:     }
409: 
410:     private FileChannel openFileChannel(Path path) throws IOException {
411:         return FileChannel.open(path, StandardOpenOption.READ);
412:     }
413: 
414:     @GuardedBy("lock")
415:     private void closeFileChannel() {
416:         assert Thread.holdsLock(lock);
417: 
418:         IOUtils.closeQuietly(dataFileChannel);
419:         dataFileChannel = null;
420:     }
421: 
422:     // ------------------------------------------------------------------------
423:     //  Implementation Methods of BufferRecycler
424:     // ------------------------------------------------------------------------
425: 
426:     @Override
427:     public void recycle(MemorySegment segment) {
428:         synchronized (lock) {
429:             bufferPool.recycle(segment);
430:             --numRequestedBuffers;
431: 
432:             mayTriggerReading();
433:         }
434:     }
435: }
