250:     @SuppressWarnings("FieldAccessNotGuarded")
251:     // read-only access to volatile isReleased and numRequestedBuffers
252:     private Queue<MemorySegment> allocateBuffers() throws Exception {
253:         long timeoutTime = getBufferRequestTimeoutTime();
254:         do {
255:             List<MemorySegment> buffers = bufferPool.requestBuffers();
256:             if (!buffers.isEmpty()) {
257:                 return new ArrayDeque<>(buffers);
258:             }
259:             checkState(!isReleased, "Result partition has been already released.");
260:         } while (System.currentTimeMillis() < timeoutTime
261:                 || System.currentTimeMillis() < (timeoutTime = getBufferRequestTimeoutTime()));
262: 
263:         // This is a safe net against potential deadlocks.
264:         //
265:         // A deadlock can happen when the downstream task needs to consume multiple result
266:         // partitions (e.g., A and B) in specific order (cannot consume B before finishing
267:         // consuming A). Since the reading buffer pool is shared across the TM, if B happens to
268:         // take all the buffers, A cannot be consumed due to lack of buffers, which also blocks
269:         // B from being consumed and releasing the buffers.
270:         //
271:         // The imperfect solution here is to fail all the subpartitionReaders (A), which
272:         // consequently fail all the downstream tasks, unregister their other
273:         // subpartitionReaders (B) and release the read buffers.
274:         throw new TimeoutException(
275:                 String.format(
276:                         "Buffer request timeout, this means there is a fierce contention of"
277:                                 + " the batch shuffle read memory, please increase '%s'.",
278:                         TaskManagerOptions.NETWORK_BATCH_SHUFFLE_READ_MEMORY.key()));
279:     }
