281:     private void mayTriggerReading() {
282:         synchronized (lock) {
283:             if (!isRunning
284:                     && !allReaders.isEmpty()
285:                     && numRequestedBuffers + bufferPool.getNumBuffersPerRequest()
286:                             <= maxRequiredBuffers
287:                     && numRequestedBuffers < bufferPool.getAverageBuffersPerRequester()) {
288:                 isRunning = true;
289:                 ioExecutor.execute(
290:                         () -> {
291:                             try {
292:                                 run();
293:                             } catch (Throwable throwable) {
294:                                 // handle un-expected exception as unhandledExceptionHandler is not
295:                                 // worked for ScheduledExecutorService.
296:                                 FatalExitExceptionHandler.INSTANCE.uncaughtException(
297:                                         Thread.currentThread(), throwable);
298:                             }
299:                         });
300:             }
301:         }
302:     }
303: 
304:     @GuardedBy("lock")
305:     private void mayNotifyReleased() {
306:         assert Thread.holdsLock(lock);
307: 
308:         if (isReleased && allReaders.isEmpty()) {
309:             releaseFuture.complete(null);
310:         }
311:     }
312: 
313:     private long getBufferRequestTimeoutTime() {
314:         return bufferPool.getLastBufferOperationTimestamp() + bufferRequestTimeout.toMillis();
315:     }
