317:     private void releaseBuffers(Queue<MemorySegment> buffers) {
318:         if (!buffers.isEmpty()) {
319:             try {
320:                 bufferPool.recycle(buffers);
321:                 buffers.clear();
322:             } catch (Throwable throwable) {
323:                 // this should never happen so just trigger fatal error
324:                 FatalExitExceptionHandler.INSTANCE.uncaughtException(
325:                         Thread.currentThread(), throwable);
326:             }
327:         }
328:     }
