330:     private Queue<HsSubpartitionFileReader> prepareAndGetAvailableReaders() {
331:         synchronized (lock) {
332:             if (isReleased) {
333:                 return new ArrayDeque<>();
334:             }
335: 
336:             for (HsSubpartitionFileReader reader : allReaders) {
337:                 reader.prepareForScheduling();
338:             }
339:             return new PriorityQueue<>(allReaders);
340:         }
341:     }
342: 
343:     private void readData(
344:             Queue<HsSubpartitionFileReader> availableReaders, Queue<MemorySegment> buffers) {
345:         while (!availableReaders.isEmpty() && !buffers.isEmpty()) {
346:             HsSubpartitionFileReader subpartitionReader = availableReaders.poll();
347:             try {
348:                 subpartitionReader.readBuffers(buffers, this);
349:             } catch (IOException throwable) {
350:                 failSubpartitionReaders(Collections.singletonList(subpartitionReader), throwable);
351:                 LOG.debug("Failed to read shuffle data.", throwable);
352:             }
353:         }
354:     }
355: 
356:     private void failSubpartitionReaders(
357:             Collection<HsSubpartitionFileReader> readers, Throwable failureCause) {
358:         synchronized (lock) {
359:             removeSubpartitionReaders(readers);
360:         }
361: 
362:         for (HsSubpartitionFileReader reader : readers) {
363:             reader.fail(failureCause);
364:         }
365:     }
366: 
367:     @GuardedBy("lock")
368:     private void removeSubpartitionReaders(Collection<HsSubpartitionFileReader> readers) {
369:         allReaders.removeAll(readers);
370:         if (allReaders.isEmpty()) {
371:             bufferPool.unregisterRequester(this);
372:             closeFileChannel();
373:         }
374:     }
375: 
376:     private void endCurrentRoundOfReading(int numBuffersRead) {
377:         synchronized (lock) {
378:             numRequestedBuffers += numBuffersRead;
379:             isRunning = false;
380:             mayNotifyReleased();
381:         }
382:         if (numBuffersRead == 0) {
383:             // When fileReader has no data to read, for example, most of the data is
384:             // consumed from memory. HsFileDataManager will encounter busy-loop
385:             // problem, which will lead to a meaningless surge in CPU utilization
386:             // and seriously affect performance.
387:             ioExecutor.schedule(this::mayTriggerReading, 5, TimeUnit.MILLISECONDS);
388:         } else {
389:             mayTriggerReading();
390:         }
391:     }
392: 
393:     @GuardedBy("lock")
394:     private void lazyInitialize() throws IOException {
395:         assert Thread.holdsLock(lock);
396:         try {
397:             if (allReaders.isEmpty()) {
398:                 dataFileChannel = openFileChannel(dataFilePath);
399:                 bufferPool.registerRequester(this);
400:             }
401:         } catch (IOException exception) {
402:             if (allReaders.isEmpty()) {
403:                 bufferPool.unregisterRequester(this);
404:                 closeFileChannel();
405:             }
406:             throw exception;
407:         }
408:     }
409: 
410:     private FileChannel openFileChannel(Path path) throws IOException {
411:         return FileChannel.open(path, StandardOpenOption.READ);
412:     }
413: 
414:     @GuardedBy("lock")
415:     private void closeFileChannel() {
416:         assert Thread.holdsLock(lock);
417: 
418:         IOUtils.closeQuietly(dataFileChannel);
419:         dataFileChannel = null;
420:     }
