707:     /**
708:      * Consumed the configured result partitions and verifies that each channel receives the
709:      * expected number of buffers.
710:      */
711:     private static class TestLocalInputChannelConsumer implements Callable<Void> {
712: 
713:         private final SingleInputGate inputGate;
714: 
715:         private final int numberOfInputChannels;
716: 
717:         private final int numberOfExpectedBuffersPerChannel;
718: 
719:         TestLocalInputChannelConsumer(
720:                 int subpartitionIndex,
721:                 int numberOfInputChannels,
722:                 int numberOfExpectedBuffersPerChannel,
723:                 BufferPool bufferPool,
724:                 ResultPartitionManager partitionManager,
725:                 TaskEventDispatcher taskEventDispatcher,
726:                 ResultPartitionID[] consumedPartitionIds)
727:                 throws IOException {
728: 
729:             checkArgument(numberOfInputChannels >= 1);
730:             checkArgument(numberOfExpectedBuffersPerChannel >= 1);
731: 
732:             this.inputGate =
733:                     new SingleInputGateBuilder()
734:                             .setNumberOfChannels(numberOfInputChannels)
735:                             .setBufferPoolFactory(bufferPool)
736:                             .build();
737:             InputChannel[] inputChannels = new InputChannel[numberOfInputChannels];
738: 
739:             // Setup input channels
740:             for (int i = 0; i < numberOfInputChannels; i++) {
741:                 inputChannels[i] =
742:                         InputChannelBuilder.newBuilder()
743:                                 .setChannelIndex(i)
744:                                 .setSubpartitionIndexSet(
745:                                         new ResultSubpartitionIndexSet(subpartitionIndex))
746:                                 .setPartitionManager(partitionManager)
747:                                 .setPartitionId(consumedPartitionIds[i])
748:                                 .setTaskEventPublisher(taskEventDispatcher)
749:                                 .buildLocalChannel(inputGate);
750:             }
751: 
752:             setupInputGate(inputGate, inputChannels);
753: 
754:             this.numberOfInputChannels = numberOfInputChannels;
755:             this.numberOfExpectedBuffersPerChannel = numberOfExpectedBuffersPerChannel;
756:         }
757: 
758:         @Override
759:         public Void call() throws Exception {
760:             // One counter per input channel. Expect the same number of buffers from each channel.
761:             final int[] numberOfBuffersPerChannel = new int[numberOfInputChannels];
762: 
763:             try {
764:                 Optional<BufferOrEvent> boe;
765:                 while ((boe = inputGate.getNext()).isPresent()) {
766:                     if (boe.get().isBuffer()) {
767:                         boe.get().getBuffer().recycleBuffer();
768: 
769:                         // Check that we don't receive too many buffers
770:                         if (++numberOfBuffersPerChannel[
771:                                         boe.get().getChannelInfo().getInputChannelIdx()]
772:                                 > numberOfExpectedBuffersPerChannel) {
773: 
774:                             throw new IllegalStateException(
775:                                     "Received more buffers than expected "
776:                                             + "on channel "
777:                                             + boe.get().getChannelInfo()
778:                                             + ".");
779:                         }
780:                     }
781:                 }
782: 
783:                 // Verify that we received the expected number of buffers on each channel
784:                 for (int i = 0; i < numberOfBuffersPerChannel.length; i++) {
785:                     final int actualNumberOfReceivedBuffers = numberOfBuffersPerChannel[i];
786: 
787:                     if (actualNumberOfReceivedBuffers != numberOfExpectedBuffersPerChannel) {
788:                         throw new IllegalStateException(
789:                                 "Received unexpected number of buffers "
790:                                         + "on channel "
791:                                         + i
792:                                         + " ("
793:                                         + actualNumberOfReceivedBuffers
794:                                         + " instead "
795:                                         + "of "
796:                                         + numberOfExpectedBuffersPerChannel
797:                                         + ").");
798:                     }
799:                 }
800:             } finally {
801:                 inputGate.close();
802:             }
803: 
804:             return null;
805:         }
806:     }
807: }
