32: 
33:     private final float releaseBufferRatio;
34: 
35:     private final float releaseThreshold;
36: 
37:     public HsFullSpillingStrategy(HybridShuffleConfiguration hybridShuffleConfiguration) {
38:         this.numBuffersTriggerSpillingRatio =
39:                 hybridShuffleConfiguration.getFullStrategyNumBuffersTriggerSpillingRatio();
40:         this.releaseThreshold = hybridShuffleConfiguration.getFullStrategyReleaseThreshold();
41:         this.releaseBufferRatio = hybridShuffleConfiguration.getFullStrategyReleaseBufferRatio();
42:     }
43: 
44:     // For the case of buffer finished, whenever the number of unSpillBuffers reaches
45:     // numBuffersTriggerSpillingRatio times currentPoolSize, make a decision based on global
46:     // information. Otherwise, no need to take action.
47:     @Override
48:     public Optional<Decision> onBufferFinished(int numTotalUnSpillBuffers, int currentPoolSize) {
49:         return numTotalUnSpillBuffers < numBuffersTriggerSpillingRatio * currentPoolSize
50:                 ? Optional.of(Decision.NO_ACTION)
51:                 : Optional.empty();
52:     }
53: 
54:     // For the case of buffer consumed, there is no need to take action for HsFullSpillingStrategy.
55:     @Override
56:     public Optional<Decision> onBufferConsumed(BufferIndexAndChannel consumedBuffer) {
57:         return Optional.of(Decision.NO_ACTION);
58:     }
59: 
60:     // When the amount of memory used exceeds the threshold, decide action based on global
61:     // information. Otherwise, no need to take action.
62:     @Override
63:     public Optional<Decision> onMemoryUsageChanged(
64:             int numTotalRequestedBuffers, int currentPoolSize) {
65:         return numTotalRequestedBuffers < currentPoolSize * releaseThreshold
66:                 ? Optional.of(Decision.NO_ACTION)
67:                 : Optional.empty();
68:     }
69: 
70:     @Override
71:     public Decision decideActionWithGlobalInfo(HsSpillingInfoProvider spillingInfoProvider) {
72:         Decision.Builder builder = Decision.builder();
73:         // Save the cost of lock, if pool size is changed between checkSpill and checkRelease, pool
74:         // size checker will handle this inconsistency.
75:         int poolSize = spillingInfoProvider.getPoolSize();
76:         checkSpill(spillingInfoProvider, poolSize, builder);
77:         checkRelease(spillingInfoProvider, poolSize, builder);
78:         return builder.build();
79:     }
80: 
81:     @Override
82:     public Decision onResultPartitionClosed(HsSpillingInfoProvider spillingInfoProvider) {
83:         Decision.Builder builder = Decision.builder();
84:         for (int subpartitionId = 0;
85:                 subpartitionId < spillingInfoProvider.getNumSubpartitions();
86:                 subpartitionId++) {
87:             builder.addBufferToSpill(
88:                             subpartitionId,
89:                             // get all not start spilling buffers.
90:                             spillingInfoProvider.getBuffersInOrder(
91:                                     subpartitionId,
92:                                     SpillStatus.NOT_SPILL,
93:                                     ConsumeStatusWithId.ALL_ANY))
94:                     .addBufferToRelease(
95:                             subpartitionId,
96:                             // get all not released buffers.
97:                             spillingInfoProvider.getBuffersInOrder(
98:                                     subpartitionId, SpillStatus.ALL, ConsumeStatusWithId.ALL_ANY));
99:         }
100:         return builder.build();
101:     }
102: 
103:     private void checkSpill(
104:             HsSpillingInfoProvider spillingInfoProvider, int poolSize, Decision.Builder builder) {
105:         if (spillingInfoProvider.getNumTotalUnSpillBuffers()
106:                 < numBuffersTriggerSpillingRatio * poolSize) {
107:             // In case situation changed since onBufferFinished() returns Optional#empty()
108:             return;
109:         }
110:         // Spill all not spill buffers.
111:         for (int i = 0; i < spillingInfoProvider.getNumSubpartitions(); i++) {
112:             builder.addBufferToSpill(
113:                     i,
114:                     spillingInfoProvider.getBuffersInOrder(
115:                             i, SpillStatus.NOT_SPILL, ConsumeStatusWithId.ALL_ANY));
116:         }
117:     }
