119:     /**
120:      * Release subpartition's spilled buffer from head. Each subpartition fairly retains a fixed
121:      * number of buffers, and all the remaining buffers are released. If this subpartition does not
122:      * have so many qualified buffers, all of them will be retained.
123:      */
124:     private void checkRelease(
125:             HsSpillingInfoProvider spillingInfoProvider, int poolSize, Decision.Builder builder) {
126:         if (spillingInfoProvider.getNumTotalRequestedBuffers() < poolSize * releaseThreshold) {
127:             // In case situation changed since onMemoryUsageChanged() returns Optional#empty()
128:             return;
129:         }
130: 
131:         int releaseNum = (int) (poolSize * releaseBufferRatio);
132:         int numSubpartitions = spillingInfoProvider.getNumSubpartitions();
133:         int expectedSubpartitionReleaseNum = releaseNum / numSubpartitions;
134:         TreeMap<Integer, Deque<BufferIndexAndChannel>> bufferToRelease = new TreeMap<>();
135: 
136:         for (int subpartitionId = 0; subpartitionId < numSubpartitions; subpartitionId++) {
137:             Deque<BufferIndexAndChannel> buffersInOrder =
138:                     spillingInfoProvider.getBuffersInOrder(
139:                             subpartitionId, SpillStatus.SPILL, ConsumeStatusWithId.ALL_ANY);
140:             // if the number of subpartition spilling buffers less than expected release number,
141:             // release all of them.
142:             int subpartitionReleaseNum =
143:                     Math.min(buffersInOrder.size(), expectedSubpartitionReleaseNum);
144:             int subpartitionSurvivedNum = buffersInOrder.size() - subpartitionReleaseNum;
145:             while (subpartitionSurvivedNum-- != 0) {
