147:             }
148:             bufferToRelease.put(subpartitionId, buffersInOrder);
149:         }
150: 
151:         // collect results in order
152:         for (int i = 0; i < numSubpartitions; i++) {
153:             Deque<BufferIndexAndChannel> bufferIndexAndChannels = bufferToRelease.get(i);
154:             if (bufferIndexAndChannels != null && !bufferIndexAndChannels.isEmpty()) {
155:                 builder.addBufferToRelease(i, bufferToRelease.getOrDefault(i, new ArrayDeque<>()));
