112:     public static int computeNetworkBuffersForAnnouncing(
113:             final int numBuffersPerChannel,
114:             final int numFloatingBuffersPerGate,
115:             final Optional<Integer> maxRequiredBuffersPerGate,
116:             final int sortShuffleMinParallelism,
117:             final int sortShuffleMinBuffers,
118:             final Map<IntermediateDataSetID, Integer> inputChannelNums,
119:             final Map<IntermediateDataSetID, Integer> partitionReuseCount,
120:             final Map<IntermediateDataSetID, Integer> subpartitionNums,
121:             final Map<IntermediateDataSetID, ResultPartitionType> inputPartitionTypes,
122:             final Map<IntermediateDataSetID, ResultPartitionType> partitionTypes) {
123: 
124:         int requirementForInputs = 0;
125:         for (IntermediateDataSetID dataSetId : inputChannelNums.keySet()) {
126:             int numChannels = inputChannelNums.get(dataSetId);
127:             ResultPartitionType inputPartitionType = inputPartitionTypes.get(dataSetId);
128:             checkNotNull(inputPartitionType);
129: 
130:             int numSingleGateBuffers =
131:                     getNumBuffersToAnnounceForInputGate(
132:                             inputPartitionType,
133:                             numBuffersPerChannel,
134:                             numFloatingBuffersPerGate,
135:                             maxRequiredBuffersPerGate,
136:                             numChannels);
137:             checkState(partitionReuseCount.containsKey(dataSetId));
138:             requirementForInputs += numSingleGateBuffers * partitionReuseCount.get(dataSetId);
139:         }
140: 
141:         int requirementForOutputs = 0;
142:         for (IntermediateDataSetID dataSetId : subpartitionNums.keySet()) {
143:             int numSubs = subpartitionNums.get(dataSetId);
144:             ResultPartitionType partitionType = partitionTypes.get(dataSetId);
145:             checkNotNull(partitionType);
146: 
147:             requirementForOutputs +=
148:                     getNumBuffersToAnnounceForResultPartition(
149:                             partitionType,
150:                             numBuffersPerChannel,
151:                             numFloatingBuffersPerGate,
152:                             sortShuffleMinParallelism,
153:                             sortShuffleMinBuffers,
154:                             numSubs);
155:         }
156: 
157:         return requirementForInputs + requirementForOutputs;
158:     }
