422:         DataStream<Long> createSourcePipeline(
423:                 StreamExecutionEnvironment env,
424:                 int minCheckpoints,
425:                 boolean slotSharing,
426:                 int expectedRestarts,
427:                 int parallelism,
428:                 int inputIndex,
429:                 long sourceSleepMs,
