436:                                     env.getCheckpointInterval(),
437:                                     sourceSleepMs),
438:                             noWatermarks(),
439:                             "source" + inputIndex)
440:                     .uid("source" + inputIndex)
441:                     .slotSharingGroup(slotSharing ? "default" : ("source" + inputIndex))
442:                     .filter(sourceFilter)
443:                     .name("input-filter" + inputIndex)
444:                     .uid("input-filter" + inputIndex)
445:                     .slotSharingGroup(slotSharing ? "default" : ("source" + inputIndex))
446:                     .map(new InputCountFunction())
447:                     .name("input-counter" + inputIndex)
448:                     .uid("input-counter" + inputIndex)
449:                     .slotSharingGroup(slotSharing ? "default" : ("source" + inputIndex))
450:                     .global()
451:                     .map(i -> checkHeader(i))
452:                     .name("global" + inputIndex)
453:                     .uid("global" + inputIndex)
454:                     .slotSharingGroup(slotSharing ? "default" : ("global" + inputIndex))
455:                     .rebalance()
456:                     .map(i -> checkHeader(i))
457:                     .setParallelism(parallelism + 1)
458:                     .name("rebalance" + inputIndex)
459:                     .uid("rebalance" + inputIndex)
460:                     .slotSharingGroup(slotSharing ? "default" : ("rebalance" + inputIndex))
461:                     .shuffle()
462:                     .map(i -> checkHeader(i))
463:                     .name("upscale" + inputIndex)
464:                     .uid("upscale" + inputIndex)
465:                     .setParallelism(2 * parallelism)
466:                     .slotSharingGroup(slotSharing ? "default" : ("upscale" + inputIndex))
467:                     .shuffle()
468:                     .map(i -> checkHeader(i))
469:                     .name("downscale" + inputIndex)
470:                     .uid("downscale" + inputIndex)
471:                     .setParallelism(parallelism + 1)
472:                     .slotSharingGroup(slotSharing ? "default" : ("downscale" + inputIndex))
473:                     .keyBy(i -> withoutHeader(i) % NUM_GROUPS)
474:                     .map(new StatefulKeyedMap())
475:                     .name("keyby" + inputIndex)
476:                     .uid("keyby" + inputIndex)
477:                     .slotSharingGroup(slotSharing ? "default" : ("keyby" + inputIndex))
478:                     .rescale()
479:                     .map(i -> checkHeader(i))
480:                     .name("rescale" + inputIndex)
481:                     .uid("rescale" + inputIndex)
482:                     .setParallelism(Math.max(parallelism + 1, parallelism * 3 / 2))
483:                     .slotSharingGroup(slotSharing ? "default" : ("rescale" + inputIndex));
484:         }
