308:     private static DataStreamSink<Long> addFailingPipeline(
309:             long minCheckpoints, boolean slotSharing, DataStream<Long> combinedSource) {
310:         return combinedSource
311:                 // shifts records from one partition to another evenly to retain order
312:                 .partitionCustom(new ShiftingPartitioner(), l -> l)
313:                 .map(
314:                         new FailingMapper<>(
315:                                 state ->
316:                                         state.completedCheckpoints >= minCheckpoints / 4
317:                                                         && state.runNumber == 0
318:                                                 || state.completedCheckpoints
319:                                                                 >= minCheckpoints * 3 / 4
320:                                                         && state.runNumber == 2,
321:                                 state ->
322:                                         state.completedCheckpoints >= minCheckpoints / 2
323:                                                 && state.runNumber == 1,
324:                                 state -> state.runNumber == 3,
325:                                 state -> state.runNumber == 4))
326:                 .name("failing-map")
327:                 .uid("failing-map")
328:                 .slotSharingGroup(slotSharing ? "default" : "failing-map")
329:                 .partitionCustom(new ChunkDistributingPartitioner(), l -> l)
330:                 .addSink(
331:                         new StrictOrderVerifyingSink(
332:                                 minCheckpoints,
333:                                 combinedSource.getExecutionEnvironment().getCheckpointInterval()))
334:                 .name("sink")
335:                 .uid("sink")
336:                 .slotSharingGroup(slotSharing ? "default" : "sink");
337:     }
