339:     /**
340:      * A sink that checks if the members arrive in the expected order without any missing values.
341:      */
342:     protected static class StrictOrderVerifyingSink
343:             extends VerifyingSinkBase<StrictOrderVerifyingSink.State> {
344:         private boolean firstOutOfOrder = true;
345:         private boolean firstDuplicate = true;
346:         private boolean firstLostValue = true;
347: 
348:         protected StrictOrderVerifyingSink(long minCheckpoints, long checkpointingInterval) {
349:             super(minCheckpoints, checkpointingInterval);
350:         }
351: 
352:         @Override
353:         protected State createState() {
354:             return new State(getRuntimeContext().getTaskInfo().getNumberOfParallelSubtasks());
355:         }
356: 
357:         @Override
358:         public void initializeState(FunctionInitializationContext context) throws Exception {
359:             super.initializeState(context);
360:         }
361: 
362:         @Override
363:         public void invoke(Long value, Context context) throws Exception {
364:             value = withoutHeader(value);
365:             int parallelism = state.lastRecordInPartitions.length;
366:             int partition = (int) (value % parallelism);
367:             long lastRecord = state.lastRecordInPartitions[partition];
368:             if (value < lastRecord) {
369:                 state.numOutOfOrderness++;
370:                 if (firstOutOfOrder) {
371:                     LOG.info(
372:                             "Out of order records current={} and last={} @ {} subtask ({} attempt)",
373:                             value,
374:                             lastRecord,
375:                             getRuntimeContext().getTaskInfo().getIndexOfThisSubtask(),
376:                             getRuntimeContext().getTaskInfo().getAttemptNumber());
377:                     firstOutOfOrder = false;
378:                 }
379:             } else if (value == lastRecord) {
380:                 state.numDuplicates++;
381:                 if (firstDuplicate) {
382:                     LOG.info(
383:                             "Duplicate record {} @ {} subtask ({} attempt)",
384:                             value,
385:                             getRuntimeContext().getTaskInfo().getIndexOfThisSubtask(),
386:                             getRuntimeContext().getTaskInfo().getAttemptNumber());
387:                     firstDuplicate = false;
388:                 }
389:             } else if (lastRecord != -1) {
390:                 long expectedValue = lastRecord + parallelism * parallelism;
391:                 if (value != expectedValue) {
392:                     state.numLostValues++;
393:                     if (firstLostValue) {
394:                         LOG.info(
395:                                 "Lost records current={}, expected={}, and last={} @ {} subtask ({} attempt)",
396:                                 value,
397:                                 expectedValue,
398:                                 lastRecord,
399:                                 getRuntimeContext().getTaskInfo().getIndexOfThisSubtask(),
400:                                 getRuntimeContext().getTaskInfo().getAttemptNumber());
401:                         firstLostValue = false;
402:                     }
403:                 }
404:             }
405:             state.lastRecordInPartitions[partition] = value;
406:             state.numOutput++;
407: 
408:             induceBackpressure();
409:         }
410: 
411:         static class State extends VerifyingSinkStateBase {
412:             private final long[] lastRecordInPartitions;
413: 
414:             private State(int numberOfParallelSubtasks) {
415:                 lastRecordInPartitions = new long[numberOfParallelSubtasks];
416:                 Arrays.fill(lastRecordInPartitions, -1);
417:             }
418:         }
419:     }
