421:     private static class KeyedIdentityFunction extends KeyedProcessFunction<Long, Long, Long> {
422:         ValueState<Long> state;
423: 
424:         @Override
425:         public void open(OpenContext openContext) throws Exception {
426:             super.open(openContext);
427:             state =
428:                     getRuntimeContext()
429:                             .getState(
430:                                     new ValueStateDescriptor<>(
431:                                             "keyedState", BasicTypeInfo.LONG_TYPE_INFO));
432:         }
433: 
434:         @Override
435:         public void processElement(Long value, Context ctx, Collector<Long> out) {
436:             checkHeader(value);
437:             out.collect(value);
438:         }
439:     }
