441:     private static class SourceAwareMinEmittingFunction
442:             extends RichFlatMapFunction<Tuple2<Integer, Long>, Long>
443:             implements CheckpointedFunction {
444:         private final int numSources;
445:         private State state;
446: 
447:         private ListState<State> stateList;
448: 
449:         public SourceAwareMinEmittingFunction(int numSources) {
450:             this.numSources = numSources;
451:         }
452: 
453:         @Override
454:         public void flatMap(Tuple2<Integer, Long> sourceValue, Collector<Long> out)
455:                 throws Exception {
456:             int source = sourceValue.f0;
457:             long value = withoutHeader(sourceValue.f1);
458:             int partition =
459:                     (int) (value % getRuntimeContext().getTaskInfo().getNumberOfParallelSubtasks());
460:             state.lastValues[source][partition] = value;
461:             for (int index = 0; index < numSources; index++) {
462:                 if (state.lastValues[index][partition] < value) {
463:                     return;
464:                 }
465:             }
466:             out.collect(sourceValue.f1);
467:         }
468: 
469:         @Override
470:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
471:             stateList.update(Collections.singletonList(state));
472:         }
473: 
474:         @Override
475:         public void initializeState(FunctionInitializationContext context) throws Exception {
476:             stateList =
477:                     context.getOperatorStateStore()
478:                             .getListState(new ListStateDescriptor<>("state", State.class));
479:             state =
480:                     getOnlyElement(
481:                             stateList.get(),
482:                             new State(
483:                                     numSources,
484:                                     getRuntimeContext()
485:                                             .getTaskInfo()
486:                                             .getNumberOfParallelSubtasks()));
487:         }
488: 
489:         private static class State {
490:             private final long[][] lastValues;
491: 
492:             public State(int numSources, int numberOfParallelSubtasks) {
493:                 this.lastValues = new long[numSources][numberOfParallelSubtasks];
494:                 for (long[] lastValue : lastValues) {
495:                     Arrays.fill(lastValue, Long.MIN_VALUE);
496:                 }
497:             }
498:         }
499:     }
500: }
