459:                     (int) (value % getRuntimeContext().getTaskInfo().getNumberOfParallelSubtasks());
460:             state.lastValues[source][partition] = value;
461:             for (int index = 0; index < numSources; index++) {
462:                 if (state.lastValues[index][partition] < value) {
463:                     return;
464:                 }
465:             }
466:             out.collect(sourceValue.f1);
467:         }
468: 
469:         @Override
470:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
471:             stateList.update(Collections.singletonList(state));
472:         }
473: 
