696: 
697:         SingleInputGate gate =
698:                 createSingleInputGate(partitionIds, ResultPartitionType.PIPELINED, netEnv);
699:         gate.setChannelStateWriter(ChannelStateWriter.NO_OP);
700: 
701:         gate.finishReadRecoveredState();
702:         while (!gate.getStateConsumedFuture().isDone()) {
703:             gate.pollNext();
704:         }
705:         gate.convertRecoveredInputChannels();
706: 
707:         try (Closer closer = Closer.create()) {
708:             closer.register(netEnv::close);
709:             closer.register(gate::close);
