59:     private final int[] auxGrouping;
60:     private final AggregateCall[] aggCalls;
61:     private final LogicalWindow window;
62:     private final int inputTimeFieldIndex;
63:     private final boolean inputTimeIsDate;
64:     private final NamedWindowProperty[] namedWindowProperties;
65:     private final RowType aggInputRowType;
66:     private final boolean enableAssignPane;
67:     private final boolean isMerge;
68:     private final boolean isFinal;
69: 
70:     public BatchExecSortWindowAggregate(
71:             ReadableConfig tableConfig,
72:             int[] grouping,
73:             int[] auxGrouping,
74:             AggregateCall[] aggCalls,
75:             LogicalWindow window,
76:             int inputTimeFieldIndex,
77:             boolean inputTimeIsDate,
78:             NamedWindowProperty[] namedWindowProperties,
79:             RowType aggInputRowType,
80:             boolean enableAssignPane,
81:             boolean isMerge,
82:             boolean isFinal,
83:             InputProperty inputProperty,
84:             RowType outputType,
85:             String description) {
86:         super(
87:                 ExecNodeContext.newNodeId(),
88:                 ExecNodeContext.newContext(BatchExecSortWindowAggregate.class),
89:                 ExecNodeContext.newPersistedConfig(BatchExecSortWindowAggregate.class, tableConfig),
90:                 Collections.singletonList(inputProperty),
91:                 outputType,
92:                 description);
93:         this.grouping = grouping;
94:         this.auxGrouping = auxGrouping;
95:         this.aggCalls = aggCalls;
96:         this.window = window;
97:         this.inputTimeFieldIndex = inputTimeFieldIndex;
98:         this.inputTimeIsDate = inputTimeIsDate;
99:         this.namedWindowProperties = namedWindowProperties;
100:         this.aggInputRowType = aggInputRowType;
101:         this.enableAssignPane = enableAssignPane;
102:         this.isMerge = isMerge;
103:         this.isFinal = isFinal;
104:     }
105: 
106:     @SuppressWarnings("unchecked")
107:     @Override
108:     protected Transformation<RowData> translateToPlanInternal(
109:             PlannerBase planner, ExecNodeConfig config) {
110:         final ExecEdge inputEdge = getInputEdges().get(0);
111:         final Transformation<RowData> inputTransform =
112:                 (Transformation<RowData>) inputEdge.translateToPlan(planner);
113: 
114:         final AggregateInfoList aggInfos =
115:                 AggregateUtil.transformToBatchAggregateInfoList(
116:                         planner.getTypeFactory(),
117:                         aggInputRowType,
118:                         JavaScalaConversionUtil.toScala(Arrays.asList(aggCalls)),
119:                         null, // aggCallNeedRetractions
120:                         null); // orderKeyIndexes
121: 
122:         final int groupBufferLimitSize =
123:                 config.get(ExecutionConfigOptions.TABLE_EXEC_WINDOW_AGG_BUFFER_SIZE_LIMIT);
124: 
125:         final Tuple2<Long, Long> windowSizeAndSlideSize = WindowCodeGenerator.getWindowDef(window);
126:         final SortWindowCodeGenerator windowCodeGenerator =
127:                 new SortWindowCodeGenerator(
128:                         new CodeGeneratorContext(
129:                                 config, planner.getFlinkContext().getClassLoader()),
130:                         planner.createRelBuilder(),
131:                         window,
132:                         inputTimeFieldIndex,
133:                         inputTimeIsDate,
134:                         JavaScalaConversionUtil.toScala(Arrays.asList(namedWindowProperties)),
135:                         aggInfos,
136:                         (RowType) inputEdge.getOutputType(),
137:                         (RowType) getOutputType(),
138:                         groupBufferLimitSize,
139:                         0L, // windowStart
140:                         windowSizeAndSlideSize.f0,
141:                         windowSizeAndSlideSize.f1,
142:                         grouping,
143:                         auxGrouping,
144:                         enableAssignPane,
145:                         isMerge,
146:                         isFinal);
