155:         return ExecNodeUtil.createOneInputTransformation(
156:                 inputTransform,
157:                 createTransformationName(config),
158:                 createTransformationDescription(config),
159:                 new CodeGenOperatorFactory<>(generatedOperator),
160:                 InternalTypeInfo.of(getOutputType()),
161:                 inputTransform.getParallelism(),
162:                 false);
