308:             super(firstMemSegment, firstMemSegment.getInt(0), HEADER_LENGTH);
309: 
310:             this.emptyBufferTarget = emptyBufferTarget;
311:             this.fullBufferSource = fullBufferSource;
312: 
313:             this.spilledBufferSource = spilledBufferSource;
