330:                 spilledBufferSource.readBlock(current);
331:             } else {
332:                 emptyBufferTarget.add(current);
333:             }
334: 
335:             // get the next buffer either from the return queue, or the full buffer source
336:             if (spilledBuffersRemaining > 0) {
337:                 spilledBuffersRemaining--;
338:                 try {
339:                     return spilledBufferSource.getReturnQueue().take();
340:                 } catch (InterruptedException e) {
341:                     throw new RuntimeException(
