363:         private boolean disposeIfDone() {
364:             if (fullBufferSource.isEmpty() && spilledBuffersRemaining == 0) {
365:                 if (getCurrentSegment() == null
366:                         || getCurrentPositionInSegment() >= getCurrentSegmentLimit()) {
367:                     if (getCurrentSegment() != null) {
368:                         emptyBufferTarget.add(getCurrentSegment());
369:                         clear();
370:                     }
371: 
372:                     if (spilledBufferSource != null) {
373:                         try {
374:                             spilledBufferSource.closeAndDelete();
375:                         } catch (Throwable t) {
376:                             // do nothing
377:                         }
378:                     }
379:                     return true;
380:                 }
381:             }
382:             return false;
383:         }
