392: 
393:             // add all remaining memory
394:             freeMemTarget.addAll(fullBufferSource);
395: 
396:             // add the segments with the requests issued but not returned
397:             for (int i = spilledBuffersRemaining - requestsRemaining; i > 0; --i) {
398:                 freeMemTarget.add(emptyBufferTarget.take());
399:             }
400: 
401:             if (spilledBufferSource != null) {
402:                 try {
403:                     spilledBufferSource.closeAndDelete();
404:                 } catch (Throwable t) {
405:                     // do nothing
406:                 }
407:             }
408:         }
409:     }
