212:     private void writeRecord(ByteBuffer source) {
213:         while (source.hasRemaining()) {
214:             MemorySegment segment = segments.get(writeSegmentIndex);
215:             int toCopy = Math.min(bufferSize - writeSegmentOffset, source.remaining());
216:             segment.put(writeSegmentOffset, source, toCopy);
