268:     private void updateWriteSegmentIndexAndOffset(int numBytes) {
269:         writeSegmentOffset += numBytes;
270: 
271:         // using the next available free buffer if the current is full
272:         if (writeSegmentOffset == bufferSize) {
273:             ++writeSegmentIndex;
274:             writeSegmentOffset = 0;
275:         }
