278:     protected int copyRecordOrEvent(
279:             MemorySegment targetSegment,
280:             int targetSegmentOffset,
281:             int sourceSegmentIndex,
282:             int sourceSegmentOffset,
283:             int recordLength) {
284:         if (recordRemainingBytes > 0) {
285:             // skip the data already read if there is remaining partial record after the previous
286:             // copy
287:             long position = (long) sourceSegmentOffset + (recordLength - recordRemainingBytes);
288:             sourceSegmentIndex += (position / bufferSize);
289:             sourceSegmentOffset = (int) (position % bufferSize);
290:         } else {
291:             recordRemainingBytes = recordLength;
292:         }
293: 
294:         int targetSegmentSize = targetSegment.size();
295:         int numBytesToCopy =
296:                 Math.min(targetSegmentSize - targetSegmentOffset, recordRemainingBytes);
297:         do {
298:             // move to next data buffer if all data of the current buffer has been copied
299:             if (sourceSegmentOffset == bufferSize) {
300:                 ++sourceSegmentIndex;
301:                 sourceSegmentOffset = 0;
302:             }
303: 
304:             int sourceRemainingBytes =
305:                     Math.min(bufferSize - sourceSegmentOffset, recordRemainingBytes);
306:             int numBytes = Math.min(targetSegmentSize - targetSegmentOffset, sourceRemainingBytes);
307:             MemorySegment sourceSegment = segments.get(sourceSegmentIndex);
308:             sourceSegment.copyTo(sourceSegmentOffset, targetSegment, targetSegmentOffset, numBytes);
309: 
310:             recordRemainingBytes -= numBytes;
311:             targetSegmentOffset += numBytes;
312:             sourceSegmentOffset += numBytes;
313:         } while ((recordRemainingBytes > 0 && targetSegmentOffset < targetSegmentSize));
314: 
315:         return numBytesToCopy;
316:     }
