337:     public long numTotalRecords() {
338:         return numTotalRecords;
339:     }
340: 
341:     @Override
342:     public long numTotalBytes() {
343:         return numTotalBytes;
344:     }
345: 
346:     @Override
347:     public boolean hasRemaining() {
348:         return numTotalBytesRead < numTotalBytes;
349:     }
