351:     @Override
352:     public void finish() {
353:         checkState(!isFinished, "DataBuffer is already finished.");
354: 
355:         isFinished = true;
356: 
357:         // prepare for reading
358:         updateReadSubpartitionAndIndexEntryAddress();
359:     }
360: 
361:     @Override
362:     public boolean isFinished() {
363:         return isFinished;
364:     }
365: 
366:     @Override
367:     public void release() {
368:         if (isReleased) {
369:             return;
370:         }
371:         isReleased = true;
372: 
373:         for (MemorySegment segment : segments) {
374:             bufferRecycler.recycle(segment);
375:         }
376:         segments.clear();
377:     }
