122:         SingleInputGate gate = buildRemoteGate();
123:         InputChannel[] channels = new InputChannel[numChannels];
124:         for (int i = 0; i < numChannels; i++) {
125:             if (testChannelIdSet.contains(i)) {
126:                 channels[i] = new TestInputChannel(gate, i, false, true);
127:             } else {
128:                 channels[i] = gate.getChannel(i);
129:             }
130:         }
131:         gate.setInputChannels(channels);
132: 
133:         return gate;
