912:     private static class CountBufferListener implements BufferListener {
913: 
914:         private final AtomicInteger times = new AtomicInteger(0);
915: 
916:         @Override
917:         public boolean notifyBufferAvailable(Buffer buffer) {
918:             times.incrementAndGet();
919:             buffer.recycleBuffer();
920:             return true;
921:         }
922: 
923:         @Override
924:         public void notifyBufferDestroyed() {}
925: 
926:         int getCount() {
927:             return times.get();
928:         }
929:     }
