931:     private static class BufferRequesterTask implements Callable<Boolean> {
932: 
933:         private final BufferProvider bufferProvider;
934: 
935:         private final int numBuffersToRequest;
936: 
937:         private BufferRequesterTask(BufferProvider bufferProvider, int numBuffersToRequest) {
938:             this.bufferProvider = bufferProvider;
939:             this.numBuffersToRequest = numBuffersToRequest;
940:         }
941: 
942:         @Override
943:         public Boolean call() {
944:             try {
945:                 for (int i = 0; i < numBuffersToRequest; i++) {
946:                     Buffer buffer = checkNotNull(bufferProvider.requestBuffer());
947:                     buffer.recycleBuffer();
948:                 }
949:             } catch (Throwable t) {
950:                 return false;
951:             }
952: 
953:             return true;
954:         }
955:     }
