145:     @Test
146:     @Timeout(value = 10) // timeout can indicate a potential deadlock
147:     void testReserveSegmentsAndCancel() throws Exception {
148:         int totalSegments = 4;
149:         int segmentsToReserve = 2;
150: 
151:         NetworkBufferPool globalPool = new NetworkBufferPool(totalSegments, memorySegmentSize);
152:         BufferPool localPool1 =
153:                 globalPool.createBufferPool(segmentsToReserve, segmentsToReserve, totalSegments);
154:         List<MemorySegment> segments = new ArrayList<>();
155: 
156:         try {
157:             for (int i = 0; i < totalSegments; ++i) {
158:                 segments.add(localPool1.requestMemorySegmentBlocking());
159:             }
160: 
161:             BufferPool localPool2 =
162:                     globalPool.createBufferPool(
163:                             segmentsToReserve, segmentsToReserve, totalSegments);
164:             // the segment reserve thread will be blocked for no buffer is available
165:             Thread reserveThread =
166:                     new Thread(
167:                             () -> {
168:                                 try {
169:                                     localPool2.reserveSegments(segmentsToReserve);
170:                                 } catch (Throwable ignored) {
171:                                 }
172:                             });
173:             reserveThread.start();
174:             Thread.sleep(100); // wait to be blocked
175: 
176:             // the cancel thread can be blocked when redistributing buffers
177:             Thread cancelThread =
178:                     new Thread(
179:                             () -> {
180:                                 localPool1.lazyDestroy();
181:                                 localPool2.lazyDestroy();
182:                             });
183:             cancelThread.start();
184: 
185:             // it is expected that the segment reserve thread can be cancelled successfully
186:             Thread interruptThread =
187:                     new Thread(
188:                             () -> {
189:                                 try {
190:                                     do {
191:                                         reserveThread.interrupt();
192:                                         Thread.sleep(100);
193:                                     } while (reserveThread.isAlive() || cancelThread.isAlive());
194:                                 } catch (Throwable ignored) {
195:                                 }
196:                             });
197:             interruptThread.start();
198: 
199:             interruptThread.join();
200:         } finally {
201:             segments.forEach(localPool1::recycle);
202:             localPool1.lazyDestroy();
203:             assertThat(globalPool.getNumberOfUsedMemorySegments()).isZero();
204:             globalPool.destroy();
205:         }
206:     }
