382:     void testIncreasePoolSizeInternal(
383:             int maxMemorySegments,
384:             int requiredMemorySegments,
385:             int smallPoolSize,
386:             int largePoolSize,
387:             int maxOverdraftBuffers,
388:             int numOverdraftBuffersAfterIncreasePoolSize,
389:             int numAvailableBuffersAfterIncreasePoolSize,
390:             boolean isAvailableAfterIncreasePoolSize)
391:             throws Exception {
392:         LocalBufferPool bufferPool =
393:                 new LocalBufferPool(
394:                         networkBufferPool,
395:                         requiredMemorySegments,
396:                         requiredMemorySegments,
397:                         maxMemorySegments,
398:                         0,
399:                         Integer.MAX_VALUE,
400:                         maxOverdraftBuffers);
