411:         assertThat(bufferPool.isAvailable()).isFalse();
412: 
413:         // request all overdraft buffers.
414:         for (int i = 0; i < maxOverdraftBuffers; i++) {
415:             buffers.add(bufferPool.requestMemorySegmentBlocking());
