423:         assertThat(bufferPool.getNumBuffers()).isEqualTo(largePoolSize);
424:         assertThat(bufferPool.getNumberOfAvailableMemorySegments())
425:                 .isEqualTo(numAvailableBuffersAfterIncreasePoolSize);
426:         assertThat(getNumberRequestedOverdraftBuffers(bufferPool))
427:                 .isEqualTo(numOverdraftBuffersAfterIncreasePoolSize);
428:         assertThat(bufferPool.isAvailable()).isEqualTo(isAvailableAfterIncreasePoolSize);
429: 
430:         for (MemorySegment buffer : buffers) {
431:             bufferPool.recycle(buffer);
432:         }
433:         bufferPool.lazyDestroy();
434:     }
