810:     private void useAllOverdraftBuffersAndCheckIsLegal(
811:             int poolSize,
812:             int totalFloatingBuffers,
813:             int maxOverdraftBuffers,
814:             int numberOfChannels,
815:             int availableChannels)
816:             throws Exception {
817:         checkArgument(totalFloatingBuffers > poolSize / numberOfChannels);
818:         checkArgument(numberOfChannels >= availableChannels);
819:         LocalBufferPool bufferPool =
820:                 new LocalBufferPool(
821:                         networkBufferPool,
822:                         1,
823:                         1,
824:                         Integer.MAX_VALUE,
825:                         numberOfChannels,
826:                         totalFloatingBuffers,
827:                         maxOverdraftBuffers);
828:         bufferPool.setNumBuffers(poolSize);
829: 
830:         // Request all buffers inside the buffer pool
831:         Map<Integer, AutoCloseableRegistry> closeableRegistryMap = new HashMap<>();
832:         for (int i = 0; i < poolSize; i++) {
833:             int targetChannel = i % availableChannels;
834:             BufferBuilder bufferBuilder = bufferPool.requestBufferBuilder(targetChannel);
835:             assertThat(bufferBuilder).isNotNull();
836:             closeableRegistryMap
837:                     .computeIfAbsent(targetChannel, channel -> new AutoCloseableRegistry())
838:                     .registerCloseable(bufferBuilder);
839:             boolean isAvailable =
840:                     (i + 1 < poolSize) && i < availableChannels * (totalFloatingBuffers - 1);
841:             assertRequestedBufferAndIsAvailable(bufferPool, 0, i + 1, isAvailable);
842:         }
843: 
844:         // request overdraft buffer
845:         AutoCloseableRegistry overdraftCloseableRegistry = new AutoCloseableRegistry();
846:         for (int i = 0; i < maxOverdraftBuffers; i++) {
847:             int targetChannel = i % availableChannels;
848:             BufferBuilder bufferBuilder = bufferPool.requestBufferBuilder(targetChannel);
849:             assertThat(bufferBuilder).isNotNull();
850:             overdraftCloseableRegistry.registerCloseable(bufferBuilder);
851:             int numberOfRequestedOverdraftBuffer = i + 1;
852:             assertRequestedBufferAndIsAvailable(
853:                     bufferPool,
854:                     numberOfRequestedOverdraftBuffer,
855:                     poolSize + numberOfRequestedOverdraftBuffer,
856:                     false);
857:         }
858: 
859:         for (int i = 0; i < numberOfChannels; i++) {
860:             assertThat(bufferPool.requestBufferBuilder(i)).isNull();
861:             assertRequestedBufferAndIsAvailable(
862:                     bufferPool, maxOverdraftBuffers, poolSize + maxOverdraftBuffers, false);
863:         }
864: 
865:         // release all bufferBuilder
866:         overdraftCloseableRegistry.close();
867:         assertRequestedBufferAndIsAvailable(bufferPool, 0, poolSize, false);
868:         int numberOfRequestedBuffer = poolSize;
869:         for (AutoCloseableRegistry closeableRegistry : closeableRegistryMap.values()) {
870:             numberOfRequestedBuffer =
871:                     numberOfRequestedBuffer - closeableRegistry.getNumberOfRegisteredCloseables();
872:             closeableRegistry.close();
873:             assertRequestedBufferAndIsAvailable(bufferPool, 0, numberOfRequestedBuffer, true);
874:         }
875:         bufferPool.lazyDestroy();
876:     }
