878:     private static void assertRequestedBufferAndIsAvailable(
879:             LocalBufferPool bufferPool,
880:             int numberOfRequestedOverdraftBuffer,
881:             int numberOfRequestedBuffer,
882:             boolean isAvailable) {
883:         if (numberOfRequestedOverdraftBuffer > 0) {
884:             checkArgument(!isAvailable);
885:         }
886:         assertThat(getNumberRequestedOverdraftBuffers(bufferPool))
887:                 .isEqualTo(numberOfRequestedOverdraftBuffer);
888: 
889:         assertThat(bufferPool.bestEffortGetNumOfUsedBuffers()).isEqualTo(numberOfRequestedBuffer);
890:         assertThat(bufferPool.getAvailableFuture().isDone()).isEqualTo(isAvailable);
891:     }
