268:     @Override
269:     public void reserveSegments(int numberOfSegmentsToReserve) throws IOException {
270:         checkArgument(
271:                 numberOfSegmentsToReserve <= minNumberOfMemorySegments,
272:                 "Can not reserve more segments than number of minimum segments.");
273: 
274:         CompletableFuture<?> toNotify = null;
275:         synchronized (availableMemorySegments) {
276:             checkDestroyed();
277: 
278:             if (numberOfRequestedMemorySegments < numberOfSegmentsToReserve) {
279:                 availableMemorySegments.addAll(
280:                         networkBufferPool.requestPooledMemorySegmentsBlocking(
281:                                 numberOfSegmentsToReserve - numberOfRequestedMemorySegments));
282:                 toNotify = availabilityHelper.getUnavailableToResetAvailable();
283:             }
284:         }
285:         mayNotifyAvailable(toNotify);
286:     }
