42: /**
43:  * The sort-based implementation of the {@link BufferAccumulator}. The {@link BufferAccumulator}
44:  * receives the records from {@link TieredStorageProducerClient} and the records will accumulate and
45:  * transform to finished buffers. The accumulated buffers will be transferred to the corresponding
46:  * tier dynamically.
47:  *
48:  * <p>The {@link SortBufferAccumulator} can help use less buffers to accumulate data, which
49:  * decouples the buffer usage with the number of parallelism. The number of buffers used by the
50:  * {@link SortBufferAccumulator} will be numBuffers at most. Once the {@link DataBuffer} is full, or
51:  * switching from broadcast to non-broadcast(or vice versa), the buffer in the sort buffer will be
52:  * flushed to the tiers.
53:  *
54:  * <p>Note that this class need not be thread-safe, because it should only be accessed from the main
55:  * thread.
56:  */
57: public class SortBufferAccumulator implements BufferAccumulator {
58: 
59:     /** The number of the subpartitions. */
60:     private final int numSubpartitions;
61: 
62:     /** The total number of the buffers used by the {@link SortBufferAccumulator}. */
63:     private final int totalFloatingBuffers;
64: 
65:     /** The byte size of one single buffer. */
66:     private final int bufferSizeBytes;
67: 
68:     /** The empty buffers without storing data. */
69:     @GuardedBy("lock")
70:     private final LinkedList<MemorySegment> freeSegments = new LinkedList<>();
71: 
72:     /** The memory manager of the tiered storage. */
73:     private final TieredStorageMemoryManager memoryManager;
74: 
75:     private final boolean isPartialRecordAllowed;
76: 
77:     /**
78:      * The {@link DataBuffer} is utilized to accumulate the incoming records. Whenever there is a
79:      * transition from broadcast to non-broadcast (or vice versa), the buffer is flushed to ensure
80:      * data integrity. Note that this can be null before using it to store records, and this {@link
81:      * DataBuffer} will be released once flushed.
82:      */
83:     @GuardedBy("lock")
84:     @Nullable
85:     private TieredStorageSortBuffer currentDataBuffer;
86: 
87:     /**
88:      * The buffer recycler. Note that this can be null before requesting buffers from the memory
89:      * manager.
90:      */
91:     @Nullable private BufferRecycler bufferRecycler;
92: 
93:     /**
94:      * The {@link SortBufferAccumulator}'s accumulated buffer flusher is not prepared during
95:      * construction, requiring the field to be initialized during setup. Therefore, it is necessary
96:      * to verify whether this field is null before using it.
97:      */
98:     @Nullable
99:     private TriConsumer<TieredStorageSubpartitionId, Buffer, Integer> accumulatedBufferFlusher;
100: 
101:     /** Whether the current {@link DataBuffer} is a broadcast sort buffer. */
102:     private boolean isBroadcastDataBuffer;
103: 
104:     @GuardedBy("lock")
105:     private boolean isDataBufferReleased;
106: 
107:     private final Object lock = new Object();
108: 
109:     public SortBufferAccumulator(
110:             int numSubpartitions,
111:             int numBuffers,
112:             int bufferSizeBytes,
113:             TieredStorageMemoryManager memoryManager,
114:             boolean isPartialRecordAllowed) {
115:         this.numSubpartitions = numSubpartitions;
116:         this.bufferSizeBytes = bufferSizeBytes;
117:         this.totalFloatingBuffers = numBuffers;
118:         this.memoryManager = memoryManager;
119:         this.isPartialRecordAllowed = isPartialRecordAllowed;
120:     }
121: 
122:     @Override
123:     public void setup(TriConsumer<TieredStorageSubpartitionId, Buffer, Integer> bufferFlusher) {
124:         this.accumulatedBufferFlusher = bufferFlusher;
125:     }
126: 
127:     @Override
128:     public void receive(
129:             ByteBuffer record,
130:             TieredStorageSubpartitionId subpartitionId,
131:             Buffer.DataType dataType,
132:             boolean isBroadcast)
133:             throws IOException {
134:         int targetSubpartition = subpartitionId.getSubpartitionId();
135:         synchronized (lock) {
136:             switchCurrentDataBufferIfNeeded(isBroadcast);
137:             if (!checkNotNull(currentDataBuffer).append(record, targetSubpartition, dataType)) {
138:                 return;
139:             }
140: 
141:             // The sort buffer is empty, but we failed to write the record into it, which indicates
142:             // the record is larger than the sort buffer can hold. So the record is written into
143:             // multiple buffers directly.
144:             if (!currentDataBuffer.hasRemaining()) {
145:                 isDataBufferReleased = true;
146:                 currentDataBuffer.release();
147:                 writeLargeRecord(record, targetSubpartition, dataType);
148:                 return;
149:             }
150:             flushDataBuffer();
151:         }
152: 
153:         checkState(record.hasRemaining(), "Empty record.");
154:         receive(record, subpartitionId, dataType, isBroadcast);
155:     }
156: 
157:     @Override
158:     public void close() {
159:         synchronized (lock) {
160:             flushCurrentDataBuffer();
161:             isDataBufferReleased = true;
162:             releaseFreeBuffers();
163:             if (currentDataBuffer != null) {
164:                 currentDataBuffer.release();
165:             }
166:         }
167:     }
168: 
169:     // ------------------------------------------------------------------------
170:     //  Internal Methods
171:     // ------------------------------------------------------------------------
172:     @GuardedBy("lock")
173:     private void switchCurrentDataBufferIfNeeded(boolean isBroadcast) {
174:         if (isBroadcast == isBroadcastDataBuffer
175:                 && currentDataBuffer != null
176:                 && !currentDataBuffer.isReleased()
177:                 && !currentDataBuffer.isFinished()) {
178:             return;
179:         }
180:         isBroadcastDataBuffer = isBroadcast;
181:         flushCurrentDataBuffer();
182:         isDataBufferReleased = true;
183:         currentDataBuffer = createNewDataBuffer();
184:         isDataBufferReleased = false;
185:     }
186: 
187:     @GuardedBy("lock")
188:     private TieredStorageSortBuffer createNewDataBuffer() {
189:         requestBuffers();
190: 
191:         // Use the half of the buffers for writing, and the other half for reading
192:         int numBuffersForSort = freeSegments.size() / 2;
193:         return new TieredStorageSortBuffer(
194:                 freeSegments,
195:                 this::recycleBuffer,
196:                 numSubpartitions,
197:                 bufferSizeBytes,
198:                 numBuffersForSort,
199:                 isPartialRecordAllowed);
200:     }
201: 
202:     @GuardedBy("lock")
203:     private void requestBuffers() {
204:         while (freeSegments.size() < totalFloatingBuffers) {
205:             Buffer buffer = requestBuffer();
206:             freeSegments.add(checkNotNull(buffer).getMemorySegment());
207:             if (bufferRecycler == null) {
208:                 bufferRecycler = buffer.getRecycler();
209:             }
210:         }
211:     }
212: 
213:     @GuardedBy("lock")
214:     private void flushDataBuffer() {
215:         if (currentDataBuffer == null
216:                 || currentDataBuffer.isReleased()
217:                 || !currentDataBuffer.hasRemaining()) {
218:             return;
219:         }
220:         currentDataBuffer.finish();
221: 
222:         do {
223:             MemorySegment freeSegment = getFreeSegment();
224:             BufferWithSubpartition bufferWithSubpartition =
225:                     currentDataBuffer.getNextBuffer(freeSegment);
226:             if (bufferWithSubpartition == null) {
227:                 break;
228:             }
229:             int numRemainingConsecutiveBuffers =
230:                     (int)
231:                             Math.ceil(
232:                                     ((double) currentDataBuffer.getRecordRemainingBytes())
233:                                             / bufferSizeBytes);
234:             flushBuffer(bufferWithSubpartition, numRemainingConsecutiveBuffers);
235:         } while (true);
236: 
237:         isDataBufferReleased = true;
238:         releaseFreeBuffers();
239:         currentDataBuffer.release();
240:     }
241: 
242:     private void flushCurrentDataBuffer() {
243:         synchronized (lock) {
244:             if (currentDataBuffer != null) {
245:                 flushDataBuffer();
246:                 currentDataBuffer = null;
247:             }
248:         }
249:     }
250: 
251:     private void writeLargeRecord(ByteBuffer record, int subpartitionId, Buffer.DataType dataType) {
252: 
253:         checkState(dataType != Buffer.DataType.EVENT_BUFFER);
254:         while (record.hasRemaining()) {
255:             int toCopy = Math.min(record.remaining(), bufferSizeBytes);
256:             MemorySegment writeBuffer = requestBuffer().getMemorySegment();
257:             writeBuffer.put(0, record, toCopy);
258: 
259:             int numRemainingConsecutiveBuffers =
260:                     (int) Math.ceil(((double) record.remaining()) / bufferSizeBytes);
261:             if (numRemainingConsecutiveBuffers == 0) {
262:                 dataType = Buffer.DataType.DATA_BUFFER_WITH_CLEAR_END;
263:             }
264: 
265:             flushBuffer(
266:                     new BufferWithSubpartition(
267:                             new NetworkBuffer(
268:                                     writeBuffer, checkNotNull(bufferRecycler), dataType, toCopy),
269:                             subpartitionId),
270:                     numRemainingConsecutiveBuffers);
271:         }
272: 
273:         releaseFreeBuffers();
274:     }
275: 
276:     private MemorySegment getFreeSegment() {
277:         synchronized (lock) {
278:             MemorySegment freeSegment = freeSegments.poll();
279:             if (freeSegment == null) {
280:                 freeSegment = requestBuffer().getMemorySegment();
281:             }
282:             return freeSegment;
283:         }
284:     }
285: 
286:     private void flushBuffer(
287:             BufferWithSubpartition bufferWithSubpartition, int numRemainingConsecutiveBuffers) {
288:         checkNotNull(accumulatedBufferFlusher)
289:                 .accept(
290:                         new TieredStorageSubpartitionId(
291:                                 bufferWithSubpartition.getSubpartitionIndex()),
292:                         bufferWithSubpartition.getBuffer(),
293:                         numRemainingConsecutiveBuffers);
294:     }
295: 
296:     private Buffer requestBuffer() {
297:         BufferBuilder bufferBuilder = memoryManager.requestBufferBlocking(this);
298:         BufferConsumer bufferConsumer = bufferBuilder.createBufferConsumerFromBeginning();
299:         Buffer buffer = bufferConsumer.build();
300:         bufferBuilder.close();
301:         bufferConsumer.close();
302:         return buffer;
303:     }
304: 
305:     private void releaseFreeBuffers() {
306:         synchronized (lock) {
307:             isDataBufferReleased = true;
308:             freeSegments.forEach(this::recycleBuffer);
309:             freeSegments.clear();
310:         }
311:     }
312: 
313:     private void recycleBuffer(MemorySegment memorySegment) {
314:         synchronized (lock) {
315:             if (!isDataBufferReleased
316:                     && currentDataBuffer != null
317:                     && !currentDataBuffer.isReleased()) {
318:                 freeSegments.add(memorySegment);
319:             } else {
320:                 checkNotNull(bufferRecycler).recycle(memorySegment);
321:             }
322:         }
323:     }
324: }
