733:     static class SinkValidatorUpdateFun
734:             implements ValidatingSink.CountUpdater<Tuple4<Long, Long, Long, IntType>> {
735: 
736:         private final int elementsPerKey;
737: 
738:         SinkValidatorUpdateFun(int elementsPerKey) {
739:             this.elementsPerKey = elementsPerKey;
740:         }
741: 
742:         @Override
743:         public void updateCount(
744:                 Tuple4<Long, Long, Long, IntType> value, Map<Long, Integer> windowCounts) {
745:             // verify the contents of that window, Tuple4.f1 and .f2 are the window start/end
746:             // the sum should be "sum (start .. end-1)"
747: 
748:             int expectedSum = 0;
749:             // we shorten the range if it goes beyond elementsPerKey, because those are "incomplete"
750:             // sliding windows
751:             long countUntil = Math.min(value.f2, elementsPerKey);
752:             for (long i = value.f1; i < countUntil; i++) {
753:                 // only sum up positive vals, to filter out the negative start of the
754:                 // first sliding windows
755:                 if (i > 0) {
756:                     expectedSum += i;
757:                 }
758:             }
759: 
760:             assertEquals(
761:                     "Window start: " + value.f1 + " end: " + value.f2, expectedSum, value.f3.value);
762: 
763:             windowCounts.merge(value.f0, 1, (val, increment) -> val + increment);
764:         }
765:     }
