712:     /** For validating the stateful window counts. */
713:     static class CountingSinkValidatorUpdateFun
714:             implements ValidatingSink.CountUpdater<Tuple4<Long, Long, Long, IntType>> {
715: 
716:         @Override
717:         public void updateCount(
718:                 Tuple4<Long, Long, Long, IntType> value, Map<Long, Integer> windowCounts) {
719: 
720:             windowCounts.merge(value.f0, 1, (a, b) -> a + b);
721: 
722:             // verify the contents of that window, the contents should be:
723:             // (key + num windows so far)
724:             assertEquals(
725:                     "Window counts don't match for key " + value.f0 + ".",
726:                     value.f0.intValue() + windowCounts.get(value.f0),
727:                     value.f3.value);
728:         }
729:     }
