771: 
772:         SinkValidatorCheckFun(int numKeys, int elementsPerKey, int elementsPerWindow) {
773:             this.numKeys = numKeys;
774:             this.numWindowsExpected = elementsPerKey / elementsPerWindow;
775:         }
776: 
777:         @Override
778:         public boolean checkResult(Map<Long, Integer> windowCounts) {
779:             if (windowCounts.size() == numKeys) {
780:                 for (Integer windowCount : windowCounts.values()) {
781:                     if (windowCount < numWindowsExpected) {
782:                         return false;
783:                     }
784:                 }
785:                 return true;
786:             }
787:             return false;
788:         }
