791:     static class KeyedEventTimeGenerator implements FailingSource.EventEmittingGenerator {
792: 
793:         private final int keyUniverseSize;
794:         private final int watermarkTrailing;
795: 
796:         public KeyedEventTimeGenerator(int keyUniverseSize, int numElementsPerWindow) {
797:             this.keyUniverseSize = keyUniverseSize;
798:             // we let the watermark a bit behind, so that there can be in-flight timers that
799:             // required checkpointing
800:             // to include correct timer snapshots in our testing.
801:             this.watermarkTrailing = 4 * numElementsPerWindow / 3;
802:         }
803: 
804:         @Override
805:         public void emitEvent(
806:                 SourceFunction.SourceContext<Tuple2<Long, IntType>> ctx, int eventSequenceNo) {
807:             final IntType intTypeNext = new IntType(eventSequenceNo);
808:             for (long i = 0; i < keyUniverseSize; i++) {
809:                 final Tuple2<Long, IntType> generatedEvent = new Tuple2<>(i, intTypeNext);
810:                 ctx.collectWithTimestamp(generatedEvent, eventSequenceNo);
811:             }
812: 
813:             ctx.emitWatermark(new Watermark(eventSequenceNo - watermarkTrailing));
814:         }
815:     }
